import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-c2-001","clusterId":"C","werkstueckRef":"C.4.3","stufe":1,"question":"Ein Gesundheitsportal wirbt: „Unser Immun-Tee stärkt Ihre Abwehr und macht eine Masernimpfung überflüssig.“ Welche Frage prüft diese Behauptung am besten?","options":["Kann ein Getränk, das die allgemeine Abwehr unterstützt, dem Körper die genaue Information über das Masernvirus liefern, die er zum Erkennen braucht?","Wie viele Menschen in meinem Umfeld trinken diesen Tee schon und fühlen sich seitdem gesünder und leistungsfähiger?","Ist der Tee aus pflanzlichen Zutaten hergestellt, die schon seit langer Zeit als bewährte Hausmittel verwendet werden?","Wirkt die Werbeaussage glaubwürdig, weil sie von einem Portal mit sehr vielen Besucherinnen und Besuchern stammt?"],"correctIndex":0,"explanation":"Die Behauptung verwechselt zwei Abwehrebenen. Die angeborene Abwehr ist schnell und grob: Sie springt auf typische Bausteine ganzer Erregergruppen an, erkennt aber nicht den einzelnen Erreger und merkt sich nichts. Die adaptive Abwehr mit B- und T-Zellen wird langsamer aktiviert, ist aber präzise und hinterlässt Gedächtniszellen, die jahrzehntelang im Körper patrouillieren. Für Masern braucht der Körper genau diese spezifische Information über den Erreger. Eine Impfung liefert sie in harmloser Form, ein allgemein „stärkendes“ Getränk kann das nicht. Die anderen Fragen prüfen Verbreitung, Tradition oder Reichweite der Quelle, aber nicht, ob die behauptete Ursache-Wirkung-Kette überhaupt möglich ist.","coreRule":"⚡ Wer eine Impfung ersetzen will, muss zeigen, wie die Maßnahme dem Körper die spezifische Information über genau diesen Erreger liefert. Allgemeine „Stärkung“ reicht dafür nicht.","beleg":"Werkstück C.4.3 (Kontext & Tiefe); Fn. gl-c-mustererkennung (Aster u. a. 2026, S. 169 und 181)","status":"entwurf","scenario":"","kurz":"Eine Impfung liefert dem Körper die spezifische Information über den Erreger, die für Masern nötig ist. Ein Tee, der die Abwehr allgemein „stärkt“, kann das nicht. Der Fehler liegt darin, schnelle, grobe Abwehr mit gezielter, gedächtnisbildender zu verwechseln.","prueffrage":"Welche Belege nennt das Portal dafür, dass Teetrinker ohne Impfung seltener an Masern erkranken?","rueckmeldung":[{"option":1,"text":"Wohlbefinden im Bekanntenkreis ist leicht zu beobachten und wirkt überzeugend. Es zeigt aber nicht, ob jemand vor Masern geschützt ist, und gerade das behauptet die Werbung. Gefühlte Fitness ersetzt keine spezifische Immunität."},{"option":2,"text":"Eine lange Tradition und pflanzliche Zutaten wirken vertrauenswürdig. Sie sagen aber nichts darüber, ob ein Getränk dem Körper den Erreger „vorstellen“ kann. Wie alt oder natürlich ein Mittel ist, beantwortet diese Frage nicht."},{"option":3,"text":"Ein Portal mit vielen Besuchern erreicht viele Menschen. Die Reichweite sagt aber nichts darüber, ob die Aussage stimmt. Entscheidend ist, ob die behauptete Wirkung überhaupt möglich ist, und das lässt sich an der Aussage selbst prüfen."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"IQWiG, gesundheitsinformation.de: Wie funktioniert das Immunsystem?","oeffentlich":true,"url":"https://www.gesundheitsinformation.de/wie-funktioniert-das-immunsystem.html","abruf":"2026-10-12"},{"typ":"url","kurz":"WHO: How do vaccines work?","oeffentlich":true,"url":"https://www.who.int/news-room/feature-stories/detail/how-do-vaccines-work","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Aster u. a. (Hrsg.) 2026, Robbins, Cotran & Kumar Pathologic Basis of Disease, 11. Aufl., Elsevier","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"c6acbfa5e8db883d"}},{"id":"qx-c2-002","clusterId":"C","werkstueckRef":"C.4.3","stufe":2,"question":"In einem Gespräch heißt es: „Gegen HIV hilft nur ein stärkeres Immunsystem, und das lässt sich über Ernährung und Lebensstil erreichen.“ Ein Arzt entgegnet, dass das Problem anderswo liegt. Welche Überlegung zeigt am besten, warum HIV die Abwehr als Ganzes zusammenbrechen lässt?","options":["Das Virus zerstört gerade die Zellen, die die gezielte Abwehr koordinieren; ohne sie laufen B- und T-Zellen ins Leere, selbst wenn alle anderen Abwehrzellen vorhanden sind.","Das Virus durchbricht gezielt die Barrieren aus Haut und Schleimhäuten; ohne sie kommt jeder Erreger ungehindert in den Körper, selbst wenn alle Abwehrzellen vorhanden sind.","Das Virus bringt die B-Zellen dazu, Antikörper gegen Körpergewebe zu bilden; ohne gezielte Abwehr gegen Erreger sind diese Antikörper wirkungslos, selbst wenn alle anderen Abwehrzellen vorhanden sind.","Das Virus löscht nur die Gedächtniszellen früherer Impfungen; ohne sie wirken Impfungen nicht mehr, selbst wenn alle anderen Abwehrzellen vorhanden sind."],"correctIndex":0,"explanation":"HIV greift gezielt die Helfer-T-Zellen an, die „Kommandozentrale“ der adaptiven Immunantwort. Diese Zellen koordinieren die gesamte Operation, also auch die B-Zellen, die Antikörper bilden, und die Killer-T-Zellen. Fällt die Kommandozentrale aus, bricht das gesamte System zusammen. HIV zerstört also nicht die Barrieren aus Haut und Schleimhäuten und löscht auch nicht nur das Gedächtnis früherer Impfungen, und es lässt B-Zellen keine Antikörper gegen Körpergewebe bilden, sondern es zerstört die koordinierenden Zellen selbst. Ein gesunder Lebensstil unterstützt die Abwehr nur allgemein; er ersetzt aber keine spezifische Immunantwort.","coreRule":"⚡ Ein System fällt nicht nur aus, wenn alles schwach ist, sondern auch, wenn sein zentraler Koordinator ausfällt. Bei HIV sind das die Helfer-T-Zellen.","beleg":"Werkstück C.4.3 (Anwendung & Relevanz, Bei AIDS & HIV)","status":"entwurf","scenario":"Bei einer HIV-Infektion sinkt die Zahl der Helfer-T-Zellen, die als Koordinatoren der gezielten (adaptiven) Abwehr arbeiten, über Jahre stark ab. Am Ende erkranken Betroffene an Infektionen, die ein gesundes Immunsystem problemlos beherrscht.","kurz":"HIV zerstört die Helfer-T-Zellen, die B- und Killer-T-Zellen koordinieren. Fällt diese Schaltstelle aus, laufen die übrigen Zellen ins Leere, und mehr Abwehrzellen oder ein gesünderer Lebensstil ersetzen die Steuerung nicht.","prueffrage":"Was zeigen Blutwerte von Menschen mit HIV über die Jahre, und ändert eine gesunde Lebensweise etwas an diesem Verlauf?","rueckmeldung":[{"option":1,"text":"Haut und Schleimhäute sind wichtige Barrieren, und über Schleimhäute kann das Virus eindringen. Der Zusammenbruch der Abwehr kommt aber nicht von ihrem Wegfall, sondern davon, dass die Helfer-T-Zellen schwinden, die die gezielte Abwehr steuern."},{"option":2,"text":"Antikörper gegen Körpergewebe wären eine Fehlsteuerung der Abwehr, erklären aber nicht, warum Erreger nicht mehr beherrscht werden. Der Zusammenbruch kommt daher, dass die Helfer-T-Zellen schwinden, die die gezielte Abwehr koordinieren."},{"option":3,"text":"Ein Verlust des Impfschutzes würde nur einen Teil der Abwehr treffen und erklärt nicht, warum Infektionen auftreten, die ein gesundes Immunsystem problemlos beherrscht. HIV schädigt die koordinierenden Zellen insgesamt, nicht nur das Impfgedächtnis."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"MSD Manual (Consumer Version): Human Immunodeficiency Virus (HIV) Infection","oeffentlich":true,"url":"https://www.msdmanuals.com/home/infections/human-immunodeficiency-virus-hiv-infection/human-immunodeficiency-virus-hiv-infection","abruf":"2026-10-12"},{"typ":"url","kurz":"CDC: About HIV","oeffentlich":true,"url":"https://www.cdc.gov/hiv/about/index.html","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"1e27c063a168b849"}},{"id":"qx-c2-003","clusterId":"C","werkstueckRef":"C.4.3","stufe":3,"question":"Was ist an diesem Argument fehlerhaft, und wo wird aus einer an sich vernünftigen Sorge um die eigene Abwehr ein Risiko?","scenario":"In einem Forum steht: „Impfungen überlasten das Immunsystem. Stärk lieber deine Abwehr mit gesunder Ernährung, viel Schlaf und einem Immun-Tee, dann brauchst du keine Impfung.“","options":["Allgemeine Stärkung ersetzt nicht die spezifische Information über einen bestimmten Erreger; riskant wird es, wenn das vage Stärken gegen die Impfung ausgespielt wird.","Ernährung und Schlaf haben auf die Abwehr keinen messbaren Einfluss; riskant wird es, wenn jemand sie trotzdem empfiehlt und dadurch Zeit verliert.","Eine Impfung belastet die Abwehr tatsächlich so stark, dass sie nur bei widerstandsfähigen Menschen sinnvoll ist; riskant wird es, wenn alle anderen sie erhalten.","Der Tee wirkt nicht, weil er nur die angeborene, nicht die erworbene Abwehr anspricht; riskant wird es erst, wenn zusätzlich Antibiotika abgelehnt werden."],"correctIndex":0,"explanation":"Ein gesunder Lebensstil unterstützt die allgemeine Funktion des Immunsystems, Ernährung und Schlaf sind also nicht wirkungslos. Aber weder Tee noch Schlaf noch Diät können ihm die spezifische Information geben, einen bestimmten Erreger wie Masern oder Tetanus zu erkennen. Genau das leistet eine Impfung: Sie zeigt dem Immunsystem ein harmloses Erkennungsmerkmal (ein Antigen), sodass es Gedächtniszellen aufbaut, ohne die echte Gefahr zu erleben. Der Überlastungs-Einwand trägt nicht, denn das Immunsystem begegnet täglich tausenden Antigenen. Die Sorge um die eigene Abwehr kippt nicht erst, wenn zusätzlich Antibiotika abgelehnt werden, sondern schon, wo sie gegen die Impfung ausgespielt wird: Dann drohen vermeidbare Erkrankungen, und gegen Viren wie Masern helfen Antibiotika ohnehin nicht.","coreRule":"⚡ Wer nur die allgemeine Abwehr stärkt, hat noch keine Information über den bestimmten Feind.","quote":"Die allgemeine Sorge um ein gesundes Immunsystem ist positiv.","quoteLabel":"Merksatz:","beleg":"Werkstück C.4.3 (Anwendung & Relevanz; Red Flags; Der Kipppunkt)","status":"entwurf","kurz":"Ein gesunder Lebensstil stützt die Abwehr allgemein, kann ihr aber nicht beibringen, einen bestimmten Erreger zu erkennen; genau das leistet die Impfung. Zum Risiko wird die Sorge, wenn diese allgemeine Stärkung gegen die Impfung ausgespielt wird.","prueffrage":"Welche Belege nennt der Forumsbeitrag für seine beiden Behauptungen?","rueckmeldung":[{"option":1,"text":"Dass Schlaf und Ernährung nichts bewirken, trifft nicht zu: Sie unterstützen die allgemeine Abwehrfunktion. Der Fehler liegt woanders, nämlich darin, diese Stärkung gegen die Impfung auszuspielen."},{"option":2,"text":"Überlastung wirkt plausibel, weil eine Impfung die Abwehr tatsächlich beansprucht. Das Immunsystem begegnet aber täglich tausenden fremden Erkennungsmerkmalen; eine Impfung fällt da kaum ins Gewicht und ist nicht nur für Robuste sinnvoll."},{"option":3,"text":"Richtig ist, dass ein Tee keine spezifische Immunität aufbaut. Riskant wird es aber nicht erst, wenn Antibiotika abgelehnt werden, sondern schon, wenn die Impfung wegfällt; gegen Viren wie Masern helfen Antibiotika ohnehin nicht."}],"familie":"mechanismus-verlangen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"WHO: How do vaccines work?","oeffentlich":true,"url":"https://www.who.int/news-room/feature-stories/detail/how-do-vaccines-work","abruf":"2026-10-12"},{"typ":"url","kurz":"Offit u. a. 2002, Addressing parents' concerns: do multiple vaccines overwhelm or weaken the infant's immune system?, Pediatrics 109(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1542/peds.109.1.124","url":"https://pubmed.ncbi.nlm.nih.gov/11773551/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"7c491ea735328570"}},{"id":"qx-c2-004","clusterId":"C","werkstueckRef":"C.4.3","stufe":4,"question":"Wie lässt sich Jenners Rolle angesichts dieser Hinweise am treffendsten beschreiben?","scenario":"Im Geschichtsunterricht heißt es: „Edward Jenner hat 1796 die Impfung erfunden.“ Du recherchierst nach und findest zwei Hinweise: Ein Bauer namens Benjamin Jesty hatte seine Familie schon 1774 mit Kuhpocken geimpft. Außerdem wurde in Europa seit Jahrzehnten mit echtem Pockenmaterial geimpft (Variolation), was gelegentlich selbst Pocken auslöste.","options":["Er war der Erste, der den Schutz durch Kuhpocken überhaupt bemerkte, und er erklärte auch schon, wie Antikörper und Gedächtniszellen dabei wirken.","Er war der Erste, der Kuhpocken zum Impfen verwendete; zuvor hatte man in Europa ausschließlich mit Menschenpocken-Material geimpft.","Er prüfte ein bereits praktiziertes Verfahren systematisch, veröffentlichte die Ergebnisse und trug wesentlich zu seiner Verbreitung bei.","Er führte die erste Studie mit Kontrollgruppe durch, in der alle Beteiligten zuvor über die Risiken aufgeklärt wurden."],"correctIndex":2,"explanation":"Der Satz „X hat Y erfunden“ behauptet eine Priorität, und die lässt sich prüfen: Jesty impfte schon 1774 mit Kuhpocken, und die Variolation mit echtem Pockenmaterial war seit Jahrzehnten verbreitet. Damit fällt „erster Anwender“ weg. Jenners Leistung liegt in einem anderen Schritt: Er prüfte das Verfahren systematisch, veröffentlichte seine Ergebnisse 1798 und warb unermüdlich dafür; Antikörper und Gedächtniszellen kannte er nicht, diese Mechanismen wurden erst viel später verstanden. Auch „als Erster wissenschaftlich geprüft“ wäre wieder eine Prioritätsbehauptung, die eigene Belege bräuchte. Bei Erfindungsgeschichten lohnt sich deshalb die Frage, was genau jemand getan hat: ausprobiert, belegt oder bekannt gemacht.","coreRule":"⚡ Bei Erfindungsmythen genau fragen, was jemand als Erster getan hat: Wer ein Verfahren zuerst benutzt, hat es noch nicht zuerst geprüft.","beleg":"Werkstück C.4.3 (Die Melkerinnen und die Pocken); Fn. gl-c-jenner (Jenner 1798; Riedel 2005, S. 22, 23 und 25)","status":"entwurf","kurz":"Wer „X hat Y erfunden“ sagt, behauptet eine Priorität, und die lässt sich prüfen: Angewendet wurde das Verfahren schon vor Jenner. Seine Leistung war ein anderer Schritt: Er prüfte es systematisch, veröffentlichte die Ergebnisse und warb für seine Verbreitung.","prueffrage":"Was genau tat Jenner 1796 und in den Jahren danach, und was davon ist durch Quellen belegt?","rueckmeldung":[{"option":0,"text":"Gleich zwei Punkte tragen hier nicht: Den Schutz durch Kuhpocken nutzte Jesty schon 1774, und Antikörper und Gedächtniszellen waren Jenner unbekannt, ihre Mechanismen wurden erst viel später verstanden."},{"option":1,"text":"Dass man in Europa lange mit Menschenpocken-Material impfte, stimmt. Der erste Anwender von Kuhpocken war Jenner aber nicht: Jesty impfte seine Familie schon 1774, also gut zwanzig Jahre früher."},{"option":3,"text":"Jenners Verdienst liegt tatsächlich im Prüfen und Belegen. Eine Studie mit Kontrollgruppe und Aufklärung aller Beteiligten über Risiken führte er aber nicht durch; solche Standards setzten sich erst viel später durch."}],"familie":"zitat-am-original-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Riedel 2005, Edward Jenner and the History of Smallpox and Vaccination, Baylor Univ Med Cent Proc 18(1) (PMC1200696)","oeffentlich":true,"doi":"10.1080/08998280.2005.11928028","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Jenner 1798, An Inquiry into the Causes and Effects of the Variolæ Vaccinæ, London: Sampson Low","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"f0220cab773cb947"}},{"id":"qx-c2-005","clusterId":"C","werkstueckRef":"C.4.4","stufe":1,"question":"Welche Antwort prüft die Behauptung am besten, ein Mittel „heile Krebs“?","options":["Die Behauptung ist unplausibel, weil Krebs hunderte verschiedene Krankheiten mit je eigenen Mutationen umfasst, sodass ein einziges Mittel für alle kaum denkbar ist.","Die Behauptung ist unplausibel, weil Krebs von außen eindringende Fremdzellen sind, die sich nur mit einem einzigen Spezialwirkstoff bekämpfen lassen.","Die Behauptung ist plausibel, weil Krebs eine einzelne Krankheit mit einer Hauptursache ist, für die es folglich auch eine einzige Heilung geben kann.","Die Behauptung ist plausibel, weil Krebs durch Übersäuerung entsteht und sich mit einem einzigen natürlichen Mittel gezielt entsäuern lässt."],"correctIndex":0,"explanation":"Unter „Krebs“ fallen hunderte verschiedene Krankheiten. Lungenkrebs verhält sich völlig anders als Hautkrebs, und jeder Tumor hat eine eigene genetische Signatur, denn Krebs entsteht, wenn körpereigene Zellen durch Mutationen in ihrer DNA die Kontrolle über Wachstum und Teilung verlieren. Schon deshalb ist die Idee „eines“ Heilmittels für alle Krebsarten biologisch unplausibel; moderne Therapien zielen auf die spezifischen Mutationen des jeweiligen Tumors. Die Verschwörungserzählung ersetzt diese Überlegung durch eine bequeme Schuldzuweisung. Die beiden anderen falschen Antworten teilen denselben Kernfehler: Sie behandeln Krebs als einheitliches Phänomen mit einer einzigen Ursache. Krebszellen sind außerdem keine Eindringlinge, sondern körpereigene Zellen, und die Übersäuerungsthese hat keine molekularbiologische Grundlage.","coreRule":"⚡ Krebs ist keine einzelne Krankheit, sondern hunderte; ein einziges Wundermittel für alle ist biologisch unplausibel.","beleg":"Werkstück C.4.4 (Kernidee; Kontext & Tiefe; Red Flags)","status":"entwurf","scenario":"Ein Beitrag im Netz verspricht: „Dieses natürliche Mittel heilt Krebs, doch die Pharmaindustrie unterdrückt es.“ Du willst herausfinden, ob die Behauptung biologisch überhaupt plausibel ist.","kurz":"Unter „Krebs“ fallen hunderte verschiedene Krankheiten, jeder Tumor hat eigene Mutationen. Ein Mittel für alle ist deshalb biologisch kaum denkbar. Der Denkfehler: Krebs wie eine einzige Krankheit mit einer Ursache zu behandeln.","prueffrage":"Gleichen sich Lungenkrebs und Hautkrebs in Ablauf und Behandlung, oder unterscheiden sie sich deutlich?","rueckmeldung":[{"option":1,"text":"Unplausibel ist die Behauptung tatsächlich, nur trägt die Begründung nicht: Krebszellen sind keine Eindringlinge, sondern körpereigene Zellen mit Mutationen, und weil diese von Tumor zu Tumor verschieden sind, hilft kein einzelner Spezialwirkstoff."},{"option":2,"text":"Eine einzige Krankheit mit einer Hauptursache würde eine einzige Heilung nahelegen. Krebs ist aber ein Sammelbegriff für hunderte Krankheiten, und jeder Tumor hat eine eigene genetische Signatur; das macht ein Universalmittel unplausibel."},{"option":3,"text":"Säure als einfache Ursache mit natürlichem Gegenmittel ist eingängig. Die Übersäuerungsthese hat aber keine molekularbiologische Grundlage: Krebs entsteht durch Mutationen in der DNA körpereigener Zellen, und die sind je nach Tumor verschieden."}],"familie":"genau-unterscheiden","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"National Cancer Institute: What Is Cancer?","oeffentlich":true,"url":"https://www.cancer.gov/about-cancer/understanding/what-is-cancer","abruf":"2026-10-12"},{"typ":"url","kurz":"Krebsinformationsdienst (DKFZ): Ernährungsmythen bei Krebs (2016)","oeffentlich":true,"url":"https://www.krebsinformationsdienst.de/aktuelles/detail/ernaehrungsmythen-bei-krebs","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"cfb3471f73e8b468"}},{"id":"qx-c2-006","clusterId":"C","werkstueckRef":"C.4.4","stufe":2,"question":"Welche Antwort prüft die Behauptung am besten und liegt in der Sache richtig?","scenario":"Im Netz kursiert: „Man kann einen Tumor einfach aushungern oder entsäuern – mit der richtigen Diät.“ Eine Bekannte, deren Mutter an Krebs erkrankt ist, überlegt deshalb, die Behandlung zugunsten einer strengen Diät aufzuschieben.","options":["Ernährung kann das Erkrankungsrisiko beeinflussen, aber kein Ernährungsplan hungert einen bereits bestehenden Tumor aus oder „entsäuert“ ihn; er kann die Behandlung höchstens begleiten, nicht ersetzen.","Weil Tumoren viel Zucker verbrauchen, genügt eine strenge, lange durchgehaltene Diät, um sie auszuhungern; die Behandlung kann dann ruhig warten.","Ernährung hat auf Krebs überhaupt keinen Einfluss; weder das Risiko einer Erkrankung noch der Verlauf hängt davon ab, was man isst, daher ist jede Diät sinnlos.","Krebszellen reagieren besonders empfindlich auf Säure; eine konsequent basische Ernährung kann den Tumor deshalb zurückdrängen, und die Behandlung kann später folgen."],"correctIndex":0,"explanation":"Eine gesunde Ernährung kann das Krebsrisiko senken, doch ein bereits bestehender, durch Mutationen veränderter Tumor lässt sich nicht gezielt „aushungern“ oder „entsäuern“. Krebszellen sind anpassungsfähige Überlebenskünstler und finden immer einen Weg, sich zu ernähren. Ebenso verdächtig sind Theorien, die „den“ Krebs als eine einzige Krankheit mit einer einzigen Ursache und Heilung darstellen. Gefährlich wird so ein Ansatz, wenn er eine medizinische Behandlung ersetzt oder verzögert, denn bei Krebs entscheidet oft die Zeit zwischen heilbar und unheilbar. Die Behauptung, Krebs werde durch „Übersäuerung“ verursacht, ist ein klares Warnsignal für Krebs-Unsinn.","coreRule":"⚡ Ernährung kann das Risiko beeinflussen, aber sie heilt keinen bestehenden, mutierten Tumor. Wer sie als Ersatz für eine Behandlung anbietet, gefährdet Leben.","beleg":"Werkstück C.4.4 (Anwendung & Relevanz, Gegen „Krebs-Diäten“ & „Entgiftungs“-Mythen; Red Flags)","status":"entwurf","kurz":"Ernährung kann das Risiko beeinflussen, aber einen bestehenden Tumor weder aushungern noch entsäuern; die Zellen sind anpassungsfähig. Gefährlich wird die Diät, wenn sie die Behandlung ersetzt oder verzögert, denn bei Krebs entscheidet oft die Zeit.","prueffrage":"Gibt es Studien an Krebskranken, in denen eine Diät allein Tumoren verkleinert hat, und wer hat sie durchgeführt?","rueckmeldung":[{"option":1,"text":"Dass Tumorzellen viel Zucker verbrauchen, stimmt und lässt „Aushungern“ plausibel klingen. Die Zellen finden aber andere Wege, sich zu versorgen, und eine aufgeschobene Behandlung kann Zeit kosten, die über heilbar oder unheilbar entscheidet."},{"option":2,"text":"Daran stimmt, dass eine Diät einen bestehenden Tumor nicht beseitigt. Der Schluss, Ernährung habe nie Einfluss, geht aber zu weit: Eine gesunde Ernährung kann das Erkrankungsrisiko senken und die Behandlung begleiten. Sie ersetzt sie nur nicht."},{"option":3,"text":"Säure als Ursache und basische Kost als Gegenmittel wirken einfach und natürlich. Der Körper hält den Säuregrad des Blutes aber in engen Grenzen, eine Diät entsäuert keinen Tumor; wer dafür die Behandlung aufschiebt, verliert wertvolle Zeit."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Krebsinformationsdienst (DKFZ): Diäten bei Krebs","oeffentlich":true,"url":"https://www.krebsinformationsdienst.de/ernaehrung-bei-krebs/krebsdiaeten","abruf":"2026-10-12"},{"typ":"url","kurz":"Krebsinformationsdienst (DKFZ): Ernährungsmythen bei Krebs (2016)","oeffentlich":true,"url":"https://www.krebsinformationsdienst.de/aktuelles/detail/ernaehrungsmythen-bei-krebs","abruf":"2026-10-12"},{"typ":"url","kurz":"Johnson u. a. 2018, Use of Alternative Medicine for Cancer and Its Impact on Survival, J Natl Cancer Inst 110(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1093/jnci/djx145","url":"https://pubmed.ncbi.nlm.nih.gov/28922780/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"53896b83eab33431"}},{"id":"qx-c2-007","clusterId":"C","werkstueckRef":"C.4.4","stufe":3,"question":"Warum ist genau dieser Vorschlag gefährlich, obwohl Ernährung und Entspannung an sich nützlich sein können?","options":["Weil Ernährung und Entspannung die Wirkung einer Chemotherapie grundsätzlich abschwächen, sobald beides zusammen angewandt wird.","Weil Maßnahmen, die Nebenwirkungen der Behandlung lindern, den Tumor angeblich weniger stark bekämpfen lassen.","Weil jede Gewohnheit, die länger als einige Monate durchgehalten wird, die Krebszellen zur Anpassung und Resistenz zwingt.","Weil das Programm die Therapie ersetzen soll und der Patient so wertvolle Zeit verliert."],"correctIndex":3,"explanation":"Der Fehler liegt nicht in der Begleitung, sondern im Ersatz. Ein gesunder Lebensstil und psychologische Unterstützung können eine Krebstherapie sinnvoll ergänzen. Gefährlich wird es, wenn sie an die Stelle der Behandlung treten: Keine Diät kann einen bereits existierenden, genetisch mutierten Tumor aushungern, und wer stattdessen wartet, verliert wertvolle Zeit. Bei Krebs ist Zeit oft ein entscheidender Faktor, eine Verzögerung kann den Unterschied zwischen heilbar und unheilbar bedeuten. Die anderen Begründungen erfinden Wirkungen, die es nicht gibt: Ergänzende Maßnahmen schwächen die Therapie nicht pauschal ab, und eine Linderung von Nebenwirkungen lässt den Tumor nicht unbehandelt wachsen. Ebenso wenig zwingt eine Gewohnheit die Krebszellen allein durch ihre Dauer zur Resistenz. Resistenzen entstehen durch Selektion: Zellen, die Therapien am besten widerstehen, überleben und vermehren sich.","coreRule":"⚡ Begleiten ist erlaubt, ersetzen ist der Kipppunkt – bei Krebs zählt jede Verzögerung.","beleg":"Werkstück C.4.4 (Der Kipppunkt; Red Flags)","status":"entwurf","scenario":"Ein Patient hat gerade die Diagnose Krebs erhalten. Die Ärztin empfiehlt eine Operation mit anschließender Chemotherapie. Eine Anbieterin von „ganzheitlicher Krebsberatung“ sagt zu ihm: „Mit meinem Ernährungs- und Entspannungsprogramm brauchst du die Operation und die Chemotherapie nicht. Warte erst einmal ab, wie es wirkt.“","quote":"","quoteLabel":"","kurz":"Gefährlich ist nicht das Programm selbst, sondern dass es die Behandlung ersetzen soll. Wer abwartet, statt sich behandeln zu lassen, verliert Zeit, und bei Krebs kann eine Verzögerung über heilbar oder unheilbar entscheiden.","prueffrage":"Was verspricht die Anbieterin genau, und auf welche Belege für die Wirkung ihres Programms bei Tumoren stützt sie sich?","rueckmeldung":[{"option":0,"text":"Die Sorge, Zusätzliches könne die Therapie stören, liegt nahe. Ernährung und Entspannung schwächen eine Chemotherapie aber nicht grundsätzlich ab; gefährlich ist hier, dass das Programm die Behandlung ersetzen soll."},{"option":1,"text":"Dass eine Behandlung nur wirkt, wenn sie spürbar zusetzt, liegt nahe, weil Wirkung und Nebenwirkungen bei der Chemotherapie oft zusammen auftreten. Den Tumor bekämpft aber die Therapie selbst, gelinderte Beschwerden schwächen sie nicht."},{"option":2,"text":"Resistenz ist ein reales Phänomen, deshalb wirkt „Anpassung“ plausibel. Sie entsteht aber durch Selektion unter Therapie, nicht durch lange durchgehaltene Gewohnheiten, und mit der Gefahr dieses Vorschlags hat das nichts zu tun."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Krebsinformationsdienst (DKFZ): Diäten bei Krebs","oeffentlich":true,"url":"https://www.krebsinformationsdienst.de/ernaehrung-bei-krebs/krebsdiaeten","abruf":"2026-10-12"},{"typ":"url","kurz":"Johnson u. a. 2018, Use of Alternative Medicine for Cancer and Its Impact on Survival, J Natl Cancer Inst 110(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1093/jnci/djx145","url":"https://pubmed.ncbi.nlm.nih.gov/28922780/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Greaves & Maley 2012, Clonal evolution in cancer, Nature 481 (PMC3367003)","oeffentlich":true,"doi":"10.1038/nature10762","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"195f46467fe75f0b"}},{"id":"qx-c2-008","clusterId":"C","werkstueckRef":"C.4.4","stufe":4,"question":"Eine Patientin liest: „Der Tumor sprach auf die Chemotherapie zunächst gut an, ist nach einem Jahr aber trotz unveränderter Behandlung wieder gewachsen.“ Sie fragt, ob die Therapie von Anfang an gelogen war. Welche Erklärung ist die sparsamste?","options":["Unter der Therapie überleben vor allem Zellen, die sie besser vertragen. Sie vermehren sich weiter, und der Tumor besteht bald überwiegend aus ihren Nachkommen.","Alle Zellen des Tumors sind genetisch identisch. Übersteht eine einzige die Therapie, ist damit sofort der gesamte Tumor dauerhaft gegen sie immun.","Das Immunsystem hält die entarteten Zellen weiterhin für körpereigen. Deshalb schützt es sie gezielt vor der Behandlung und lässt den Tumor wieder wachsen.","Die Therapie verwandelt gesunde Zellen in widerstandsfähige Krebszellen. Je länger sie angewendet wird, desto mehr solcher Zellen entstehen im Gewebe."],"correctIndex":0,"explanation":"Ein Tumor ist keine einheitliche Masse, sondern ein Gemisch aus Zellen mit leicht unterschiedlichen Mutationen, die um Platz und Nährstoffe konkurrieren. Eine Therapie wirkt wie ein Filter: Zellen, die sie schlechter vertragen, sterben, und die Zellen, die sie besser überstehen, vermehren sich weiter. Das ist natürliche Selektion im Kleinen, und sie erklärt den Rückfall ohne Zusatzannahmen; die Behandlung war also nicht „gelogen“, sie hat die empfindlichen Zellen tatsächlich getroffen. Wären dagegen alle Zellen identisch, gäbe es nichts, worauf Selektion wirken könnte, und dass das Immunsystem Tumorzellen gezielt vor der Behandlung schützt, ist unbelegt. Manche Chemotherapien können zwar Jahre später einen Zweittumor begünstigen, doch das wäre ein neuer Krebs und erklärt nicht, warum derselbe Tumor wieder wächst.","coreRule":"⚡ Ein Tumor ist Evolution im Kleinen: Was die Therapie überlebt, vermehrt sich – und der Rückfall ist dann kein Widerspruch, sondern genau das, was man erwarten muss.","beleg":"Werkstück C.4.4 (Kontext & Tiefe, Krebs ist Evolution im eigenen Körper)","status":"entwurf","scenario":"Ein erkennbarer Tumor besteht meist aus Milliarden Zellen, die sich bei jeder Teilung leicht verändern können. Eine Therapie tötet nicht alle diese Zellen gleich gut.","kurz":"Der Tumor ist ein Gemisch verschiedener Zellen: Die Therapie tötete die empfindlichen, während die widerstandsfähigeren überlebten und sich weiter vermehrten. So wächst er zurück, obwohl die Behandlung anfangs wirklich wirkte.","prueffrage":"Sprechen die Zellen, die nach einem Jahr wachsen, noch genauso auf das Mittel an wie die Zellen zu Beginn?","rueckmeldung":[{"option":1,"text":"Dass eine überlebende Zelle genügt, wirkt wie eine einfache Erklärung. Zellen, die sich bei jeder Teilung leicht verändern können, sind aber nicht identisch, und gerade diese Unterschiede ermöglichen die Auslese."},{"option":2,"text":"Tumorzellen können sich der Immunabwehr zwar mitunter entziehen. Dass das Immunsystem sie aber gezielt vor der Behandlung schützt, ist eine unbelegte Zusatzannahme, die für den Rückfall gar nicht nötig ist."},{"option":3,"text":"Eine Therapie, die aus gesunden Zellen neue Krebszellen macht, wäre für den Rückfall eine unnötige Zusatzannahme. Es genügt, dass unter den vorhandenen Tumorzellen manche die Behandlung besser überstehen und sich weiter vermehren."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Greaves & Maley 2012, Clonal evolution in cancer, Nature 481 (PMC3367003)","oeffentlich":true,"doi":"10.1038/nature10762","abruf":"2026-10-12"},{"typ":"url","kurz":"National Cancer Institute: What Is Cancer?","oeffentlich":true,"url":"https://www.cancer.gov/about-cancer/understanding/what-is-cancer","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"dfa4f88ebf002347"}},{"id":"qx-c2-009","clusterId":"C","werkstueckRef":"C.4.5","stufe":1,"question":"Was ist an dem Schluss der Mitprobandin fehlerhaft, und was erklärt deine Beschwerden am besten?","scenario":"In einer Medikamentenstudie klärt dich eine Ärztin ausführlich über mögliche Nebenwirkungen des Prüfmittels auf. Kurz nach der Einnahme bekommst du Kopfschmerzen und Übelkeit. Später wird bekannt, dass du zur Placebo-Gruppe gehörtest und nur eine wirkstofffreie Tablette erhalten hast. Eine Mitprobandin sagt: „Dann hast du dir die Beschwerden nur eingebildet.“","options":["Der Schluss ist richtig: Ohne Wirkstoff kann die Tablette keine echten Symptome auslösen, denn die Beschwerden waren dann vorgetäuscht.","Der Schluss ist fehlerhaft: Aus „kein Wirkstoff“ folgt nicht „keine echten Beschwerden“, denn negative Erwartungen können reale Symptome auslösen.","Der Schluss ist fehlerhaft: Die Beschwerden hatten eine andere zufällige Ursache, denn Kopfschmerz und Übelkeit sind häufige Zufallsbeschwerden ohne Bezug zur Studie.","Der Schluss ist fehlerhaft: Die Tablette enthielt Spuren des Wirkstoffs, denn wirkstofffreie Tabletten sind in der Praxis meist leicht verunreinigt."],"correctIndex":1,"explanation":"Die Mitprobandin vermischt zwei Dinge: „ohne Wirkstoff“ und „ohne echte Wirkung“. Wer über mögliche Nebenwirkungen aufgeklärt wird, verspürt mit höherer Wahrscheinlichkeit genau diese, auch wenn er nur eine Scheinbehandlung bekommt; das heißt Nocebo-Effekt, das Gegenstück zum Placebo. Negative Erwartungen können zum Beispiel die Stressachse des Körpers anregen (vgl. Colloca & Barsky 2020, New England Journal of Medicine). Die Symptome sind also real; ihr Auslöser ist die Erwartung, nicht ein Wirkstoff. Ein zufälliges Zusammentreffen ist nie ganz ausgeschlossen, doch die Abfolge aus ausführlicher Aufklärung, Einnahme und Beschwerden kurz danach passt besser zur Erwartung, und für einen Wirkstoffrest in einer wirkstofffreien Tablette spricht nichts.","coreRule":"⚡ Erwartung wirkt in beide Richtungen: Placebo bessert, Nocebo belastet. „Kein Wirkstoff“ heißt nicht „keine echten Symptome“.","beleg":"Werkstück C.4.5 (Kernidee; Kontext & Tiefe); Fn. gl-c-colloca (Colloca/Barsky 2020, NEJM 382, S. 554–561)","status":"entwurf","kurz":"Fehlender Wirkstoff heißt nicht, dass die Beschwerden unecht sind: Wer über Nebenwirkungen aufgeklärt wird, erlebt sie häufiger auch ohne Wirkstoff, weil negative Erwartung reale Symptome auslösen kann (Nocebo-Effekt).","prueffrage":"Was hat die Ärztin vor der Einnahme erklärt, und welche Beschwerden traten kurz danach auf?","rueckmeldung":[{"option":0,"text":"Richtig ist, dass die Tablette keinen Wirkstoff enthielt. Daraus folgt aber nicht, dass die Beschwerden vorgetäuscht waren: Erwartung allein kann echte Symptome erzeugen, und genau diesen Schritt überspringt der Satz."},{"option":2,"text":"Kopfschmerz und Übelkeit treten tatsächlich auch zufällig auf. Hier gingen aber eine ausführliche Aufklärung über Nebenwirkungen und die Einnahme direkt voraus, und das passt eher zu einer negativen Erwartung als zu bloßem Zufall."},{"option":3,"text":"Eine Verunreinigung ist denkbar, hier aber durch nichts gestützt: Die Tablette war ausdrücklich wirkstofffrei, und dass Placebos meist verunreinigt seien, trifft nicht zu. Für die Beschwerden braucht es keinen Wirkstoffrest."}],"familie":"fair-testen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Häuser, Hansen & Enck 2012, Nocebo phenomena in medicine: their relevance in everyday clinical practice, Dtsch Arztebl Int 109(26) (PMC3401955)","oeffentlich":true,"doi":"10.3238/arztebl.2012.0459","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Colloca & Barsky 2020, Placebo and Nocebo Effects, New England Journal of Medicine 382(6)","oeffentlich":false,"doi":"10.1056/NEJMra1907805"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"6bce6a7f3ddee3da"}},{"id":"qx-c2-010","clusterId":"C","werkstueckRef":"C.4.5","stufe":2,"question":"Was folgt aus der Umfrage des Herstellers für seine Behauptung?","scenario":"Ein Hersteller wirbt: „Unsere blaue Tablette beruhigt nachweislich stärker als die rote.“ Als Beleg nennt er eine Umfrage, in der Testpersonen die blaue Tablette beruhigender fanden und sie sich nach der Einnahme ruhiger fühlten. Wirkstoff und Dosis beider Tabletten sind laut Hersteller identisch.","options":["Sie zeigt nur, dass die Farbe Erwartungen weckt; ob sie die tatsächliche Wirkung verändert, bleibt offen.","Sie belegt, dass die Farbe die tatsächliche Wirkung verändert, denn die Testpersonen fühlten sich nach der blauen Tablette ruhiger.","Sie widerlegt den Einfluss der Farbe auf die Wirkung, denn bei identischem Wirkstoff und identischer Dosis kann es keine Unterschiede im Empfinden geben.","Sie sagt nichts über die Farbe aus, denn Erwartungen beeinflussen bei Tabletten das Empfinden der Einnehmenden nicht."],"correctIndex":0,"explanation":"Schon die Farbe einer Pille prägt die Erwartung: Blau und Grün verbinden Menschen eher mit einer beruhigenden Wirkung. Wer eine blaue Tablette für beruhigend hält und sie dann einnimmt, fühlt sich deshalb oft tatsächlich ruhiger. Das ist ein Erwartungseffekt, der durch Symbolik und Kontext entsteht. Die Umfrage erfasst nur das Empfinden der Testpersonen. Ob die Farbe auch die tatsächliche Wirkung verändert, ist weniger klar: In einem Überblick über zwölf Studien (de Craen u. a. 1996) fielen die Befunde zur Wirksamkeit uneinheitlich aus. Der Schluss von „fühlt sich beruhigender an“ auf „wirkt stärker“ ist deshalb nicht gedeckt, ebenso wenig der Schluss, die Farbe habe gar keinen Einfluss auf das Empfinden.","coreRule":"⚡ Wer nur das Empfinden nach einer Behandlung erfasst, misst auch die Erwartung mit. Ob ein Merkmal wie die Pillenfarbe die Wirkung selbst verändert, zeigt erst ein verblindeter Vergleich.","beleg":"Werkstück C.4.5 (Kontext & Tiefe, Die Symbolik); Fn. gl-c-pillenfarbe (de Craen u. a. 1996, BMJ 313, S. 1624–1626)","status":"entwurf","kurz":"Die Umfrage erfasst nur, wie sich die Testpersonen fühlen, und das kann allein die Erwartung zur Farbe erklären. Von „fühlt sich beruhigender an“ auf „wirkt stärker“ zu schließen, ist daher nicht gedeckt; ob die Farbe die Wirkung ändert, bleibt offen.","prueffrage":"Wer hat in der Umfrage was angegeben, und gab es daneben eine Messung, die nicht von den Testpersonen selbst stammt?","rueckmeldung":[{"option":1,"text":"Dass sich die Testpersonen ruhiger fühlten, ist ein echtes Ergebnis. Es zeigt aber nur das Empfinden, nicht die tatsächliche Wirkung, und die Befunde dazu sind uneinheitlich. Der Schluss auf eine veränderte Wirkung ist nicht gedeckt."},{"option":2,"text":"Bei gleichem Wirkstoff und gleicher Dosis ist ein pharmakologischer Unterschied tatsächlich nicht zu erwarten. Das Empfinden kann trotzdem abweichen, weil die Farbe Erwartungen weckt, und auch ob sie die Wirkung ändert, ist offen statt widerlegt."},{"option":3,"text":"Die Umfrage sagt durchaus etwas aus: Die Farbe prägt die Erwartung, und wer eine Tablette für beruhigend hält, fühlt sich nach der Einnahme oft ruhiger. Offen bleibt nur, ob sich auch die tatsächliche Wirkung ändert."}],"familie":"fair-testen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"de Craen u. a. 1996, Effect of colour of drugs: systematic review of perceived effect of drugs and of their effectiveness, BMJ 313 (PMC2359128)","oeffentlich":true,"doi":"10.1136/bmj.313.7072.1624","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"2cf2398d22f702ac"}},{"id":"qx-c2-011","clusterId":"C","werkstueckRef":"C.4.5","stufe":3,"question":"In einem Vortrag heißt es: „Ein Patient mit orangengroßen Tumoren bekam eine Spritze mit einem angeblichen Wundermittel, die Tumoren verschwanden. Später erfuhr er, dass das Mittel wertlos sei, und der Krebs kam zurück. Glaube kann also Tumoren schmelzen lassen.“ Was ist der entscheidende Haken an diesem Beleg?","options":["Der Fall ist erfunden, weil kein behandelnder Arzt ihn je schriftlich bestätigt hat.","Das Mittel wurde später doch als wirksam anerkannt, daher beweist der Fall nichts über Erwartung.","Placebo-Wirkungen zeigen sich vor allem bei objektiv messbaren Größen wie Tumorgrößen, der Bericht ist also plausibel.","Es ist ein einzelner, nachträglicher Bericht ohne Vergleichsgruppe, der Spontanverläufe und Erinnerungsfehler nicht ausschließt."],"correctIndex":3,"explanation":"Ein einzelner, nachträglich aufgeschriebener Fall ohne Vergleichsgruppe kann nicht zeigen, was die Ursache war. Spontane Verläufe, Fehldiagnosen und Erinnerungsfehler passen genauso zur Geschichte wie ein Erwartungseffekt, und ob sich alles so zugetragen hat, lässt sich gar nicht prüfen. Dazu kommt der Abgleich mit der Datenlage: Kontrollierte Studien finden Placebo-Wirkungen fast nur bei Beschwerden, die Patienten selbst einschätzen, etwa Schmerz oder Übelkeit. Die große Cochrane-Übersicht (Hróbjartsson und Gøtzsche, 2010) fand insgesamt keine wichtigen klinischen Wirkungen von Placebos „im Allgemeinen“. Dass Glaube einen Tumor auflöst, wäre deshalb eine außergewöhnliche Behauptung, für die ein Einzelfall als Beleg nicht reicht. Der Fall ist allerdings auch nicht „widerlegt“: Man kann ihn nicht prüfen, und genau das macht ihn als Beweis wertlos.","coreRule":"⚡ Ein Einzelfall ohne Vergleich beweist keine Wirkung, auch kein Wunder.","beleg":"Werkstück C.4.5 (Die Operation ohne Skalpell; Kontext & Tiefe); Fn. gl-c-klopfer (Klopfer 1957, S. 337–339); Fn. gl-c-placebo-grenzen (Hróbjartsson/Gøtzsche 2010, Cochrane CD003974)","status":"entwurf","scenario":"Der Fall stammt aus den 1950er Jahren und wurde erst nachträglich aufgeschrieben, nach einer persönlichen Mitteilung eines der behandelnden Ärzte. Eine Vergleichsgruppe gab es nicht.","kurz":"Ein einzelner, nachträglich aufgeschriebener Fall ohne Vergleichsgruppe zeigt nicht, was die Ursache war: Spontanverlauf, Fehldiagnose oder Erinnerungsfehler passen genauso gut zur Geschichte wie ein Erwartungseffekt.","prueffrage":"Wann und von wem wurde der Fall aufgeschrieben, und lässt sich heute noch nachprüfen, was damals mit dem Patienten geschah?","rueckmeldung":[{"option":0,"text":"Dass der Bericht erst nachträglich nach einer persönlichen Mitteilung aufgeschrieben wurde, schwächt ihn tatsächlich. „Erfunden“ folgt daraus aber nicht: Der Fall lässt sich nur nicht prüfen, und genau deshalb taugt er nicht als Beweis."},{"option":1,"text":"Hier wird etwas vorausgesetzt, das nirgends steht: Von einer späteren Anerkennung des Mittels ist nicht die Rede, es galt ja als wertlos. Und selbst dann bliebe das Problem, dass ohne Vergleichsgruppe die Ursache offen ist."},{"option":2,"text":"Wer an Placebo denkt, denkt leicht an große körperliche Wirkungen. Kontrollierte Studien finden sie aber fast nur bei selbst eingeschätzten Beschwerden wie Schmerz oder Übelkeit, kaum bei objektiv messbaren Größen wie der Tumorgröße."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Hróbjartsson & Gøtzsche 2010, Placebo interventions for all clinical conditions, Cochrane Database Syst Rev (PMC7156905)","oeffentlich":true,"doi":"10.1002/14651858.CD003974.pub3","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Klopfer 1957, Psychological variables in human cancer, Journal of Projective Techniques 21(4)","oeffentlich":false,"doi":"10.1080/08853126.1957.10380794"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"c707a4b76f8df101"}},{"id":"qx-c2-012","clusterId":"C","werkstueckRef":"C.4.5","stufe":4,"question":"Welche Schlussfolgerung ist aus diesem Befund am besten begründet?","scenario":"Eine Kollegin bekommt Kopfschmerzen, sobald sie glaubt, der WLAN-Router laufe – auch dann, wenn er ausgeschaltet ist. Eine große, im Auftrag der WHO erstellte Übersicht von 41 Experimenten kommt zu folgendem Ergebnis: Echte Funkfelder hatten keine oder nur kleine, nicht signifikante Wirkungen auf Beschwerden. Beschwerden traten aber häufiger auf, wenn den Versuchspersonen eine Strahlung angekündigt wurde. Das galt unabhängig davon, ob wirklich gesendet wurde.","options":["Die Beschwerden der Kollegin sind erfunden, weil Kopfschmerzen ohne einen echten körperlichen Auslöser nicht entstehen können.","Die Erwartung der Kollegin ist der naheliegende Auslöser, weil die Beschwerden dem geglaubten und nicht dem tatsächlichen Reiz folgen.","Echte Funkfelder lösen die Beschwerden zuverlässig aus, weil die Erwartung die Wirkung der Felder bei jeder Person zusätzlich verstärkt.","Die Übersicht sagt über die Kollegin nichts aus, weil Experimente mit mehreren Personen niemals auf einen einzelnen Menschen übertragbar sind."],"correctIndex":1,"explanation":"Die Übersicht fand: Echte Funkfelder hatten keine oder nur kleine, nicht signifikante Wirkungen, Symptome traten aber vermehrt auf, wenn die Exposition angekündigt war – also bezogen auf den wahrgenommenen, nicht auf den realen Feldzustand. Das spricht dafür, dass nicht die Strahlung, sondern die Erwartung die Beschwerden erzeugt. Das erklärt auch den Fall der Kollegin: Ihre Kopfschmerzen sind real, die negative Erwartung kann sie erzeugen (Nocebo-Effekt). „Real“ heißt also nicht „von außen verursacht“, und „von der Erwartung verursacht“ heißt nicht „erfunden“. Auf den Einzelfall übertragen ist das nur eine Wahrscheinlichkeitsaussage: Die Erwartung ist die naheliegendste Erklärung, aber im Einzelfall bleibt es eine Schlussfolgerung. Ob sie bei der Kollegin zutrifft, ließe sich nur durch eine verblindete Prüfung klären.","coreRule":"⚡ Wo die Beschwerden dem geglaubten statt dem tatsächlichen Reiz folgen, liegt Nocebo nahe.","beleg":"Werkstück C.4.5 (Bei Verschwörungsmythen, Nocebo); Fn. gl-c-nocebo-emf (Bosch-Capblanch u. a. 2024, Environment International 187, Art. 108612)","status":"entwurf","kurz":"Die Beschwerden folgen dem geglaubten, nicht dem tatsächlichen Reiz, also spricht mehr für die Erwartung als für die Strahlung. Der naheliegende Fehler: „Real“ mit „von außen verursacht“ gleichzusetzen. Im Einzelfall bleibt es eine Schlussfolgerung.","prueffrage":"Wann treten die Beschwerden auf, und was passiert in den Fällen, in denen der Router gar nicht läuft?","rueckmeldung":[{"option":0,"text":"Dass kein äußerer Auslöser nachweisbar ist, macht die Schmerzen nicht unecht. Die Erwartung kann sie selbst erzeugen (Nocebo-Effekt), und genau das spricht der Befund an."},{"option":2,"text":"Dass die Erwartung eine Rolle spielt, stimmt. Die echten Felder hatten aber keine oder nur kleine, nicht signifikante Wirkungen, und „zuverlässig“ und „bei jeder Person“ gehen weit über den Befund hinaus."},{"option":3,"text":"Richtig ist, dass sich ein Gruppenbefund nicht sicher auf einen Einzelfall übertragen lässt. „Niemals“ geht aber zu weit: Als Wahrscheinlichkeitsaussage stützt die Übersicht die Erwartung als naheliegendste Erklärung, prüfen ließe es sich verblindet."}],"familie":"fair-testen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Bosch-Capblanch u. a. 2024, The effects of radiofrequency electromagnetic fields exposure on human self-reported symptoms: A systematic review of human experimental studies, Environment International 187 (PubMed-Abstract)","oeffentlich":true,"doi":"10.1016/j.envint.2024.108612","url":"https://pubmed.ncbi.nlm.nih.gov/38640611/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"6b6263058a003fc0"}},{"id":"qx-c2-013","clusterId":"C","werkstueckRef":"C.4.6","stufe":1,"question":"Ein Freund erzählt dir begeistert: „Ich hatte eine schwere Erkältung, am schlimmsten ging es mir am dritten Tag. Da habe ich einen Kräutertee für 50 Euro gekauft. Vier Tage später war ich fast beschwerdefrei. Der Tee wirkt!“ Welche Erklärung für seine Besserung ist am sparsamsten, wenn du nur dieses Wissen hast?","options":["Die Besserung erklärt sich auch ohne Wirkung des Tees: Erkältungen klingen von allein ab, und gekauft wurde der Tee auf dem Höhepunkt der Beschwerden.","Die Besserung zeigt eine Wirkung des Tees, denn zwischen Einnahme und Besserung liegen nur wenige Tage, und das ist ein klarer zeitlicher Zusammenhang.","Die Besserung beweist, dass der Tee besonders gut wirkt, denn sein hoher Preis spricht für hochwertige und wirksame Inhaltsstoffe.","Die Besserung ist ein Zufall, der mit dem Tee nichts zu tun hat, denn kein Mittel kann bei einer Erkältung überhaupt je wirken."],"correctIndex":0,"explanation":"Erkältungen sind selbstlimitierend: Das Immunsystem heilt sie meist von allein. Wer sich auf dem Höhepunkt der Beschwerden zu einer Behandlung entschließt, startet an einem Punkt, von dem aus es ohnehin bergauf geht. Dazu kommt die Erwartung, dass das Mittel hilft (Placebo-Effekt). Die zeitliche Abfolge „Mittel genommen, dann besser“ sagt nichts darüber, ob das Mittel die Ursache war (Post-hoc-Fehlschluss). Mit einer Kontrollgruppe ohne Behandlung ließe sich der natürliche Verlauf von einer echten Wirkung trennen. Aus dem Fall folgt weder, dass der Tee wirkt, noch dass Mittel gegen Erkältungen nie wirken können; auch ein hoher Preis ist kein Wirksamkeitsbeleg.","coreRule":"⚡ Besserung nach einem Mittel ist noch keine Wirkung des Mittels.","beleg":"Werkstück C.4.6 (Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Wer sich auf dem Höhepunkt der Beschwerden zu einer Behandlung entschließt, startet an einem Punkt, von dem es ohnehin bergauf geht. „Tee getrunken, dann besser“ sagt daher noch nicht, dass der Tee die Ursache war.","prueffrage":"An welchem Tag kaufte dein Freund den Tee, und wie ging es ihm an diesem Tag im Vergleich zu den Tagen davor?","rueckmeldung":[{"option":1,"text":"Dass die Besserung kurz nach dem Teekauf kam, stimmt. Eine bloße Abfolge sagt aber nichts über die Ursache: Erkältungen klingen meist von allein ab, ob der Tee gewirkt hat, lässt sich so nicht entscheiden."},{"option":2,"text":"Ein hoher Preis weckt Vertrauen in ein Mittel, belegt aber keine Wirkung. Die Besserung erklärt sich schon durch den natürlichen Verlauf: Erkältungen klingen von allein ab, und gekauft wurde der Tee auf dem Höhepunkt."},{"option":3,"text":"Dass die Besserung auch ohne Tee erklärbar ist, stimmt. Sie ist aber kein Zufall, sondern der übliche Verlauf einer Erkältung, und dass kein Mittel je wirken kann, lässt sich aus diesem einen Fall nicht ableiten."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"IQWiG, gesundheitsinformation.de: Erkältung","oeffentlich":true,"url":"https://www.gesundheitsinformation.de/erkaeltung.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Barnett, van der Pols & Dobson 2005, Regression to the mean: what it is and how to deal with it, Int J Epidemiol 34(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1093/ije/dyh299","url":"https://pubmed.ncbi.nlm.nih.gov/15333621/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"0e6a1ba62d39f5bc"}},{"id":"qx-c2-014","clusterId":"C","werkstueckRef":"C.4.6","stufe":2,"question":"Welche Erklärung für den Leistungsabfall ist am besten begründet?","scenario":"Eine Tennisspielerin hat die beste Saison ihrer Karriere gespielt und landet deshalb auf dem Titel eines Sportmagazins. In der Folgesaison spielt sie schlechter, bleibt aber weiter eine starke Spielerin. Kollegen sprechen vom „Fluch des Covers“.","options":["Der Medienrummel lenkt Sportlerinnen so ab, dass ihre Leistung danach dauerhaft unter dem früheren Durchschnitt liegt und kaum zurückkehrt.","Profi-Leistungen sind frei von Zufall, weshalb als Ursache nur psychologischer Druck oder Verletzungen in Frage kommen.","Sie kam aufs Cover, weil ihre Leistung gerade außergewöhnlich hoch war; nach einem Extremwert liegt der nächste meist wieder näher am Normalniveau.","Magazine wählen bevorzugt Sportlerinnen, die ihren Karrierehöhepunkt bereits überschritten haben und ohnehin schon nachlassen."],"correctIndex":2,"explanation":"Eine Rekordsaison ist ein Extremwert, und genau deshalb erscheint die Spielerin auf dem Cover. In jedem System, in das Zufall involviert ist, liegt nach einem Extremwert der nächste Wert mit hoher Wahrscheinlichkeit wieder näher am Durchschnitt. Diese Regression zur Mitte erklärt den Abfall ohne zusätzliche Annahmen, denn sie braucht weder einen Fluch noch eine dauerhafte Ablenkung. Die Spielerin kann dabei weiterhin sehr gut sein, nur nicht mehr auf dem außergewöhnlichen Höhepunkt. Das erwartete Muster wäre also: Rückgang, aber weiterhin starkes Niveau. Dasselbe Prinzip erklärt, warum nach dem schlimmsten Tag einer schwankenden Krankheit mit hoher Wahrscheinlichkeit eine Besserung folgt, unabhängig von einer Behandlung.","coreRule":"⚡ Wer wegen einer Rekordleistung auffällt, wird danach meist wieder normaler – ohne Fluch.","beleg":"Werkstück C.4.6 (Anwendung & Relevanz, In der Sport- und Wirtschaftswelt)","status":"freigegeben","freigabe":{"datum":"2026-10-13","pruefsumme":"9ced5798fb44a856","vermerk":"Prüfpult"},"kurz":"Aufs Cover kam sie wegen eines Extremwerts, und nach einem Extremwert liegt der nächste Wert wahrscheinlich näher am Durchschnitt. Ein Fluch ist dafür nicht nötig: Rückgang bei weiter starkem Niveau ist genau das zu Erwartende.","prueffrage":"Wie lagen ihre Ergebnisse in den Jahren vor der Rekordsaison, und wo liegt die Folgesaison im Vergleich dazu?","rueckmeldung":[{"option":0,"text":"Medienrummel kann tatsächlich Kraft kosten, daher wirkt die Erklärung plausibel. Sie behauptet aber einen dauerhaften Abfall unter das frühere Niveau, wofür eine einzige Saison nichts zeigt; die Spielerin bleibt stark."},{"option":1,"text":"Druck und Verletzungen kommen als Ursachen durchaus vor. Falsch ist aber die Voraussetzung: Auch Profi-Leistungen schwanken, etwa durch Tagesform oder knappe Sätze, und diese Schwankung kann den Rückgang ohne weitere Ursache erklären."},{"option":3,"text":"Dass die Auswahl vom Leistungsverlauf abhängt, ist richtig gedacht, aber die Reihenfolge stimmt nicht: Sie kam aufs Cover, weil sie auf dem Höhepunkt stand, nicht weil sie schon nachließ. Die Auswahl erfolgte also nach einem Extremwert."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Barnett, van der Pols & Dobson 2005, Regression to the mean: what it is and how to deal with it, Int J Epidemiol 34(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1093/ije/dyh299","url":"https://pubmed.ncbi.nlm.nih.gov/15333621/","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"9ced5798fb44a856"}},{"id":"qx-c2-015","clusterId":"C","werkstueckRef":"C.4.6","stufe":3,"question":"Bei welcher Art von Erkrankung wäre sein Vorhaben am gefährlichsten?","options":["Bei einer Krankheit, die weder von allein abklingt noch schwankt, etwa Typ-1-Diabetes, weil die Methode dort eine wirksame Therapie ersetzen würde.","Bei einer Krankheit, die ohnehin von allein abklingt, etwa einer Erkältung, weil die Methode dort den Verlauf spürbar verlängern würde.","Bei einer Krankheit mit stark schwankenden Beschwerden, etwa unspezifischen Rückenschmerzen, weil dort Besserung und Verschlechterung kaum zu unterscheiden wären.","Bei einer Krankheit, die länger als eine Woche dauert, etwa einem hartnäckigen Husten, weil die Erwartung dann ihre Wirkung verlöre und jede Linderung ausbliebe."],"correctIndex":0,"explanation":"Eine Methode, die nur von Erwartung, Selbstheilung und Regression zur Mitte lebt, richtet bei Krankheiten, die ohnehin abklingen oder stark schwanken, kaum Schaden an: Die Besserung wäre auch ohne sie gekommen, und der Körper bekommt Zeit zur Heilung. Gefährlich wird es erst dort, wo eine Besserung nicht von allein zu erwarten ist, etwa bei Typ-1-Diabetes, einer schweren bakteriellen Infektion oder den meisten Krebsarten. Dort entsteht der Schaden nicht durch die Methode selbst, sondern dadurch, dass sie eine wirksame Therapie verdrängt und wertvolle Zeit verloren geht. Die Frage „Wäre es auch von allein besser geworden?“ entscheidet also nicht nur darüber, ob du eine Heilungsgeschichte glaubst, sondern auch darüber, wie riskant der Einsatz ist.","coreRule":"⚡ Gefährlich wird eine Scheinwirkung dort, wo die Krankheit nicht von allein besser wird und die Methode die echte Therapie ersetzt.","beleg":"Werkstück C.4.6 (Der Kipppunkt)","status":"entwurf","scenario":"Ein Bekannter schwärmt: „Die sanfte Naturmethode hat mir und meiner Familie schon oft geholfen. Ich nehme sie jetzt einfach bei allem.“ Du weißt: Ihre Wirkung beruht nur auf Erwartung, Selbstheilung und dem Abflachen zufälliger Beschwerdespitzen.","kurz":"Gefährlich wird die Methode dort, wo keine Besserung von allein zu erwarten ist: Sie verdrängt dann eine wirksame Therapie, und wertvolle Zeit geht verloren. Bei Krankheiten, die abklingen oder schwanken, richtet sie kaum Schaden an.","prueffrage":"Was geschieht bei jeder der genannten Krankheiten, wenn sie gar nicht wirksam behandelt wird?","rueckmeldung":[{"option":1,"text":"Dass eine Erkältung von allein abklingt, stimmt. Gerade deshalb verlängert eine wirkungslose Methode den Verlauf nicht spürbar: Die Besserung käme auch so, und der Körper bekommt die Zeit, die er zur Heilung braucht."},{"option":2,"text":"Bei schwankenden Beschwerden lässt sich tatsächlich schwer sagen, ob eine Besserung von der Methode kommt. Gefährlich ist das aber kaum: Die Beschwerdespitzen flachen ohnehin wieder ab, die Besserung käme also auch ohne sie."},{"option":3,"text":"Dass die Erwartung nach einer Woche ihre Wirkung verlöre, ist nicht belegt und erklärt keine Gefahr. Entscheidend ist nicht die Dauer, sondern ob eine Besserung von allein zu erwarten ist und eine wirksame Therapie verdrängt würde."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Johnson u. a. 2018, Use of Alternative Medicine for Cancer and Its Impact on Survival, J Natl Cancer Inst 110(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1093/jnci/djx145","url":"https://pubmed.ncbi.nlm.nih.gov/28922780/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Hanna u. a. 2020, Mortality due to cancer treatment delay: systematic review and meta-analysis, BMJ 371 (PMC7610021)","oeffentlich":true,"doi":"10.1136/bmj.m4087","abruf":"2026-10-12"},{"typ":"url","kurz":"IQWiG, gesundheitsinformation.de: Erkältung","oeffentlich":true,"url":"https://www.gesundheitsinformation.de/erkaeltung.html","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"44e2d0ca7ba60fe4"}},{"id":"qx-c2-016","clusterId":"C","werkstueckRef":"C.4.6","stufe":4,"question":"Welche Prüffrage fehlt, bevor man den Blitzer als Ursache der Besserung ansieht?","scenario":"Eine Gemeinde baut nach dem schlimmsten Unfalljahr ihrer Geschichte an einer Kreuzung einen Blitzer ein; im Jahr darauf passieren dort weniger Unfälle. Der Bürgermeister sieht darin den Beweis, dass der Blitzer wirkt.","options":["Wie viele Autofahrer den Blitzer bemerkt haben, denn wenn ihn viele kennen, ist der Rückgang der Unfallzahlen damit schon erklärt.","Wie sich vergleichbare Kreuzungen ohne Blitzer entwickelt haben, denn so lässt sich eine Wirkung von der Rückkehr zum Durchschnitt trennen.","Ob der Bürgermeister selbst an die Maßnahme glaubt, denn bloße Erwartung verändert die Zahl der tatsächlichen Unfälle spürbar.","Ob die Unfallzahl im Folgejahr genau dem langjährigen Durchschnitt entspricht, denn nur dann ist eine Rückkehr zum Durchschnitt belegt."],"correctIndex":1,"explanation":"Ein außergewöhnlich schlechtes Jahr, eine Maßnahme genau danach, anschließend Besserung: Das ist das typische Muster der Regression zur Mitte. Nach einem extremen Ausreißer liegt der nächste Wert mit hoher Wahrscheinlichkeit wieder näher am Durchschnitt, auch ohne jede Maßnahme. Erst der Vergleich mit ähnlichen Kreuzungen, die keinen Blitzer bekommen haben, trennt diesen natürlichen Verlauf von einer echten Wirkung. Dass Autofahrer den Blitzer bemerken, beantwortet diese Frage nicht, die Erwartung des Bürgermeisters ändert nichts an der Zahl der Unfälle, und dass der Folgewert den Durchschnitt genau trifft, ist nicht nötig, denn Regression zur Mitte heißt nur: näher am Durchschnitt. Der Blitzer kann trotzdem wirken; es fehlt nur der Beleg.","coreRule":"⚡ Ohne Vergleichsgruppe bleibt offen, ob die Maßnahme wirkte oder der Zufall zur Normalität zurückkehrte.","beleg":"Werkstück C.4.6 (Kontext & Tiefe: Regression zur Mitte; Red Flags: fehlende Kontrollgruppe; Verbindungen: Kontrollgruppen); Übertragung auf ein Alltagsbeispiel","status":"entwurf","quote":"","quoteLabel":"","kurz":"Nach einem Rekordjahr fällt der nächste Wert meist ohnehin näher an den Durchschnitt, auch ohne Maßnahme. Erst der Vergleich mit ähnlichen Kreuzungen ohne Blitzer trennt diesen natürlichen Verlauf von einer echten Wirkung.","prueffrage":"War das schlimmste Unfalljahr an dieser Kreuzung ein Ausreißer, und hätte es danach auch ohne Blitzer besser werden können?","rueckmeldung":[{"option":0,"text":"Dass Fahrer den Blitzer bemerken, ist plausibel, sagt aber noch nichts darüber, ob dadurch Unfälle ausbleiben. Und die Besserung kann auch ohne jede Wirkung eintreten, nach einem Ausnahmejahr ist das sogar zu erwarten."},{"option":2,"text":"Eine Überzeugung kann die Deutung färben, doch sie ändert nicht, wie viele Unfälle tatsächlich passieren. Dass der Bürgermeister an die Maßnahme glaubt, ist deshalb nichts, was man prüfen müsste, um die Ursache zu klären."},{"option":3,"text":"Für eine Rückkehr zum Durchschnitt muss der Folgewert ihn gar nicht genau treffen, es genügt, ihm näher zu kommen. Das Kriterium ist zu eng und trifft die eigentliche Lücke nicht, nämlich dass eine Vergleichsgruppe fehlt."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Allsop 2010, The Effectiveness of Speed Cameras. A review of evidence. Executive Summary, RAC Foundation","oeffentlich":true,"url":"https://www.racfoundation.org/wp-content/uploads/speed-camera-effectiveness-allsop-exec-summary.pdf","seite":"PDF-S. 7","abruf":"2026-10-12"},{"typ":"url","kurz":"Barnett, van der Pols & Dobson 2005, Regression to the mean: what it is and how to deal with it, Int J Epidemiol 34(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1093/ije/dyh299","url":"https://pubmed.ncbi.nlm.nih.gov/15333621/","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"0e5c17bf82515da9"}},{"id":"qx-c2-017","clusterId":"C","werkstueckRef":"C.4.7","stufe":1,"question":"Du liest die Meldung und willst sie prüfen, bevor du sie weiterleitest: Was ist der entscheidende Denkfehler dieser Schlagzeile?","scenario":"Eine Schlagzeile warnt vor „Dihydrogenmonoxid im Leitungswasser“: Es sei Bestandteil des sauren Regens, könne in gasförmigem Zustand schwere Verbrennungen verursachen, und sein Einatmen sei tödlich. Ein Chemiker erklärt, „Dihydrogenmonoxid“ sei nur ein ungewöhnlicher chemischer Name für H₂O, also für Wasser.","options":["Die Meldung nennt Eigenschaften eines Stoffes, aber weder Dosis noch Kontext; ohne sie sagt „kann tödlich sein“ nichts über die tatsächliche Gefahr.","Die Meldung beschreibt Eigenschaften, die der Stoff gar nicht hat; schon die genannten Tatsachenbehauptungen sind sachlich falsch.","Die Meldung verwendet einen Fachnamen; wer Fachnamen benutzt, will damit immer Angst erzeugen und das Publikum bewusst täuschen.","Die Meldung nennt Gefahren, die in großen Mengen wirklich bestehen; weil die Eigenschaften stimmen, ist die Warnung im Kern berechtigt."],"correctIndex":0,"explanation":"Wasser steckt im sauren Regen, heißer Wasserdampf kann schwere Verbrühungen verursachen, und Wasser in der Lunge führt zum Ertrinken. Die Aussagen sind einzeln richtig, aber ohne Menge und Kontext sagen sie nichts über das Risiko: Bei den allermeisten Stoffen ist eine kleine Dosis harmlos und eine sehr hohe schädlich (Ausnahmen wie erbgutschädigende Stoffe nimmt man ohne sichere Schwelle an), auch bei Wasser. Die Meldung nutzt einen unvertrauten Fachnamen und verschweigt genau die Information, die über Gefahr oder Sicherheit entscheidet. Zu prüfen wäre also: Welche Menge liegt vor, wo liegt die schädliche Schwelle, und wie verhält sich beides zur alltäglichen Belastung?","coreRule":"⚡ Nicht die Substanz allein, sondern die Menge im Kontext entscheidet über die Gefahr.","beleg":"Werkstück C.4.7 (Das tödliche Wasser)","status":"entwurf","kurz":"Die genannten Eigenschaften von Wasser stimmen einzeln, sagen aber ohne Menge und Kontext nichts über das Risiko: Meist ist eine kleine Menge harmlos und eine sehr große schädlich. Der unvertraute Fachname lässt das vergessen.","prueffrage":"Treffen die drei Warnungen auf Wasser zu, und was folgt daraus für das Glas Leitungswasser auf deinem Tisch?","rueckmeldung":[{"option":1,"text":"Bei so ungewöhnlichen Warnungen vermutet man leicht, sie seien erfunden. Doch die Tatsachen stimmen: Wasser steckt im sauren Regen, Dampf kann verbrühen, und eingeatmetes Wasser kann zum Ertrinken führen; es fehlt die Menge, nicht die Wahrheit."},{"option":2,"text":"Der unvertraute Name wirkt hier tatsächlich bedrohlich und verdeckt, worum es geht. Dass Fachnamen immer täuschen sollen, trägt aber nicht: Sie sind üblich und verraten keine Absicht; entscheidend ist, was die Meldung verschweigt."},{"option":3,"text":"Einzeln stimmen die Eigenschaften, und manche werden erst bei großen Mengen gefährlich. Gerade deshalb ist die Warnung ohne Menge und Kontext irreführend: Leitungswasser in alltäglicher Menge ist harmlos."}],"familie":"dosis-entscheidet","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Grandjean, P. (2016): Paracelsus Revisited: The Dose Concept in a Complex World. Basic & Clinical Pharmacology & Toxicology 119(2), 126–132","oeffentlich":true,"doi":"10.1111/bcpt.12622","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4942381/","abruf":"2026-10-12"},{"typ":"url","kurz":"EFSA: Margin of Exposure (Themenseite)","oeffentlich":true,"url":"https://efsa.europa.eu/en/topics/topic/margin-exposure","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"1f72d7f4b5212d19"}},{"id":"qx-c2-018","clusterId":"C","werkstueckRef":"C.4.7","stufe":2,"question":"Welche Frage und welche Vergleichsgrößen entkräften diese Schlagzeile am besten?","scenario":"In einer Chatgruppe kursiert die Meldung „Spuren von Formaldehyd in Impfstoffen gefunden!“ und löst Entsetzen aus. Eine Teilnehmerin schreibt: „Formaldehyd ist ein Gift. Wo Gift drin ist, darf nichts in meinen Körper!“ Du willst sachlich antworten.","options":["Wie viel ist es, und wie verhält sich die Menge zu dem, was Obst enthält und der Körper selbst ständig bildet?","Ist Formaldehyd ein Gift? Wenn ja, darf es in Impfstoffen nicht vorkommen, und die Meldung ist ein Skandal.","Wer hat die Meldung verbreitet, und hat diese Person ein Interesse daran, dass Impfstoffe schlecht dastehen?","Wurde Formaldehyd tatsächlich nachgewiesen, oder beruht die Meldung auf einer Verwechslung mit einem anderen Stoff?"],"correctIndex":0,"explanation":"Nicht die bloße Anwesenheit eines Stoffs entscheidet über seine Gefährlichkeit, sondern seine Menge im Verhältnis zu Grenzwert und natürlichen Quellen. Hier ist die Menge klein: Eine Impfdosis enthält höchstens 0,1 Milligramm Formaldehyd. Ein Apfel oder eine Birne enthält insgesamt mehr, und der Körper bildet selbst ständig weitaus höhere, aber völlig harmlose Mengen. Die Frage „Wie viel, verglichen womit?“ macht aus einem Schreckenswort eine prüfbare Größenordnung. Die anderen Fragen bleiben bei „Gift ja oder nein“, bei der Quelle der Meldung oder bei der Frage, ob der Nachweis stimmt. Das kann alles seinen Platz haben, klärt aber nicht, ob die gefundene Menge überhaupt etwas bedeutet.","coreRule":"⚡ Frag bei jedem „Gift gefunden“ nach der Menge und dem Vergleichswert.","beleg":"Werkstück C.4.7 (Anwendung & Relevanz, Chemophobie); Fn. gl-c-formaldehyd (Kuhrt u. a. 2021; Packungsbeilage INFANRIX; Centre for Food Safety Hongkong)","status":"entwurf","kurz":"Entscheidend ist nicht, dass ein Stoff vorkommt, sondern wie viel davon und im Vergleich zu was. Wer nur fragt, ob es „Gift“ ist, bleibt beim Schreckenswort. Die Mengenfrage macht daraus eine Größenordnung, die man prüfen kann.","prueffrage":"Was genau steht in der Meldung, und was müsstest du zusätzlich wissen, um ihre Bedeutung einschätzen zu können?","rueckmeldung":[{"option":1,"text":"Die Frage folgt dem Schlagwort „Gift“, als hinge die Gefahr allein am Stoff. Wie gefährlich ein Stoff ist, hängt aber von der Menge ab, und genau diese Größenordnung lässt die Schlagzeile weg."},{"option":2,"text":"Wer eine Meldung verbreitet und warum, ist eine berechtigte Frage. Sie sagt aber nichts darüber, ob die gefundene Menge etwas bedeutet. Eine Meldung mit eigennützigem Absender kann genauso richtig oder falsch sein wie jede andere."},{"option":3,"text":"Den Nachweis zu prüfen, ist grundsätzlich sinnvoll, entkräftet aber nichts: Manche Impfstoffe enthalten tatsächlich Spuren, höchstens 0,1 Milligramm pro Dosis. Erst der Vergleich mit Obst und körpereigener Bildung zeigt, was das bedeutet."}],"familie":"dosis-entscheidet","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"U.S. FDA: Common Ingredients in FDA-Approved Vaccines","oeffentlich":true,"url":"https://www.fda.gov/vaccines-blood-biologics/safety-availability-biologics/common-ingredients-fda-approved-vaccines","abruf":"2026-10-12"},{"typ":"url","kurz":"Centre for Food Safety Hongkong: Foods Known to Contain Naturally Occurring Formaldehyde","oeffentlich":true,"url":"https://www.cfs.gov.hk/english/whatsnew/whatsnew_fa/files/formaldehyde.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"GlaxoSmithKline: Packungsbeilage INFANRIX („≤100 mcg of residual formaldehyde“ je 0,5-ml-Dosis), nach Landkarte Fn. gl-c-formaldehyd","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"fb0a99c6be899fa0"}},{"id":"qx-c2-019","clusterId":"C","werkstueckRef":"C.4.7","stufe":3,"question":"Welche Einschätzung der beiden Aussagen trifft zu, und was folgt daraus für den Umgang mit dem Stoff?","options":["Die Leserin liegt richtig: Wo keine sichere Schwelle angenommen wird, ist jede Menge gleich riskant, deshalb gilt Nulltoleranz und der Abstand zur schädlichen Dosis wird nicht bewertet.","Beide liegen falsch: Auch ohne angenommene sichere Schwelle sinkt das Risiko mit der Dosis, ohne ganz zu verschwinden, deshalb senkt man solche Stoffe so weit wie vernünftig möglich und bewertet den Abstand zur schädlichen Dosis.","Der Kollege liegt richtig: Stoffe ohne angenommene Schwelle unterliegen keiner Dosis-Wirkungs-Beziehung, deshalb ist jede nachgewiesene Spur gleich harmlos und der Abstand zur schädlichen Dosis spielt keine Rolle.","Die Leserin liegt im Ergebnis richtig: Zwar steigt das Risiko mit der Dosis, doch weil es nie ganz verschwindet, muss jeder Nachweis zu einem Verbot führen, ohne dass der Abstand zur schädlichen Dosis bewertet wird."],"correctIndex":1,"explanation":"Beide Aussagen machen aus einem Kontinuum eine Ja-Nein-Frage. Für erbgutschädigende Stoffe und ionisierende Strahlung nimmt man vorsorglich keine sichere Schwelle an: Das Risiko sinkt nach dieser Annahme mit der Dosis, verschwindet aber nicht ganz. „Keine Schwelle“ heißt also nicht „jede Menge gleich gefährlich“ und auch nicht „Dosis egal“. Behörden bewerten deshalb den Abstand zwischen der tatsächlichen Belastung und der Dosis, die im Tierversuch Tumoren auslöst, und senken solche Stoffe so weit, wie es vernünftigerweise möglich ist (ALARA-Prinzip). Auch hier hängt das Risiko von der Dosis ab.","coreRule":"⚡ Auch ohne sichere Schwelle gilt: Das Risiko wächst mit der Dosis – Null gibt es nicht, aber auch nicht „alles gleich schlimm“.","beleg":"Werkstück C.4.7 (Kontext & Tiefe, „Die Kurve ist entscheidend“); Fn. gl-c-schwelle (Mußhoff u. a. 2015, S. 602–603; Schrenk 2011, S. 317)","status":"entwurf","scenario":"Eine Redaktion berichtet: In einem Brot wurden Spuren eines Stoffes gefunden, der das Erbgut schädigen kann. Eine Leserin schreibt: „Bei erbgutschädigenden Stoffen gibt es keine sichere Menge – also ist schon jede Spur gleich gefährlich wie eine große Dosis, und man muss das Brot komplett meiden.“ Ein Kollege widerspricht: „Unsinn – so winzige Spuren sind einfach harmlos, auf die genaue Menge kommt es da gar nicht an.“","kurz":"Ohne angenommene Schwelle sinkt das Risiko mit der Dosis, ohne ganz zu verschwinden. „Jede Spur gleich gefährlich“ und „Spuren sind harmlos“ übersehen das beide. Richtig ist, so weit wie vernünftig möglich zu senken und den Abstand zur schädlichen Dosis zu bewerten.","prueffrage":"Was würden Leserin und Kollege jeweils über eine Spur sagen, die zehnmal größer wäre als die im Brot gefundene?","rueckmeldung":[{"option":0,"text":"Dass bei solchen Stoffen vorsorglich keine sichere Schwelle angenommen wird, stimmt. Daraus folgt aber nicht, dass jede Menge gleich riskant ist: Das Risiko sinkt mit der Dosis, deshalb wird der Abstand zur schädlichen Dosis sehr wohl bewertet."},{"option":2,"text":"Dass eine winzige Spur nur ein kleines Risiko bedeutet, stimmt. „Keine Schwelle“ heißt aber nicht „Menge egal“: Das Risiko hängt weiter von der Dosis ab und verschwindet nicht ganz, deshalb bleibt der Abstand zur schädlichen Dosis entscheidend."},{"option":3,"text":"Dass das Risiko mit der Dosis steigt und nie ganz verschwindet, stimmt. Daraus folgt aber kein Verbot bei jedem Nachweis: Weil die Dosis zählt, bewertet man den Abstand zur schädlichen Dosis und senkt die Belastung so weit wie vernünftig möglich."}],"familie":"dosis-entscheidet","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"EFSA: Margin of Exposure (Themenseite)","oeffentlich":true,"url":"https://efsa.europa.eu/en/topics/topic/margin-exposure","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Schrenk, D. (2011): Lebensmittel – Nahrungsergänzungsmittel – Arzneimittel. Toxikologische Bewertung und Abgrenzung. Pharmazie in unserer Zeit 40(4), 316–324 (doi 10.1002/pauz.201100426)","oeffentlich":false},{"typ":"literatur","kurz":"Mäntele, W. (2021): Elektrosmog und Ökoboom. Springer, Kap. „Gibt es einen Schwellwert für die Dosis?“","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"13f340ab8984a986"}},{"id":"qx-c2-020","clusterId":"C","werkstueckRef":"C.4.8","stufe":1,"question":"Ein Gesprächspartner sagt: „Der Zweite Hauptsatz der Thermodynamik verbietet es grundsätzlich, dass ein Lebewesen unbegrenzt lange lebt. Entropie nimmt immer zu, also muss jeder Organismus irgendwann zerfallen.“ Was ist an diesem Schluss am ehesten fehlerhaft?","options":["Er übersieht, dass ein Organismus ein offenes System ist: Energie fließt zu, Entropie wird abgegeben, und so kann seine Ordnung lokal bestehen bleiben.","Er übersieht, dass Lebewesen die Gesetze der Thermodynamik umgehen, weil biologische Prozesse anderen Regeln folgen als physikalische.","Er übersieht, dass Entropie nur in unbelebter Materie zunimmt, weil sie in lebenden Zellen durch Stoffwechsel ständig sinkt.","Er übersieht, dass unbegrenzte Lebensdauer längst beobachtet wurde, sodass der Hauptsatz empirisch widerlegt ist."],"correctIndex":0,"explanation":"Kein System setzt den Zweiten Hauptsatz außer Kraft. Er verbietet einem offenen System aber nicht, seine Ordnung beliebig lange zu halten, solange Energie nachfließt und Entropie nach außen abgegeben wird. Ein Lebewesen ist ein solches offenes System im Stoff- und Energiefluss: Es ist eine lokale Senke niedriger Entropie und hält diese Ordnung nur durch fortwährende Energiezufuhr und die Abgabe von Entropie nach außen aufrecht. Jede Reparatur kostet Energie, aber ein Verbot unbegrenzter Lebensdauer folgt daraus nicht. Dass Körper nicht unbegrenzt in Wartung investieren, ist eine Frage der evolutionär eingestellten Energieverteilung (Fortpflanzung statt Instandhaltung), keine physikalische Notwendigkeit. Schon der Evolutionsbiologe George C. Williams wies 1957 den Vergleich des Organismus mit einer verschleißenden Maschine zurück. Die Gegenthese, der Tod sei physikalisch unvermeidlich, wird vertreten, bleibt aber umstritten, denn bei manchen Arten steigt das Sterberisiko mit dem Alter kaum oder gar nicht. Die anderen Antworten scheitern ebenfalls: Lebewesen umgehen die Thermodynamik nicht, ihre lokal niedrige Entropie bleibt nur durch Energiezufuhr und die Abgabe von Entropie nach außen bestehen, und der Hauptsatz ist nicht widerlegt. Der Fehlschluss besteht darin, aus dem Hauptsatz ein Verbot abzuleiten, das er für ein offenes System gar nicht ausspricht.","coreRule":"⚡ Ein Gesetz über abgeschlossene Systeme beweist nichts über offene. Reparatur kostet Energie, verboten ist sie nicht.","beleg":"Werkstück C.4.8 (Kontext & Tiefe, Hierarchie der Grenzen); Fn. gl-c-williams (Williams 1957, S. 398 und 401–402)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Der Zweite Hauptsatz gilt, verbietet einem offenen System aber nicht, seine Ordnung zu halten, solange Energie zufließt und Entropie nach außen abgeht. Der Fehlschluss liegt darin, aus „Entropie nimmt zu“ ein Verbot abzuleiten, das für Lebewesen gar nicht folgt.","prueffrage":"Bleibt ein Kühlschrank innen dauerhaft kalt, obwohl Wärme von selbst immer vom Warmen zum Kalten fließt, und was braucht er dafür?","rueckmeldung":[{"option":1,"text":"Dass Leben besonders geordnet wirkt, lädt zu der Annahme ein, es folge eigenen Regeln. Auch Zellen unterliegen aber der Thermodynamik; ihre Ordnung ist keine Ausnahme vom Hauptsatz, sondern wird durch Energiezufuhr und Entropieabgabe erkauft."},{"option":2,"text":"Dass im Stoffwechsel Ordnung aufgebaut wird, stimmt. Die Zelle hält ihre Entropie aber nur niedrig, weil sie die dabei entstehende Entropie an die Umgebung abgibt; insgesamt nimmt die Entropie auch hier zu."},{"option":3,"text":"Der Hauptsatz ist nicht widerlegt, und eine nachgewiesene unbegrenzte Lebensdauer gibt es nicht. Beobachtet wurde bei manchen Arten nur ein kaum oder gar nicht mit dem Alter steigendes Sterberisiko, und das ist etwas anderes."}],"familie":"bilanz-pruefen","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Schaible, R. u. a. (2015): Constant mortality and fertility over age in Hydra. PNAS 112(51), 15701–15706","oeffentlich":true,"doi":"10.1073/pnas.1521002112","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4697432/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Jones, O. R. u. a. (2014): Diversity of ageing across the tree of life. Nature 505(7482), 169–173","oeffentlich":true,"doi":"10.1038/nature12789","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC4157354/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Williams, G. C. (1957): Pleiotropy, natural selection, and the evolution of senescence. Evolution 11(4), 398–411 (doi 10.1111/j.1558-5646.1957.tb02911.x)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"3e4624fbf4862cca"}},{"id":"qx-c2-021","clusterId":"C","werkstueckRef":"C.4.8","stufe":2,"question":"Wie sollte die Werbung vor dem Hintergrund der Studienlage beurteilt werden?","scenario":"Ein Online-Shop verspricht: „Antioxidantien-Kapseln stoppen den Rost des Alterns und verlängern dein Leben.“ Zur Prüfung liegt dir eine Übersichtsarbeit vor, die 78 Studien mit insgesamt 296.707 Teilnehmenden ausgewertet hat, Gesunde ebenso wie Kranke.","options":["Die Behauptung ist gut belegt, denn große Studien zeigen bei Gesunden, die vorbeugend Antioxidantien nehmen, eine geringere Sterblichkeit.","Die Behauptung ist nur bei hoher Dosierung zutreffend, denn größere Mengen verlängern das Leben stärker als kleine.","Die Behauptung ist nicht belegt: Große Studien fanden keine geringere Sterblichkeit, bei Beta-Carotin und Vitamin E sogar Hinweise auf eine höhere.","Die Behauptung lässt sich weder bestätigen noch widerlegen, denn zu Antioxidantien liegen keine Studien mit genug Teilnehmenden vor."],"correctIndex":2,"explanation":"Die plausible Idee „Altern ist molekularer Rost, also hilft ein Rostschutz“ ist kein Beleg. Ob Kapseln die Sterblichkeit tatsächlich senken, entscheidet sich an Studien mit vielen Teilnehmenden, und die liegen vor: Die Cochrane-Übersicht von Bjelakovic u. a. (2012) wertete 78 Studien mit 296.707 Teilnehmenden aus. Antioxidantien als Nahrungsergänzung senkten die Sterblichkeit nicht, Beta-Carotin und Vitamin E scheinen sie sogar zu erhöhen. Dass freie Radikale Schäden verursachen, ist zudem nur ein Teil des Bildes: Es gibt viele weitere Schadensquellen, und ein einzelner Wirkstoff kann nicht alle abdecken. Wer ein Ein-Wirkstoff-Versprechen prüft, fragt deshalb nicht, ob der Mechanismus einleuchtet, sondern ob die Wirkung am Menschen belegt ist.","coreRule":"⚡ Ein einleuchtender Mechanismus ersetzt keinen Beleg: Wer „Rostschutz“ verspricht, muss zeigen, dass Kapseln die Sterblichkeit senken – große Studien zeigen das bisher nicht.","beleg":"Werkstück C.4.8 (Ebene 2: Die Chemie; Red Flags); Fn. gl-c-antioxidantien (Bjelakovic u. a. 2012, Cochrane CD007176)","status":"entwurf","kurz":"Ob Kapseln das Leben verlängern, zeigen Studien am Menschen, nicht ein einleuchtender Mechanismus. Bei fast 300.000 Teilnehmenden sank die Sterblichkeit nicht, bei Beta-Carotin und Vitamin E scheint sie sogar zu steigen. Das Bild vom „Rost“ überzeugt, belegt aber nichts.","prueffrage":"Woran könntest du erkennen, ob die Kapseln bei Menschen tatsächlich etwas bewirken, und nicht nur im Reagenzglas oder in der Theorie?","rueckmeldung":[{"option":0,"text":"Vorbeugende Einnahme scheint gerade für Gesunde sinnvoll. In den 78 Studien, Gesunde eingeschlossen, sank die Sterblichkeit aber nicht, und bei Beta-Carotin und Vitamin E gibt es sogar Hinweise auf eine höhere."},{"option":1,"text":"„Viel hilft viel“ ist eine bekannte Denkgewohnheit, aber hier ohne Stütze: Für einen Nutzen höherer Dosen gibt es keinen Beleg, bei Beta-Carotin und Vitamin E sogar Hinweise auf eine höhere Sterblichkeit."},{"option":3,"text":"Vorsicht bei offenen Fragen ist grundsätzlich vernünftig. Hier liegt aber eine Auswertung von 78 Studien mit rund 297.000 Teilnehmenden vor. Daran fehlt es nicht, und das Ergebnis lautet: kein Beleg für eine geringere Sterblichkeit."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Bjelakovic, G. u. a. (2012): Antioxidant supplements for prevention of mortality in healthy participants and patients with various diseases. Cochrane Database of Systematic Reviews (3), CD007176","oeffentlich":true,"doi":"10.1002/14651858.CD007176.pub2","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8407395/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"d05352648bad1aaa"}},{"id":"qx-c2-022","clusterId":"C","werkstueckRef":"C.4.8","stufe":3,"question":"Welche Einschätzung der Aussage ist am besten begründet?","options":["Die Aussage ist plausibel, aber nicht belegt: Der Mausbefund stützt den Zielkonflikt nicht, und beim Menschen fehlt bisher ein gesichertes Beispiel für ein solches Gen.","Die Aussage ist widerlegt: Der Krebsschutz durch p53 ließ sich in Mäusen nicht bestätigen, und die Apoptose trifft ohnehin nur Tumorzellen, nie gesunde Stammzellen.","Die Aussage ist bestätigt: Mäuse mit zusätzlichem p53 alterten deutlich schneller, das Ergebnis gilt vermutlich aber nur für Nagetiere, nicht für den Menschen.","Die Aussage ist unbegründet: p53 wirkt nur im höheren Alter, und in der Jugend hat das Gen keinen messbaren Einfluss auf die Entstehung von Tumoren."],"correctIndex":0,"explanation":"Die Hypothese ist plausibel: Ein Gen, das in der Jugend krebsverdächtige Zellen rigoros entfernt, könnte im Alter auch nützliche Stammzellen opfern. Plausibel ist aber nicht bewiesen. Bei „Super-p53“-Mäusen mit zusätzlichen, normal gesteuerten p53-Kopien trat der Krebsschutz ohne beschleunigtes Altern auf; mehr Schutz durch p53 kostet also nicht zwangsläufig schnelleres Altern, und der behauptete Zielkonflikt wird dadurch nicht gestützt. Für den Menschen gibt es bislang keinen überzeugenden Fall, in dem das verantwortliche Gen identifiziert wäre. Ein stimmiges Erklärungsbild ersetzt keine Evidenz, und Befunde aus einer Art lassen sich nicht ungeprüft auf eine andere übertragen.","coreRule":"⚡ Ein schönes Erklärungsbild ist noch kein Befund: Prüfe, ob Experimente es tatsächlich stützen und ob sie für die Art gelten, über die du sprichst.","beleg":"Werkstück C.4.8 (Das Adaptive Talent; Anwendung & Relevanz); Fn. gl-c-p53 (García-Cao u. a. 2002, EMBO J 21 (22), S. 6225–6235); Fn. gl-c-austad (Austad/Hoffman 2018, S. 289)","status":"entwurf","scenario":"Eine Biologin sagt: „p53 ist das klassische Beispiel für antagonistische Pleiotropie: In der Jugend schützt das Gen vor Krebs, im Alter treibt es den Zerfall voran.“ Du kennst zwei Befunde: Mäuse mit zusätzlichen, normal gesteuerten p53-Kopien waren besser vor Krebs geschützt und alterten trotzdem normal. Bei Fadenwürmern, Fliegen und Mäusen sind mehrere Gene mit solchen Zielkonflikten beschrieben, beim Menschen ist bislang kein Gen dieser Art zweifelsfrei identifiziert.","kurz":"Plausibel ist die Idee, belegt ist sie nicht: Mäuse mit zusätzlichen p53-Kopien waren besser vor Krebs geschützt und alterten normal, beim Menschen fehlt ein gesichertes Beispiel. Der Fehler wäre, ein stimmiges Erklärungsbild schon für Evidenz zu halten.","prueffrage":"Was geschah bei den Mäusen mit zusätzlichen p53-Kopien mit der Krebsrate und mit der Alterung?","rueckmeldung":[{"option":1,"text":"Dass die Aussage nicht gesichert ist, stimmt. Widerlegt ist sie aber nicht: Der Krebsschutz durch p53 wurde in den Mäusen gerade bestätigt, und dass Apoptose nie gesunde Stammzellen trifft, lässt sich nicht halten."},{"option":2,"text":"Vorsicht beim Übertragen von einer Art auf eine andere ist berechtigt. Die Mäuse mit zusätzlichem p53 alterten aber normal, nicht schneller; der Befund stützt die Aussage also nicht."},{"option":3,"text":"„Unbegründet“ geht zu weit, auch wenn die Aussage nicht bewiesen ist: Für die Annahme, p53 wirke nur im Alter, gibt es keinen Beleg, und die Mäuse mit zusätzlichem p53 waren besser vor Krebs geschützt."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"García-Cao, I. u. a. (2002): „Super p53“ mice exhibit enhanced DNA damage response, are tumor resistant and age normally. EMBO Journal 21(22), 6225–6235","oeffentlich":true,"doi":"10.1093/emboj/cdf595","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC137187/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Austad, S. N.; Hoffman, J. M. (2018): Is antagonistic pleiotropy ubiquitous in aging biology? Evolution, Medicine, and Public Health 2018(1), 287–294","oeffentlich":true,"doi":"10.1093/emph/eoy033","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"58e56e54536a020b"}},{"id":"qx-c2-023","clusterId":"C","werkstueckRef":"C.4.9","stufe":1,"question":"Welche Erklärung passt am besten zu diesem Muster?","options":["Wo Tiere ohnehin früh sterben, lohnt sich Körperwartung kaum; Art A investiert eher in Fortpflanzung und altert deshalb früher.","Art A hat durch ihr kurzes Leben weniger Zeit, Schäden anzusammeln, und müsste deshalb im Labor langsamer altern als Art B.","Die Lebensdauer einer Art ist ein Zufallswert, der sich von Art zu Art unterscheidet, ohne dass das Sterberisiko in der Natur dabei eine Rolle spielt.","Art A wird im Labor durch die fehlende Gefahr krank, weil ihr Körper ohne Fressfeinde nicht mehr auf Reparatur eingestellt ist."],"correctIndex":0,"explanation":"Die Evolution investiert nur so viel in Reparatur und Wartung des Körpers („Soma“), wie nötig ist, um ihn bis zur erfolgreichen Fortpflanzung am Leben zu erhalten (Disposable-Soma-Theorie). Stirbt eine Art in der Natur meist früh, bringt aufwendige Wartung für spätere Jahre kaum zusätzlichen Nachwuchs; die Ressourcen gehen besser in Fortpflanzung. Übertragen auf die Beobachtung heißt das: Art A altert auch im geschützten Labor früher, weil Selektion ihre Ausstattung auf die kurze Lebenserwartung in der Natur eingestellt hat (eine Übertragung der Theorie, kein direkter Befund). Die anderen Erklärungen tragen nicht: Weniger Zeit für Schäden erklärt nicht, warum Art A im Labor schneller altert; bei nur zwei Arten ist Zufall zwar nicht ausgeschlossen, doch die Behauptung, das Sterberisiko spiele keine Rolle, übergeht gerade die naheliegende Erklärung für den Unterschied. Und ein einzelnes Tier verliert im Labor seine Reparaturfähigkeit nicht, weil die Gefahr fehlt, denn diese Ausstattung ist evolutionär festgelegt.","coreRule":"⚡ Wartung lohnt sich nur so weit, wie ein Körper realistisch lebt, um seine Gene weiterzugeben.","beleg":"Werkstück C.4.9 (Ebene 1: Die Biologie, Disposable Soma Theory; Anwendung auf Fressfeinde und Laborbedingungen ist Transfer, nicht im Buchtext belegt)","status":"entwurf","scenario":"Eine Forscherin vergleicht zwei ähnlich große Tierarten: Art A hat viele Fressfeinde und stirbt in der Natur meist schon im ersten Lebensjahr, Art B hat kaum Feinde und lebt oft viele Jahre. Im Labor, wo keine Fressfeinde drohen, zeigt Art A nach kurzer Zeit deutliche Alterserscheinungen, Art B erst viel später.","kurz":"Wo Tiere in der Natur meist früh sterben, brächte aufwendige Körperwartung für spätere Jahre kaum zusätzlichen Nachwuchs; Art A ist durch Selektion darauf eingestellt und altert deshalb auch im Labor früher. Diese Deutung ist eine begründete Übertragung, kein direkter Befund.","prueffrage":"Worin unterscheiden sich die beiden Arten in der Natur, und bleibt dieser Unterschied im Labor sichtbar, obwohl dort keine Fressfeinde drohen?","rueckmeldung":[{"option":1,"text":"Wer früh stirbt, hat tatsächlich weniger Zeit, Schäden anzusammeln. Das spräche aber für langsameres Altern von Art A, während sie im Labor früher altert; die Beobachtung widerlegt diese Erklärung also."},{"option":2,"text":"Bei nur zwei Arten ist Zufall zwar nicht ganz ausgeschlossen. Dass das Sterberisiko in der Natur keine Rolle spielt, trägt aber nicht: Gerade es liefert eine Erklärung dafür, dass die gefährdete Art auch im Labor früher altert."},{"option":3,"text":"Hier wird die Art mit dem einzelnen Tier verwechselt: Wie viel ein Körper in Reparatur investiert, hat die Selektion über viele Generationen festgelegt. Ein Tier verliert im Labor nicht seine Reparaturfähigkeit, weil die Gefahr fehlt."}],"familie":"auslese-statt-plan","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Austad, S. N.; Hoffman, J. M. (2018): Is antagonistic pleiotropy ubiquitous in aging biology? Evolution, Medicine, and Public Health 2018(1), 287–294","oeffentlich":true,"doi":"10.1093/emph/eoy033","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Williams, G. C. (1957): Pleiotropy, natural selection, and the evolution of senescence. Evolution 11(4), 398–411 (doi 10.1111/j.1558-5646.1957.tb02911.x)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"9b8a68728b489501"}},{"id":"qx-c2-024","clusterId":"C","werkstueckRef":"C.4.9","stufe":2,"question":"Welche Erklärung für die niedrige Krebsrate bei Kindern ist am besten begründet?","options":["Die Zellen von Kindern teilen sich so selten, dass kaum Fehler entstehen, und die Schutzmechanismen gegen entartete Zellen werden erst im höheren Alter aktiv, wenn die Mutationen zahlreicher werden.","Ein Schutzmechanismus erkennt und beseitigt beschädigte Zellen früh, und in jungen Zellen haben sich erst wenige Mutationen angesammelt.","Das Immunsystem von Kindern erkennt die meisten Krebszellen früh, und im jungen Körper werden Mutationen meist sofort repariert.","Schutzgene verhindern Mutationen schon beim Kopieren der DNA weitgehend, und die Zellen von Kindern besitzen kaum Gene, die zu Krebstreibern entarten könnten."],"correctIndex":1,"explanation":"„Jung“ ist hier keine Erklärung, sondern ein Sammelbegriff für zwei Mechanismen. Ein Wächtergen wie p53 erkennt Zellen mit beschädigter DNA und kann ihren programmierten Zelltod (Apoptose) auslösen, bevor sie zu Krebszellen werden; dieser Schutz wirkt von Anfang an. Den Unterschied zwischen Kindern und Älteren macht vor allem die Zahl der Mutationen: Junge Zellen haben erst wenige angesammelt, und mit den Jahren können auch Schutzgene wie p53 selbst getroffen werden. Die übrigen Antworten tragen nicht: Kinderzellen teilen sich im Wachstum eher häufig als selten, das Immunsystem erkennt längst nicht die meisten Krebszellen, Reparatur geschieht weder sofort noch fehlerfrei, die Fehlerkorrektur beim Kopieren der DNA lässt immer einige Fehler durch, und Kinder tragen dieselben Gene wie Erwachsene. Wer eine Alltagserklärung wie „weil jung“ prüft, fragt also: Welche Mechanismen stecken dahinter, und trägt jeder einzelne?","coreRule":"⚡ Prüfe Sammelbegriffe wie „weil jung“: Zerlege sie in die Mechanismen, die tatsächlich wirken. Hier schützt der Wächter p53, und es gibt noch wenig Fehler, die sich angehäuft haben.","beleg":"Werkstück C.4.9 (Der Wächter kehrt zurück, zweiter Absatz); Verweis auf C.4.4","status":"entwurf","scenario":"Eine Kollegin sagt: „Krebs ist eine Alterskrankheit, bei Kindern kommt er kaum vor. Das liegt doch nur daran, dass Kinder jung sind, mehr steckt nicht dahinter.“ Du willst wissen, was dieses „jung“ konkret bedeutet.","kurz":"„Jung“ ist keine Erklärung, sondern steht für zwei Mechanismen: Ein Wächtergen wie p53 kann Zellen mit beschädigter DNA früh in den Zelltod schicken, und junge Zellen haben erst wenige Mutationen angesammelt, die entarten könnten.","prueffrage":"Was genau unterscheidet eine junge Zelle von einer alten, und lässt sich jeder dieser Unterschiede einzeln benennen?","rueckmeldung":[{"option":0,"text":"Dass sich mit dem Alter Mutationen häufen, stimmt. Die Schutzmechanismen wirken aber schon in der Jugend, nicht erst im Alter, und selten teilen sich Kinderzellen nicht: Im Wachstum teilen sie sich sogar besonders häufig."},{"option":2,"text":"Immunabwehr und DNA-Reparatur gibt es wirklich. Doch die Abwehr erkennt längst nicht die meisten Krebszellen früh, und Reparatur geschieht weder sofort noch fehlerfrei; als Hauptgrund für den Altersunterschied trägt das nicht."},{"option":3,"text":"Fehlerkorrektur beim Kopieren der DNA gibt es tatsächlich, doch sie lässt immer einige Fehler durch, die sich mit den Jahren ansammeln. Und Kinder tragen dieselben Gene wie Erwachsene, nur mit erst wenigen Mutationen."}],"familie":"genau-unterscheiden","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Zhang, H. u. a. (2024): Unraveling the Guardian: p53’s Multifaceted Role in the DNA Damage Response and Tumor Treatment Strategies. International Journal of Molecular Sciences 25(23), 12928","oeffentlich":true,"doi":"10.3390/ijms252312928","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC11641486/","abruf":"2026-10-12"},{"typ":"url","kurz":"National Cancer Institute: The Genetics of Cancer","oeffentlich":true,"url":"https://www.cancer.gov/about-cancer/causes-prevention/genetics","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"6412f30ad479154a"}},{"id":"qx-c2-025","clusterId":"C","werkstueckRef":"C.4.9","stufe":3,"question":"Eine Forscherin behauptet: „Freie Radikale rosten uns zu Tode – oxidativer Schaden ist die Ursache des Alterns.“ Welche Beobachtung spricht am stärksten gegen diese Behauptung?","options":["Bei Mäusen beschleunigten zusätzliche oxidative Schäden das Altern nicht, und der Nacktmull wird trotz hoher oxidativer Schäden außergewöhnlich alt.","Bei Mäusen verlängerte fast jede Veränderung der Schutzenzyme das Leben deutlich, aber beim Menschen blieb der Effekt in Studien bisher aus.","In Zellversuchen wirken freie Radikale vor allem als Signalstoffe, während sie Proteine, Fette und DNA kaum noch schädigen können.","Freie Radikale entstehen vor allem durch äußere Einflüsse wie Rauchen oder UV-Strahlung, kaum jedoch im Stoffwechsel der Zellen."],"correctIndex":0,"explanation":"Wenn oxidativer Schaden die Ursache des Alterns wäre, müsste jeder Eingriff, der ihn verändert, auch die Lebensdauer verändern. Genau das tritt nicht ein: Mehr oxidativer Schaden beschleunigte das Altern von Mäusen nicht, und eine Art mit hohen oxidativen Schäden wird dennoch außergewöhnlich alt. Auch Veränderungen der Schutzenzyme änderten die Lebensdauer von Mäusen in einer großen Versuchsreihe nur in einem von 18 Fällen. Die anderen Antworten behaupten Dinge, die nicht stimmen: Radikale entstehen sehr wohl im Stoffwechsel (in den Mitochondrien), sie schädigen Proteine, Fette und DNA tatsächlich, und Veränderungen der Schutzenzyme verlängerten das Leben eben nicht durchgängig. Weil dieselben Moleküle auch als Signalstoffe wirken, gilt oxidativer Schaden heute als ein Baustein des Alterns unter vielen, nicht als seine Ursache. Wer eine Theorie prüft, fragt also: Was müsste gelten, wenn sie stimmt – und tritt es ein?","coreRule":"⚡ Prüfe eine Ursachenbehauptung mit der Gegenprobe: Ändert sich das Ergebnis, wenn du die vermutete Ursache veränderst? Oxidativer Schaden ist ein Baustein des Alterns, nicht seine alleinige Ursache.","beleg":"Werkstück C.4.9 (Ebene 2: Oxidativer Stress); Fn. gl-c-radikale (Pérez u. a. 2009: nur 1 von 18 Veränderungen der Schutzenzyme änderte die Lebensdauer; López-Otín u. a. 2013: mehr oxidative Schäden beschleunigen das Altern nicht; Gladyshev 2014; zum Nacktmull Verweis auf Andziak u. a. 2006, Werkstück C.4.11)","status":"entwurf","scenario":"Die Theorie der freien Radikale galt lange als wichtigste Erklärung des Alterns. Du prüfst, ob sie sich halten lässt.","kurz":"Wäre oxidativer Schaden die Ursache des Alterns, müsste mehr davon das Altern beschleunigen und eine Art mit viel davon früh altern. Beides trat nicht ein. Der Fehler wäre, bloße Beteiligung mit Ursache gleichzusetzen.","prueffrage":"In welchen Versuchen wurde der oxidative Schaden gezielt verändert, und wie alt wurden die Tiere danach?","rueckmeldung":[{"option":1,"text":"Das Mausmodell wirkt überzeugend, und die Lücke zum Menschen scheint der einzige Haken. In einer großen Versuchsreihe änderten Eingriffe in die Schutzenzyme die Lebensdauer aber nur in einem von 18 Fällen."},{"option":2,"text":"Dass dieselben Moleküle auch als Signalstoffe wirken, stimmt und relativiert die Theorie. Die Behauptung, sie schädigten Proteine, Fette und DNA kaum noch, stimmt jedoch nicht: Sie schädigen diese tatsächlich."},{"option":3,"text":"Rauchen und UV erzeugen tatsächlich freie Radikale. Sie entstehen aber sehr wohl auch im Stoffwechsel, in den Mitochondrien. Außerdem sagt die Herkunft nichts darüber, ob der Schaden das Altern verursacht."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Pérez, V. I. u. a. (2009): Is the oxidative stress theory of aging dead? Biochimica et Biophysica Acta 1790(10), 1005–1014","oeffentlich":true,"doi":"10.1016/j.bbagen.2009.06.003","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC2789432/","abruf":"2026-10-12"},{"typ":"doi","kurz":"López-Otín, C. u. a. (2013): The Hallmarks of Aging. Cell 153(6), 1194–1217, Abschnitt „Mitochondrial Dysfunction“","oeffentlich":true,"doi":"10.1016/j.cell.2013.05.039","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3836174/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Andziak, B. u. a. (2006): High oxidative damage levels in the longest-living rodent, the naked mole-rat. Aging Cell 5(6), 463–471 (doi 10.1111/j.1474-9726.2006.00237.x)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"0d7e66a63d9c42c7"}},{"id":"qx-c2-026","clusterId":"C","werkstueckRef":"C.4.9","stufe":4,"question":"Welche Einschätzung des Ansatzes ist am besten begründet?","scenario":"Ein Start-up wirbt für einen Wirkstoff, der gezielt „Zombie-Zellen“ (seneszente Zellen) aus dem Gewebe entfernen soll, und nennt ihn den „ersten Schritt zur Verjüngung“. Eine Investorin fragt dich, was man davon realistischerweise erwarten darf.","options":["Der Ansatz behandelt nur die Folgen des Alterns: Wie jede Krankheitstherapie lindert er Beschwerden, ohne den zugrunde liegenden Verschleiß zu berühren, und taugt daher nicht als Verjüngung.","Der Ansatz greift die genetischen Grundlagen des Alterns an: Er verändert Gene, die früh im Leben nützen und später schaden, und könnte das Altern damit an der Wurzel stoppen.","Der Ansatz zielt darauf, den zellulären Verschleiß zu verlangsamen: Er entfernt Zellen, die sich angesammelt haben, und soll das Altern so bremsen, ohne in die Gene einzugreifen.","Der Ansatz ist wissenschaftlich gegenstandslos: Zellen, die ihre Teilung eingestellt haben, richten im Gewebe keinen Schaden an, also gibt es nichts zu entfernen."],"correctIndex":2,"explanation":"Entscheidend ist, an welcher Stelle der Ansatz eingreift. Das Entfernen seneszenter „Zombie-Zellen“ setzt am Verschleiß der Zellen an und soll ihn verlangsamen, ähnlich wie das Ankurbeln der zelleigenen Reinigungsprozesse (Autophagie). Das ist weder bloße Symptombehandlung, wie sie die klassische Medizin bei Herzinfarkt, Krebs oder Alzheimer betreibt, noch ein Eingriff in Gene oder Epigenetik, wie ihn Verfahren wie CRISPR oder die Reprogrammierung von Zellen bedeuten würden. Ob und wie gut das beim Menschen funktioniert, sagt diese Einordnung nicht, und das Altern selbst abzuschaffen, ist damit ohnehin nicht gemeint. Eine Werbeaussage wie „Verjüngung“ verlangt deshalb Belege aus Studien am Menschen, nicht nur ein plausibles Wirkprinzip.","coreRule":"⚡ Frag bei Anti-Aging-Versprechen, wo der Ansatz eingreift: bei den Folgen (Krankheiten), beim Verschleiß (Zellen, Chemie) oder bei den Grundlagen (Gene). Daran hängt, was er leisten kann und was nicht.","beleg":"Werkstück C.4.9 (Anwendung & Relevanz, Die drei Stufen des Anti-Aging)","status":"entwurf","kurz":"Der Ansatz setzt am Verschleiß an: Er entfernt angesammelte Zellen, ohne in Gene einzugreifen. Das ist mehr als Symptombehandlung, aber keine Abschaffung des Alterns, und die Wirkung beim Menschen muss erst belegt werden.","prueffrage":"Welche Ergebnisse aus Studien am Menschen nennt das Start-up für seinen Wirkstoff, und was genau wurde dort gemessen?","rueckmeldung":[{"option":0,"text":"Dass „Verjüngung“ ohne Belege am Menschen zu viel verspricht, stimmt. Der Ansatz ist aber keine reine Symptombehandlung wie bei Herzinfarkt oder Krebs, sondern setzt am zellulären Verschleiß an und soll ihn verlangsamen."},{"option":1,"text":"Ein Eingriff in die Gene wirkt wie der tiefste Ansatz am Altern. Hier werden aber Zellen entfernt, nicht Gene verändert; in Gene oder ihre Steuerung griffen etwa CRISPR oder die Reprogrammierung von Zellen ein."},{"option":3,"text":"Aus der Teilungsruhe dieser Zellen folgt nicht, dass sie harmlos sind: Sie bleiben im Gewebe und können es mit ausgeschütteten Entzündungsstoffen belasten. Wie viel ihr Entfernen beim Menschen bringt, ist allerdings noch offen."}],"familie":"genau-unterscheiden","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Chaib, S.; Tchkonia, T.; Kirkland, J. L. (2022): Cellular senescence and senolytics: the path to the clinic. Nature Medicine 28(8), 1556–1568","oeffentlich":true,"doi":"10.1038/s41591-022-01923-y","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC9599677/","abruf":"2026-10-12"},{"typ":"doi","kurz":"López-Otín, C. u. a. (2013): The Hallmarks of Aging. Cell 153(6), 1194–1217","oeffentlich":true,"doi":"10.1016/j.cell.2013.05.039","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3836174/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"47122b9158b4c50e"}},{"id":"qx-c2-027","clusterId":"C","werkstueckRef":"C.4.10","stufe":1,"question":"Ein Labor hält menschliche Bindegewebszellen in einer Petrischale mit bester Nährlösung, wechselt das Medium regelmäßig und hält alle Bedingungen konstant. Nach etwa 50 Teilungen stellen die Zellen die Teilung ein, bleiben aber am Leben. Was erklärt diesen Befund am besten?","options":["Die Zellen haben eine eigene Teilungsgrenze: Bei jeder Teilung verkürzen sich die Schutzkappen an den Chromosomenenden, bis die Zelle den Teilungsstopp auslöst.","Die Nährlösung ist mit der Zeit erschöpft, weil sich Zellen in einer Kultur gegenseitig die Nährstoffe wegnehmen und die Teilung dadurch zum Erliegen kommt.","Die Zellen teilen sich unbegrenzt, solange sie genug Energie bekommen; der Stopp nach etwa 50 Teilungen ist ein Messfehler durch alternde Kulturgefäße.","Die Zellen teilen sich nur auf äußere Aufforderung hin; nach etwa 50 Teilungen bleibt dieses Signal dauerhaft aus und die Zellen reagieren nicht mehr."],"correctIndex":0,"explanation":"Der Befund spricht gegen die Annahme, die Umgebung sei schuld: Die Bedingungen waren konstant und ideal, und der Teilungsstopp trat trotzdem nach etwa 50 Teilungen ein. Das deutet auf eine Grenze, die in der Zelle selbst liegt. Tatsächlich geht beim Kopieren der DNA bei jeder Teilung ein winziges Stück der Telomere verloren, der Schutzkappen an den Chromosomenenden (vergleichbar mit den Plastikkappen an Schnürsenkeln). Werden sie zu kurz, deutet die Zelle das als mögliche DNA-Schädigung, aktiviert das Wächter-Gen p53 und hört auf, sich zu teilen, ein Schutz vor Krebs. Die Zellen leben weiter, sind aber seneszent, gleichsam „Zombie-Zellen“. Diese nach Leonard Hayflick benannte Grenze zeigt früh, dass Altern auch von innen kommt. Sie bedeutet aber nicht, dass ein Programm den ganzen Körper altern lässt. Eine Erklärung durch erschöpfte Nährlösung scheitert daran, dass das Medium erneuert wurde und die Zellen ohnehin weiterleben.","coreRule":"⚡ Wenn ein Effekt trotz konstanter, idealer Außenbedingungen eintritt, such die Ursache im System selbst.","beleg":"Werkstück C.4.10 (Die tickende Uhr in der Petrischale; Kernidee; Kontext & Tiefe)","status":"entwurf","scenario":"Eine Kommilitonin sagt: „Zellen in einer idealen Umgebung müssten sich doch ewig teilen können. Wenn sie aufhören, muss die Nährlösung schuld sein.“ Du sollst beurteilen, ob das stimmt.","quote":"","quoteLabel":"","kurz":"Der Stopp kam trotz konstanter, bester Bedingungen, also liegt die Grenze in der Zelle selbst: Mit jeder Teilung werden die Telomere kürzer, bis die Zelle die Teilung einstellt. Die Umgebung als Ursache zu vermuten, ist der naheliegende Fehler.","prueffrage":"Was hat sich im Labor über die Zeit verändert, und was blieb für die Zellen konstant?","rueckmeldung":[{"option":1,"text":"Dass Kulturen Nährstoffe verbrauchen, ist grundsätzlich richtig. Hier wurde das Medium aber regelmäßig erneuert, und die Zellen leben weiter, sind also nicht verhungert. Eine erschöpfte Nährlösung erklärt den Stopp deshalb nicht."},{"option":2,"text":"Unbegrenzte Teilung gibt es bei manchen Zelllinien, etwa Krebszellen, nicht aber bei normalen Bindegewebszellen. Ein Messfehler wird im Befund nirgends angedeutet. Der Stopp tritt genau dort auf, wo er für gesunde Zellen zu erwarten ist."},{"option":3,"text":"Viele Zellen teilen sich tatsächlich erst nach Wachstumssignalen. Hier sind aber beste Bedingungen gegeben, und die Zellen leben weiter. Sie stellen die Teilung aktiv ein, weil die Telomere zu kurz sind, nicht weil ein Signal ausbleibt."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Roake & Artandi 2017, Control of Cellular Aging, Tissue Function, and Cancer by p53 Downstream of Telomeres, Cold Spring Harb Perspect Med 7(5) (PMC5411683)","oeffentlich":true,"doi":"10.1101/cshperspect.a026088","abruf":"2026-10-12"},{"typ":"url","kurz":"Shay & Wright 2000, Hayflick, his limit, and cellular ageing, Nat Rev Mol Cell Biol 1(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1038/35036093","url":"https://pubmed.ncbi.nlm.nih.gov/11413492/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Hayflick & Moorhead 1961, The serial cultivation of human diploid cell strains, Exp Cell Res 25","oeffentlich":false,"doi":"10.1016/0014-4827(61)90192-6"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"41b70871e91a3e08"}},{"id":"qx-c2-028","clusterId":"C","werkstueckRef":"C.4.10","stufe":2,"question":"Welche Erklärung ist am sparsamsten für diesen Befund?","options":["Die Zellen sterben sofort ab, die lebenden Zellen in der Schale sind nur Reste, die den Messungen entgangen sind.","Die Zellen stoppen die Teilung selbst, als Schutz vor Krebs, wenn sie die Verkürzung als mögliche DNA-Schädigung deuten; Tumorzellen umgehen diese Bremse.","Die Zellen verlängern ihre Schutzkappen wieder und teilen sich weiter; erst ein Mangel an Nährstoffen hält sie am Ende auf.","Die Zellen teilen sich ungebremst weiter, weil ihre Schutzgene bei verkürzten Chromosomenenden abgeschaltet werden, und werden so zu Tumorzellen."],"correctIndex":1,"explanation":"Der Befund enthält drei Hinweise: Die Nährlösung ist nicht der Engpass, die Zellen leben nach dem Stopp weiter, und die Chromosomenenden sind kürzer geworden. Das passt zu einer eingebauten Bremse: Bei jeder Teilung geht ein Stück der Schutzkappen (Telomere) verloren. Erreichen sie eine kritische Kürze, wird das als mögliche DNA-Schädigung gedeutet, das Wächter-Gen p53 stoppt die Teilung, und die Zelle bleibt als seneszente „Zombie-Zelle“ am Leben. Das verhindert, dass beschädigte Zellen sich unkontrolliert vermehren. Tumorzellen teilen sich unbegrenzt, weil sie oft das Enzym Telomerase reaktivieren und so die Grenze umgehen. Die übrigen Erklärungen scheitern an den Beobachtungen: Sofortiger Tod widerspricht den überlebenden Zellen, Nachlassen der Nährstoffe widerspricht der erneuerten Lösung, und ungebremstes Teilen widerspricht dem beobachteten Stopp.","coreRule":"⚡ Wähle die Erklärung, die alle Beobachtungen zugleich trägt, und prüfe jede Alternative an dem, was sie vorhersagen würde.","beleg":"Werkstück C.4.10 (Kontext & Tiefe, Der Seneszenz-Stopp; Anwendung & Relevanz)","status":"entwurf","scenario":"Ein Labor züchtet gesunde menschliche Zellen in einer Nährlösung, die immer wieder erneuert wird, sodass nichts knapp wird. Nach etwa 50 Teilungen hören die Zellen auf, sich zu teilen, bleiben aber am Leben und verbrauchen weiter Nährstoffe. Messungen zeigen, dass die Schutzkappen an den Chromosomenenden mit jeder Teilung kürzer geworden sind und nun eine kritische Länge erreicht haben. Gleichzeitig teilen sich Zellen aus einem Tumor unter denselben Bedingungen unbegrenzt weiter.","quote":"","quoteLabel":"","kurz":"Am sparsamsten ist eine eingebaute Bremse: Verkürzte Schutzkappen gelten als mögliche DNA-Schädigung, die Zelle stoppt die Teilung und bleibt am Leben. Der naheliegende Fehler ist, den Stopp mit Tod, Mangel oder Entartung zu verwechseln.","prueffrage":"Was lässt sich in der Schale beobachten, nachdem die Teilung aufgehört hat, und was zeigt die Messung an den Chromosomenenden?","rueckmeldung":[{"option":0,"text":"Wenn Zellen sich nicht mehr teilen, liegt es nahe, an ihr Absterben zu denken. Laut Befund bleiben sie aber am Leben und verbrauchen weiter Nährstoffe; übersehene Reste wären eine zusätzliche, unbelegte Annahme."},{"option":2,"text":"Tumorzellen kommen tatsächlich oft an der Verkürzung vorbei, und der Gedanke an eine Verlängerung passt zu dieser Beobachtung. Bei den gesunden Zellen wurden die Schutzkappen aber kürzer, und die Nährlösung wird erneuert, sodass nichts knapp wird."},{"option":3,"text":"Dass eine ausgefallene Kontrolle zu Krebs führen kann, stimmt. Hier ist es aber umgekehrt: Die Teilung hört beobachtbar auf, und das Schutzgen p53 wird bei der Verkürzung aktiv, statt abgeschaltet zu werden. Die Zellen werden nicht zu Tumorzellen."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Roake & Artandi 2017, Control of Cellular Aging, Tissue Function, and Cancer by p53 Downstream of Telomeres, Cold Spring Harb Perspect Med 7(5) (PMC5411683)","oeffentlich":true,"doi":"10.1101/cshperspect.a026088","abruf":"2026-10-12"},{"typ":"url","kurz":"Shay & Wright 2000, Hayflick, his limit, and cellular ageing, Nat Rev Mol Cell Biol 1(1) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1038/35036093","url":"https://pubmed.ncbi.nlm.nih.gov/11413492/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"826d081e477b21b4"}},{"id":"qx-c2-029","clusterId":"C","werkstueckRef":"C.4.10","stufe":3,"question":"Ein Forschungsteam schlägt vor, in gesunden Körperzellen das Enzym Telomerase dauerhaft zu aktivieren, damit sie sich unbegrenzt teilen können und das Altern aufgehalten wird. Krebszellen sind häufig deshalb „unsterblich“, weil sie Telomerase wieder anschalten. Welches Dilemma folgt daraus?","options":["Telomerase würde die Teilungsgrenze zwar verschieben, die Zellen aber zwingen, sich schneller zu teilen, sodass sie früher in den Ruhezustand übergehen.","Telomerase ist in gesunden Zellen ohnehin dauerhaft aktiv, sodass eine zusätzliche Aktivierung keinerlei Wirkung auf die Teilungsfähigkeit hätte.","Telomerase wirkt ausschließlich in Krebszellen, sodass gesundes Gewebe für sie grundsätzlich nicht zugänglich wäre, auch nicht durch Gentechnik.","Telomerase könnte gesunden Zellen dieselbe Unsterblichkeit geben wie Krebszellen, sodass die schützende Teilungsgrenze entfiele und das Krebsrisiko stiege."],"correctIndex":3,"explanation":"Normale Zellen können sich nur etwa 40 bis 60 Mal teilen. Wenn die Telomere kritisch kurz werden, deutet die Zelle das als mögliche gefährliche DNA-Schädigung, aktiviert das Wächter-Gen p53 und stellt die Teilung ein. Diese Grenze schützt damit vor Krebs. Krebszellen umgehen sie häufig, indem sie Telomerase reaktivieren. Wer Telomerase in gesunden Zellen aktiviert, nimmt ihnen deshalb dieselbe Bremse. Ein möglicher Gewinn (länger teilungsfähige Zellen) ist untrennbar mit einem Risiko (ungebremstes Wachstum geschädigter Zellen) verbunden. Das Dilemma entsteht, weil Nutzen und Schaden am selben Mechanismus hängen. Die anderen Aussagen scheitern an Tatsachen: Telomerase hebt die Hayflick-Grenze auf, von einer schnelleren Teilung oder einem früheren Ruhezustand kann keine Rede sein. Dass Krebszellen sie reaktivieren, zeigt zudem, dass sie in Zellen wirken kann, und die Aussage, sie sei in gesunden Zellen ohnehin dauerhaft aktiv, widerspricht der Grenze selbst: Wäre sie dort dauerhaft aktiv, gäbe es die Teilungsgrenze nicht.","coreRule":"⚡ Wer eine Schutzgrenze aufhebt, um einen Nutzen zu gewinnen, nimmt auch den Schutz weg, den sie geboten hat: Prüfe, wofür die Grenze da ist, bevor du sie abschaffen willst.","beleg":"Werkstück C.4.10 (Anwendung & Relevanz); vgl. Werkstück C.4.4","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Die Teilungsgrenze schützt vor Krebs, und Telomerase hebt sie auf. Wer das Altern bremsen will, nimmt gesunden Zellen damit dieselbe Bremse, die Krebszellen umgehen: Nutzen und Risiko hängen am selben Mechanismus.","prueffrage":"Was geschieht normalerweise, wenn die Telomere einer gesunden Zelle sehr kurz geworden sind?","rueckmeldung":[{"option":0,"text":"Dass Telomerase an der Teilungsgrenze ansetzt, stimmt. Sie verlängert aber die Telomere und hebt die Grenze auf, statt die Zellen zu hetzen. Von schnellerer Teilung oder früherem Ruhezustand kann keine Rede sein."},{"option":1,"text":"Wirkungslos wäre eine zusätzliche Aktivierung nur, wenn Telomerase in gesunden Körperzellen längst dauerhaft arbeitete. Dann gäbe es keine Teilungsgrenze; tatsächlich teilen sich normale Zellen aber nur etwa 40 bis 60 Mal."},{"option":2,"text":"Weil Krebs so eng mit Telomerase verbunden ist, wirkt sie wie ein reines Krebsenzym. Krebszellen schalten sie aber häufig nur wieder an, und das zeigt, dass sie in Zellen wirken kann, auch in gesunden."}],"familie":"nutzen-und-risiko-abwaegen","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Roake & Artandi 2017, Control of Cellular Aging, Tissue Function, and Cancer by p53 Downstream of Telomeres, Cold Spring Harb Perspect Med 7(5) (PMC5411683)","oeffentlich":true,"doi":"10.1101/cshperspect.a026088","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Hayflick & Moorhead 1961, The serial cultivation of human diploid cell strains, Exp Cell Res 25","oeffentlich":false,"doi":"10.1016/0014-4827(61)90192-6"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"7666b8a5abcc5fb1"}},{"id":"qx-c2-030","clusterId":"C","werkstueckRef":"C.4.10","stufe":4,"question":"Wie ist die Aussage „Die Forschung hat bewiesen: höchstens 120 bis 150 Jahre“ einzuordnen?","scenario":"Ein Artikel meldet: „Die Forschung hat bewiesen: Der Mensch kann höchstens 120 bis 150 Jahre alt werden.“ Als Grundlage dient eine Modellrechnung, die aus den Blutwerten von Hunderttausenden Menschen schätzt, wann die körperliche Widerstandsfähigkeit vollständig verloren ginge. Andere Forschergruppen werten stattdessen die tatsächlich erreichten Höchstalter aus und kommen zu voneinander abweichenden Ergebnissen: Die eine sieht die Höchstalter seit Jahrzehnten bei 114 Jahren stagnieren, die andere findet ab 105 Jahren ein Sterblichkeitsplateau ohne erkennbare Grenze.","options":["Als Schätzung eines Modells; weil Auswertungen tatsächlicher Höchstalter zu abweichenden Ergebnissen kommen, ist „bewiesen“ zu stark.","Als gesichertes Ergebnis, weil die Auswertung tatsächlicher Höchstalter die Modellrechnung bestätigt und keinen Spielraum für mehr Lebensjahre lässt.","Als widerlegt, weil das Sterblichkeitsplateau ab 105 Jahren beweist, dass Menschen unbegrenzt leben können.","Als bestätigt, weil die Modellrechnung auf Daten von Hunderttausenden Menschen beruht und eine so große Datenmenge ein Ergebnis zuverlässig absichert."],"correctIndex":0,"explanation":"Eine Modellrechnung, die aus Blutwerten einen Punkt „totalen Resilienzverlusts“ schätzt (Pyrkov u. a. 2021: etwa 120–150 Jahre), ist eine Modellschätzung, kein direkt beobachteter Wert. Das zeigt schon der Blick auf die Gegenseite: Eine Auswertung der jährlichen Höchstalter (Dong u. a. 2016) sieht seit den 1990er Jahren eine Stagnation bei 114 Jahren, eine andere (Barbi u. a. 2018) ab 105 Jahren ein Sterblichkeitsplateau ohne erkennbare Grenze. Wo sich methodisch unterschiedliche Auswertungen nicht einig sind, ist die Frage offen. Umgekehrt findet die Plateau-Auswertung lediglich keine erkennbare Grenze; das ist kein Beleg für Unbegrenztheit. Und eine große Stichprobe ändert an der Natur einer Modellschätzung nichts. Wer eine offene Forschungsfrage als „bewiesen“ meldet, zeigt mehr Sicherheit, als die Belege hergeben.","coreRule":"⚡ Eine Modellschätzung ist kein Beweis, und widersprechen sich unabhängige Auswertungen, ist die Frage offen.","beleg":"Werkstück C.4.10 (Die Berechnungen; Der Stand der Forschung); Fn. gl-c-lebensspanne (Pyrkov u. a. 2021, Nat. Commun. 12, Art. 2765); Fn. gl-c-lebensspanne-dissens (Dong u. a. 2016, Nature 538, S. 257–259; Barbi u. a. 2018, Science 360, S. 1459–1461; Warner u. a. 2005)","status":"entwurf","kurz":"Aus Blutwerten wird eine Grenze nur geschätzt, nicht beobachtet, und Auswertungen tatsächlicher Höchstalter kommen zu abweichenden Ergebnissen. Wo sich Methoden nicht einig sind, ist die Frage offen; „bewiesen“ meldet mehr Sicherheit, als die Belege hergeben.","prueffrage":"Was wurde für die Modellrechnung tatsächlich gemessen, und welcher Wert wurde daraus erst errechnet?","rueckmeldung":[{"option":1,"text":"Die Auswertungen tatsächlicher Höchstalter bestätigen die Modellrechnung gerade nicht: Die eine sieht Stagnation bei 114 Jahren, die andere ein Plateau ohne erkennbare Grenze. Aus solch abweichenden Ergebnissen folgt kein gesichertes Ergebnis."},{"option":2,"text":"Das Plateau ab 105 Jahren spricht tatsächlich gegen „bewiesen“. Es zeigt aber nur, dass keine Grenze erkennbar ist, und das ist noch kein Beleg dafür, dass es keine gibt; die Frage bleibt offen, nicht entschieden."},{"option":3,"text":"Hunderttausende Datensätze beeindrucken, ändern aber nichts an der Art der Aussage: Es bleibt eine Schätzung aus Blutwerten und keine beobachtete Höchstgrenze. Eine große Datenmenge macht aus einer Modellschätzung noch keinen Beweis."}],"familie":"wiederholung-abwarten","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Pyrkov u. a. 2021, Longitudinal analysis of blood markers reveals progressive loss of resilience and predicts human lifespan limit, Nature Communications 12 (PMC8149842)","oeffentlich":true,"doi":"10.1038/s41467-021-23014-1","abruf":"2026-10-12"},{"typ":"doi","kurz":"Dong, Milholland & Vijg 2016, Evidence for a limit to human lifespan, Nature 538 (PMC11673931)","oeffentlich":true,"doi":"10.1038/nature19793","abruf":"2026-10-12"},{"typ":"doi","kurz":"Barbi u. a. 2018, The plateau of human mortality: Demography of longevity pioneers, Science 360 (PMC6457902)","oeffentlich":true,"doi":"10.1126/science.aat3119","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"333cdbb440d9d7ca"}},{"id":"qx-c2-031","clusterId":"C","werkstueckRef":"C.4.11","stufe":1,"question":"Ein Museumstext behauptet: „Vor etwa 300 Millionen Jahren gab es Libellen mit der Spannweite von Möwen – das beweist, dass die Schwerkraft damals deutlich geringer war.“ Welche Prüfung trifft den Kern der Behauptung am besten?","options":["Gibt es unabhängige Belege für eine andere Schwerkraft, und erklärt sich die Größe auch anders?","Wie groß war die Spannweite im Durchschnitt, und lässt sich daraus das Gewicht berechnen?","Gab es damals auch kleinere Insekten, und lässt sich daraus die Artenzahl ableiten?","Wie viele dieser Libellen wurden gefunden, und stammen sie aus demselben Land?"],"correctIndex":0,"explanation":"Der Schluss „riesige Tiere, also geringere Schwerkraft“ ist eine Erklärung unter mehreren. Gute Prüfung heißt, nach unabhängigen Belegen für genau diese Ursache zu fragen und zu klären, ob eine andere Erklärung dasselbe leistet. Hier gibt es sie: Nach gängigen Modellen (Berner 2006; Krause u. a. 2018) lag der Sauerstoffgehalt vor rund 300 Millionen Jahren bei etwa 25 bis 30 Prozent (heute 21), gestützt durch fossile Holzkohle. Insekten haben ein einfaches Atmungssystem, das von höherer Sauerstoffkonzentration profitierte; das macht große Körper plausibel (Clapham/Karr 2012). Für eine andere Schwerkraft gibt es keinen Beleg; die Größe lässt sich auch ohne diese Annahme über den Sauerstoff erklären. Auch die Sauerstofferklärung bleibt eine begründete Vermutung, kein bewiesener Befund. Fragen nach Durchschnittsspannweite, Artenzahl oder fossilen Fundorten ändern nichts daran, ob die behauptete Ursache stimmt.","coreRule":"⚡ Eine Behauptung prüfst du, indem du nach unabhängigen Belegen für genau die genannte Ursache fragst und nach einfacheren Erklärungen suchst.","beleg":"Werkstück C.4.11 (Der Sauerstoffgehalt); Fn. gl-c-karbon (Sauerstoffwerte: Berner 2006, Krause u. a. 2018; Insektengröße: Clapham/Karr 2012)","status":"entwurf","scenario":"Fossilien aus dem Karbon belegen riesige libellenähnliche Insekten, sogenannte Riesenlibellen. Zugleich weisen unabhängige Spuren (etwa fossile Holzkohle) und mehrere Klimamodelle auf einen Sauerstoffanteil der Luft von etwa 25 bis 30 Prozent hin, gegenüber 21 Prozent heute.","kurz":"Der Text macht aus „riesige Libellen“ den Schluss „geringere Schwerkraft“, obwohl das nur eine mögliche Erklärung ist. Tragfähig ist die Prüfung, ob es dafür eigene Belege gibt und ob sich die Größe anders erklären lässt, etwa durch mehr Sauerstoff in der Luft.","prueffrage":"Was an der Behauptung im Museumstext ist durch Fossilien belegt, und was ist daraus erst gefolgert?","rueckmeldung":[{"option":1,"text":"Spannweite und Gewicht zu klären, wirkt gründlich, denn Zahlen schaffen Klarheit über die Tiere selbst. Ob aber die Schwerkraft die Ursache war, entscheidet sich damit nicht: Auch ein genau bekanntes Gewicht passt zu mehr als einer Erklärung."},{"option":2,"text":"Der Blick auf die übrigen Insekten gibt Kontext zur damaligen Tierwelt. Die Behauptung dreht sich aber um die Ursache der Riesengröße, und dazu liefern Artenzahl und kleinere Verwandte weder einen Beleg für die Schwerkraft noch eine Alternative."},{"option":3,"text":"Nach Zahl und Herkunft der Funde zu fragen, wäre eine gute Quellenfrage, wenn die Existenz der Tiere fraglich wäre. Hier belegen Fossilien die Riesenlibellen aber; angezweifelt wird der Schluss auf die Schwerkraft, und den klärt kein Fundort."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Krause u. a. 2018, Stepwise oxygenation of the Paleozoic atmosphere, Nature Communications 9 (PMC6172248)","oeffentlich":true,"doi":"10.1038/s41467-018-06383-y","abruf":"2026-10-12"},{"typ":"doi","kurz":"Clapham & Karr 2012, Environmental and biotic controls on the evolutionary history of insect body size, PNAS 109(27) (PMC3390886)","oeffentlich":true,"doi":"10.1073/pnas.1204026109","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Berner 2006, GEOCARBSULF: A combined model for Phanerozoic atmospheric O2 and CO2, Geochim Cosmochim Acta 70(23)","oeffentlich":false,"doi":"10.1016/j.gca.2005.11.032"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"929aa2d91d33f4ae"}},{"id":"qx-c2-032","clusterId":"C","werkstueckRef":"C.4.11","stufe":2,"question":"Eine Schülerin behauptet: „Ein Blauwal ist so riesig, weil Meerestiere einfach stärkere Gene für Wachstum haben als Landtiere.“ Was spricht am stärksten gegen diese Erklärung?","options":["Ein Tier im Wasser wird vom Auftrieb getragen, ein Landtier muss sein ganzes Gewicht selbst stützen und braucht dafür im Verhältnis immer massivere Knochen.","Meerestiere leben in kälterem Wasser, deshalb ist ihr Stoffwechsel langsamer und sie werden größer als Landtiere.","Meerestiere nehmen über das Wasser mehr Sauerstoff auf, wodurch ihre Zellen größer werden dürfen als die Zellen von Landtieren.","Große Tiere brauchen mehr Nahrung, und im Meer ist das Nahrungsangebot größer, sodass die Gene für Größe dort häufiger zum Zug kommen."],"correctIndex":0,"explanation":"Die Erklärung über „stärkere Gene“ übersieht, dass die Umgebung die Möglichkeiten vorgibt. Wasser trägt einen großen Teil des Körpergewichts durch Auftrieb, sodass ein Meerestier sein Gewicht kaum selbst stützen muss. An Land setzt die Schwerkraft dagegen eine Obergrenze: Je schwerer ein Landtier wird, desto massiver müssen seine tragenden Knochen im Verhältnis werden; schon Galilei hielt 1638 fest, dass Riesentiere im Wasser bestehen können, an Land aber nicht ohne veränderte Körperproportionen. Reichlich Nahrung ist für Riesen wie den Blauwal zwar eine Voraussetzung, erklärt aber nicht, warum ein so schweres Tier nur im Wasser bestehen kann, und die Antwort mit den Genen stützt die These der Schülerin sogar. Ein langsamer Stoffwechsel in der Kälte passt nicht zum warmblütigen Wal, und Wasser enthält weniger gelösten Sauerstoff als Luft.","coreRule":"⚡ Bevor du Unterschiede den Genen zuschreibst, prüfe die physikalischen Rahmenbedingungen: An Land begrenzt die Schwerkraft die Größe, im Wasser trägt der Auftrieb mit.","beleg":"Werkstück C.4.11 (Die Stärke der Erdanziehungskraft, Blauwal/Auftrieb); Fn. gl-c-schwerkraft (Galilei 1638: Riesentiere im Wasser; Campione/Evans 2012, BMC Biology 10, 60)","status":"entwurf","scenario":"Die Größe von Tieren hängt nicht nur von ihren Genen ab, sondern auch von den physikalischen Bedingungen, unter denen sie leben. Landtiere und Meerestiere tragen ihr Gewicht unter sehr verschiedenen Bedingungen.","kurz":"Wasser trägt über den Auftrieb einen großen Teil des Gewichts, an Land setzt die Schwerkraft dagegen eine Obergrenze. Die Genthese übersieht, dass die Umgebung mitbestimmt, wie groß ein Tier überhaupt werden kann.","prueffrage":"Wie schwer werden die größten Tiere im Meer und an Land, und worin unterscheiden sich ihre Lebensbedingungen außer in den Genen?","rueckmeldung":[{"option":1,"text":"Kälte und ein langsamer Stoffwechsel wirken wie ein Grund für Größe. Der Blauwal ist aber warmblütig und hält seine Körpertemperatur auch im kalten Wasser hoch; ein durch Kälte verlangsamter Stoffwechsel passt deshalb nicht zu ihm."},{"option":2,"text":"Mehr Sauerstoff klingt nach mehr Wachstum. Wasser enthält aber weit weniger gelösten Sauerstoff als Luft, und Wale atmen ohnehin Luft. Den Größenunterschied zwischen Meer und Land erklärt das nicht."},{"option":3,"text":"Reichlich Nahrung ist tatsächlich eine Voraussetzung für einen so großen Körper. Gegen die Genthese spricht das aber kaum, denn auch hier sollen Gene den Ausschlag geben; offen bleibt, warum ein so schweres Tier an Land nicht bestehen könnte."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Campione & Evans 2012, A universal scaling relationship between body mass and proximal limb bone dimensions in quadrupedal terrestrial tetrapods, BMC Biology 10 (PMC3403949)","oeffentlich":true,"doi":"10.1186/1741-7007-10-60","abruf":"2026-10-12"},{"typ":"doi","kurz":"Biewener 2005, Biomechanical consequences of scaling, Journal of Experimental Biology 208(9)","oeffentlich":true,"doi":"10.1242/jeb.01520","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Galilei 1638, Unterredungen und mathematische Demonstrationen über zwei neue Wissenszweige (dt. von Oettingen 1890, Ostwald's Klassiker 11)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"aa78f105be248302"}},{"id":"qx-c2-033","clusterId":"C","werkstueckRef":"C.4.11","stufe":3,"question":"Wie solltest du diese Aussage einschätzen?","scenario":"Jemand sagt: „Oxidation und Schwerkraft verhindern am Ende immer echte biologische Unsterblichkeit – das ist Physik, da gibt es keine Ausnahme.“ Du weißt: Die Maus lebt nur wenige Jahre. Der Nacktmull, ein Nagetier ähnlicher Größe, wird rund zehnmal so alt wie eine Maus, obwohl seine Zellen deutlich mehr oxidative Schäden aufweisen als die einer Maus.","options":["Als gesicherten Befund, weil die Grenzen der Physik für alle Lebewesen gelten und sich langlebige Tiere nur langsamer abnutzen.","Als widerlegt, weil ein sehr langlebiges Tier zeigt, dass Oxidation und Schwerkraft beim Altern kaum eine Rolle spielen.","Als plausible Vermutung, nicht als Befund, weil ein Gegenbeispiel zur Vorsicht mahnt und die Aussage unbewiesen bleibt.","Als zutreffend für Landtiere, aber falsch für Meerestiere, weil dort Auftrieb und gelöster Sauerstoff die Grenzen weitgehend aufheben."],"correctIndex":2,"explanation":"Die Aussage klingt nach Physik, ist aber eine Vermutung über das Altern, kein gemessenes Ergebnis. Der Nacktmull zeigt, warum Vorsicht angebracht ist: Er lebt trotz deutlich höherer oxidativer Schäden (Andziak u. a. 2006) rund zehnmal so lange wie eine Maus ähnlicher Größe. Das widerlegt die Vermutung nicht, zeigt aber, dass viel Oxidation nicht zwingend ein kurzes Leben bedeutet. Zur Schwerkraft sagt das Beispiel nichts; dieser Teil der Aussage ist ebenso wenig belegt, nur behauptet. Dass Oxidation und Schwerkraft echte biologische Unsterblichkeit am Ende immer verhindern, bleibt deshalb eine Vermutung, kein Befund.","coreRule":"⚡ Plausible Grenzen sind keine bewiesenen Grenzen – ein Gegenbeispiel genügt zur Vorsicht.","beleg":"Werkstück C.4.11 (Schlussfolgerung); Fn. gl-c-nacktmull (Andziak u. a. 2006, Aging Cell 5(6), S. 463–471: hohe oxidative Schäden beim Nacktmull)","status":"entwurf","kurz":"Die Aussage klingt nach Physik, ist aber eine Vermutung über das Altern. Der Nacktmull lebt trotz mehr oxidativer Schäden rund zehnmal so lange wie die Maus: kein Widerlegen, aber ein Grund, sie nicht als Befund zu nehmen.","prueffrage":"Was genau wurde beim Nacktmull gemessen, und sagt das etwas darüber aus, ob Unsterblichkeit möglich ist?","rueckmeldung":[{"option":0,"text":"„Physik“ wirkt wie ein Gütesiegel, und physikalische Grenzen gelten tatsächlich für alle Lebewesen. Was sie für das Altern bedeuten, wurde hier aber nicht gemessen. Der Nacktmull lebt trotz mehr oxidativer Schäden als die Maus viel länger."},{"option":1,"text":"Der Nacktmull ist ein starkes Gegenbeispiel zum Zusammenhang von viel Oxidation und kurzem Leben. Er ist aber nicht unsterblich, nur deutlich langlebiger als erwartet, und widerlegt die Vermutung daher nicht. Vorsicht heißt nicht verwerfen."},{"option":3,"text":"Eine Aufteilung nach Land- und Meerestieren trägt nicht: Auftrieb hebt die Schwerkraft nicht auf, und gelöster Sauerstoff verhindert keine Oxidation. Zudem ist der Nacktmull selbst ein Landtier."}],"familie":"befund-reichweite","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Andziak u. a. 2006, High oxidative damage levels in the longest-living rodent, the naked mole-rat, Aging Cell 5(6) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1111/j.1474-9726.2006.00237.x","url":"https://pubmed.ncbi.nlm.nih.gov/17054663/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"d8ddef072ae335ef"}},{"id":"qx-c2-034","clusterId":"C","werkstueckRef":"C.4.11","stufe":4,"question":"Wie solltest du diesen Befund einordnen?","scenario":"Eine Schweizer Studie mit 1,64 Millionen Erwachsenen im Alter von 40 bis 84 Jahren, die in 259 bis 1960 Metern Höhe wohnen, zeigt: Je 1000 Höhenmeter starben 22 Prozent weniger Menschen an koronarer Herzkrankheit und 12 Prozent weniger an Schlaganfall. Frühere Studien zum Thema kamen zu widersprüchlichen Ergebnissen. Jemand folgert daraus: „Dünne Luft schützt das Herz.“","options":["Als Beobachtung mit unklarer Ursache: Der Zusammenhang ist belegt, ob die dünne Luft der Grund ist, nicht.","Als Beweis, dass dünne Luft das Herz schützt: Bei 1,64 Millionen Menschen ist die Stichprobe so groß, dass keine andere Erklärung mehr infrage kommt.","Als Widerlegung der Annahme, dass Sauerstoff Zellen schädigt: Wo weniger Sauerstoff ist, leben Menschen eben länger.","Als Bestätigung, dass die Schwerkraft in der Höhe schwächer wirkt: Gelenke, Wirbelsäule und Kreislauf verschleißen dort weniger."],"correctIndex":0,"explanation":"Die Studie fand einen deutlichen Zusammenhang zwischen Wohnhöhe und Sterblichkeit durch Herz- und Gefäßerkrankungen. Aus einem Zusammenhang in Beobachtungsdaten folgt aber noch nicht, was ihn verursacht. Menschen in höheren Lagen unterscheiden sich vermutlich auch in anderen Dingen, die den Effekt ganz oder teilweise erklären könnten; die Ursache bleibt offen. Eine große Stichprobe macht die Messung genauer, räumt Störfaktoren aber nicht aus; frühere Studien mit widersprüchlichen Ergebnissen mahnen zusätzlich zur Vorsicht. Dass dünne Luft die Ursache ist, bleibt eine Hypothese, die man gezielt prüfen müsste. Auch die beiden anderen Deutungen springen über die Daten hinaus: Die Studie hat weder Sauerstoffschäden noch die Wirkung der Schwerkraft untersucht, und die Schwerkraft ist in der Höhe nur marginal geringer.","coreRule":"⚡ Auch ein gut gemessener Zusammenhang erklärt noch nicht, was ihn verursacht.","beleg":"Werkstück C.4.11 (Das Rennen der zwei Läufer); Fn. gl-c-hoehe (Faeh u. a. 2009, Circulation 120(6), S. 495–501)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Die Studie zeigt einen deutlichen Zusammenhang zwischen Wohnhöhe und Herztod, aber nicht, was ihn verursacht. Menschen in höheren Lagen unterscheiden sich vermutlich auch in anderem. Dünne Luft als Ursache bleibt eine Hypothese.","prueffrage":"Worin könnten sich Menschen, die auf 1900 Metern wohnen, außer der Höhe noch von denen im Tal unterscheiden?","rueckmeldung":[{"option":1,"text":"Eine so große Stichprobe macht die Messung tatsächlich genauer. Sie sagt aber nichts darüber, ob andere Unterschiede zwischen Berg- und Talbewohnern den Effekt erklären. Mehr Daten verfestigen den Zusammenhang, nicht seine Deutung."},{"option":2,"text":"Weniger Sauerstoff, längeres Leben: Das klingt nach einem Befund über Sauerstoff. Die Studie hat aber weder Sauerstoffschäden noch Zellen untersucht, sondern Herz- und Schlaganfalltode nach Wohnhöhe verglichen. Widerlegen lässt sich damit nichts."},{"option":3,"text":"Auch diese Deutung nimmt eine bestimmte Ursache vorweg, ohne dass die Daten sie stützen. Die Schwerkraft wurde nicht untersucht und ist in der Höhe nur marginal geringer. Zudem ging es um Todesfälle durch Herz und Gefäße, nicht um Gelenke."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Faeh, Gutzwiller & Bopp 2009, Lower mortality from coronary heart disease and stroke at higher altitudes in Switzerland, Circulation 120(6) (PubMed-Abstract)","oeffentlich":true,"doi":"10.1161/CIRCULATIONAHA.108.819250","url":"https://pubmed.ncbi.nlm.nih.gov/19635973/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"beb6a162572a11a5"}},{"id":"qx-c2-035","clusterId":"C","werkstueckRef":"C.5.1","stufe":1,"question":"Was ist an diesem Argument fehlerhaft?","options":["Der Politiker schließt aus einem einzelnen kalten Winter an einem Ort auf den langfristigen Temperaturtrend, obwohl dafür der Durchschnitt vieler Jahre entscheidend ist.","Der Politiker prüft nur die Temperatur, dabei bemisst sich der Klimatrend vor allem an der Menge des Niederschlags und nicht an der Temperatur.","Der Politiker vergleicht den Winter mit dem Sommer, dabei lassen sich nur Messwerte derselben Jahreszeit sinnvoll vergleichen.","Der Politiker nutzt Daten, die sich nicht überprüfen lassen, dabei zählen nur Messreihen, die von mehreren Ländern gemeinsam erhoben wurden."],"correctIndex":0,"explanation":"Das Wetter ist von Natur aus variabel und chaotisch: wie ein Hund, der wild um seinen Besitzer herumläuft, während dieser stetig in eine Richtung geht. Das Klima ist der statistische Durchschnitt des Wetters samt der Häufigkeit von Extremen, typischerweise über rund 30 Jahre. Ein einzelner kalter Tag oder Winter an einem Ort sagt über diesen Trend deshalb ebenso wenig aus wie ein einzelner warmer. Zudem bedeutet Erwärmung nicht, dass es überall und jederzeit wärmer wird: Einzelne harte Kälteeinbrüche bleiben möglich. Wer aus ein paar Tagen auf den Trend schließt, schaut fünf Sekunden auf den Hund und übersieht den Spaziergänger.","coreRule":"⚡ Wetter ist der Hund, Klima ist der Spaziergänger: Ein einzelnes Ereignis widerlegt keinen Langzeittrend.","quote":"Sprechen wir hier gerade über den Hund (das Wetter) oder über den Spaziergänger (das Klima)? Ist diese kurzfristige Beobachtung repräsentativ für den langfristigen Trend?","quoteLabel":"Prüffrage:","beleg":"Werkstück C.5.1 (Kernidee; Kontext & Tiefe; Das Anti-Denkmuster)","status":"entwurf","scenario":"Nach dem kältesten Januar seit Jahrzehnten sagt ein Politiker vor laufender Kamera: „Es ist eiskalt, Schnee bis zum Knie. Die globale Erwärmung ist damit widerlegt!“","kurz":"Wetter schwankt von Tag zu Tag und von Jahr zu Jahr, Klima ist der Durchschnitt über rund 30 Jahre. Ein kalter Winter an einem Ort sagt über den Trend so wenig wie ein warmer; als Widerlegung der Erwärmung taugt er nicht.","prueffrage":"Wäre ein besonders heißer Januar an demselben Ort ein Beweis für die Erwärmung?","rueckmeldung":[{"option":1,"text":"Niederschlag gehört zwar zum Klima, doch für die Erwärmung ist gerade die Temperatur das Maß, gemittelt über viele Jahre. Problematisch ist nicht, dass der Politiker auf die Temperatur schaut, sondern dass ihm ein einzelner Winter genügt."},{"option":2,"text":"Für saubere Vergleiche nimmt man tatsächlich gleiche Jahreszeiten. Der Politiker vergleicht hier aber gar nicht Winter mit Sommer: Er hält einen einzelnen kalten Winter gegen einen langfristigen Trend. Genau dieser Sprung ist das Problem."},{"option":3,"text":"Seine Beobachtung ist durchaus überprüfbar: Kälte und Schnee lassen sich messen. Auch zählen nicht nur Reihen, die mehrere Länder gemeinsam erheben. Zu wenig ist vielmehr ein einzelner Winter an einem Ort als Grundlage."}],"familie":"trend-statt-einzelfall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"NOAA National Centers for Environmental Information: WMO Climate Normals","oeffentlich":true,"url":"https://ncei.noaa.gov/products/wmo-climate-normals","abruf":"2026-10-12"},{"typ":"url","kurz":"IPCC (2021): Summary for Policymakers. In: Climate Change 2021: The Physical Science Basis, A.3.1","oeffentlich":true,"doi":"10.1017/9781009157896.001","url":"https://www.ipcc.ch/report/ar6/wg1/downloads/report/IPCC_AR6_WGI_SPM.pdf","seite":"8","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"da4362ecc7bbe12a"}},{"id":"qx-c2-036","clusterId":"C","werkstueckRef":"C.5.1","stufe":2,"question":"Was ist an dieser Aussage richtig, und was blendet sie aus?","scenario":"Nach einer Hitzewelle sagt ein Bekannter: „Solche Hitzewellen hat es schon immer gegeben. Das ist kein Beweis für irgendeinen Klimawandel.“","options":["Sie stimmt, blendet aber aus, dass es bei Extremwetter nicht darum geht, ob es solche Ereignisse je gab, sondern ob sie häufiger und heftiger werden.","Sie stimmt nicht, denn Hitzewellen sind ein neues Phänomen, das erst mit der Erwärmung des Klimas aufgetreten ist.","Sie stimmt und entkräftet damit den Zusammenhang, denn wenn es Hitzewellen schon früher gab, kann die Erwärmung keinen Einfluss auf sie haben.","Sie stimmt, doch die Erwärmung betrifft alle Extremereignisse und alle Regionen in gleichem Maß und mit gleicher Sicherheit."],"correctIndex":0,"explanation":"Die Aussage ist richtig, aber sie beantwortet eine Frage, die niemand stellt. Die Klimawissenschaft behauptet nicht, Hitzewellen seien neu, sondern dass ihre Häufigkeit und Intensität zunehmen, weil dem System zusätzliche Energie zugeführt wird. Dass etwas früher vorkam, schließt nicht aus, dass es heute häufiger oder heftiger vorkommt. Zur Veranschaulichung: Auch Verkehrsunfälle gab es schon immer; entscheidend ist, ob ihre Zahl steigt. Für Hitzeextreme zeigt der IPCC-Bericht (2021) tatsächlich, dass Hitzewellen seit den 1950er-Jahren in den meisten Landregionen häufiger und heftiger geworden sind, Kälteextreme dagegen seltener und milder. Dabei lohnt Genauigkeit: Bei Hitzeextremen ist die Zunahme praktisch sicher, bei Dürren je nach Region und Dürretyp unterschiedlich gut belegt. Wer „gab es schon immer“ sagt, vergleicht also Existenz mit Häufigkeit und weicht damit der eigentlichen Frage aus.","coreRule":"⚡ „Gab es schon immer“ ist richtig, aber die Häufigkeit zählt.","beleg":"Werkstück C.5.1 (Die thermodynamische Grundlage; Anwendung & Relevanz); Fn. gl-c-ipcc-extreme (IPCC 2021, Summary for Policymakers, A.3.1 und A.3.2, S. 8)","status":"entwurf","kurz":"Dass es Hitzewellen schon immer gab, stimmt, beantwortet aber nicht die eigentliche Frage. Entscheidend ist, ob sie häufiger und heftiger werden: Existenz wird mit Häufigkeit verwechselt, und früheres Vorkommen schließt ein Mehr heute nicht aus.","prueffrage":"Was müsste man zählen oder messen, um zu prüfen, ob sich bei Hitzewellen in den letzten Jahrzehnten etwas verändert hat?","rueckmeldung":[{"option":1,"text":"Wer von Klimawandel spricht, meint meist Zunahme, und das lässt sich leicht zu „neu“ verkürzen. Hitzewellen sind aber nicht neu; belegt ist, dass sie seit den 1950er-Jahren in den meisten Landregionen häufiger und heftiger geworden sind."},{"option":2,"text":"Dass es Hitzewellen früher gab, stimmt tatsächlich. Daraus folgt aber nicht, dass die Erwärmung keinen Einfluss hat: Auch Unfälle gab es immer, und trotzdem kann ihre Zahl steigen oder sinken."},{"option":3,"text":"Die Aussage stimmt, und die Erwärmung beeinflusst Extremereignisse. Gleiches Maß und gleiche Sicherheit überall gibt es aber nicht: Bei Hitze ist die Zunahme praktisch sicher, bei Dürren je nach Region und Typ unterschiedlich gut belegt."}],"familie":"trend-statt-einzelfall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"IPCC (2021): Summary for Policymakers. In: Climate Change 2021: The Physical Science Basis, A.3.1 und A.3.2","oeffentlich":true,"doi":"10.1017/9781009157896.001","url":"https://www.ipcc.ch/report/ar6/wg1/downloads/report/IPCC_AR6_WGI_SPM.pdf","seite":"8","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"969ce45497c835e5"}},{"id":"qx-c2-037","clusterId":"C","werkstueckRef":"C.5.1","stufe":3,"question":"Welche Entscheidung zeigt am deutlichsten, dass hier Wetter mit Klima verwechselt wird?","options":["Der Deichbau wird gestoppt, weil es in den letzten Wochen zufällig trocken war – ein kurzfristiger Eindruck ersetzt hier Langzeitdaten.","Der Deichbau wird verschoben, weil die Pegelmessungen der letzten Jahrzehnte erst noch genauer ausgewertet und geprüft werden sollen.","Der Deichbau wird beschlossen, weil die Messreihen zeigen, dass starke Hochwasser im Mittel häufiger und heftiger geworden sind.","Der Deichbau wird in der Gemeinde diskutiert, weil einzelne Anwohner von ihren Erfahrungen mit früheren Überschwemmungen berichtet haben."],"correctIndex":0,"explanation":"Entscheidungen von langer Reichweite müssen sich auf den langfristigen statistischen Trend stützen, nicht auf den Zustand der letzten Tage oder Wochen. Drei trockene Wochen sind Wetter; Klima ist der statistische Durchschnitt über Jahrzehnte (typischerweise 30 Jahre). Einen Deichbau zu stoppen, weil es heute gerade mal nicht regnet, ist ein Fehlschluss. Dasselbe Muster zeigt sich, wenn ein kalter Wintertag als Argument gegen die Erwärmung der Erde ins Feld geführt wird: Ein kurzfristiger Eindruck wird zur Grundlage einer Entscheidung mit langem Zeithorizont, während die Langzeitdaten übergangen werden. Die anderen Varianten stützen sich dagegen auf Messreihen oder diskutieren sie, statt sie durch einen Momenteindruck zu ersetzen.","coreRule":"⚡ Kippt, wenn ein kurzer Eindruck Entscheidungen über Jahrzehnte begründen soll.","beleg":"Werkstück C.5.1 (Der Kipppunkt; Red Flags)","status":"entwurf","scenario":"In einer Gemeinde wird über den Bau eines Deiches gegen Hochwasser beraten. Ein Gemeinderat sagt: „Die letzten drei Wochen war es trocken. Wir können das Geld für den Deich sparen.“ Eine Nachbargemeinde dagegen stützt ihre Entscheidung auf Pegelmessungen und Niederschlagsstatistiken der letzten Jahrzehnte.","quote":"","quoteLabel":"","kurz":"Der Deichbau soll Jahrzehnte schützen, also muss sich die Entscheidung auf den langfristigen Trend stützen. Drei trockene Wochen sind Wetter, Klima ist der Durchschnitt über viele Jahre. Wer aus dem Momenteindruck den Verzicht ableitet, übergeht die Langzeitdaten.","prueffrage":"Über welchen Zeitraum liegen die Daten oder Eindrücke vor, auf die sich die jeweilige Entscheidung stützt?","rueckmeldung":[{"option":1,"text":"Sorgfältiges Auswerten wirkt zunächst wie Zögern, und Verschieben kann man kritisieren. Mit dem Wetter-Klima-Fehler hat das aber nichts zu tun: Die Langzeitdaten bleiben die Grundlage und werden nicht durch einen Momenteindruck ersetzt."},{"option":2,"text":"Hier liegt gerade kein Fehler vor, sondern das Gegenbeispiel: Der Beschluss stützt sich auf Messreihen über viele Jahre. Genau so sollte eine Entscheidung mit langem Zeithorizont begründet werden, statt mit dem Zustand weniger Wochen."},{"option":3,"text":"Einzelne Erfahrungsberichte ersetzen zwar keine Messreihen. Hier wird aber nur diskutiert, nicht entschieden, und es wird kein kurzfristiges Wetter gegen Langzeitdaten ausgespielt. Die Verwechslung von Wetter und Klima liegt woanders."}],"familie":"trend-statt-einzelfall","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"NOAA National Centers for Environmental Information: WMO Climate Normals","oeffentlich":true,"url":"https://ncei.noaa.gov/products/wmo-climate-normals","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"ad5a5273a584a26b"}},{"id":"qx-c2-038","clusterId":"C","werkstueckRef":"C.5.1","stufe":4,"question":"Ein Bekannter sagt: „Wenn Wärme immer vom Wärmeren zum Kälteren fließt, müsste sich der Temperaturunterschied zwischen Tropen und Polen längst aufgelöst haben, und es gäbe gar kein wechselhaftes Wetter mehr.“ Was ist an diesem Schluss fehlerhaft?","options":["Er übersieht, dass die Sonne den Unterschied jeden Tag neu schafft, sodass der Ausgleich nie fertig wird und gerade dadurch Wind und Wetter entstehen.","Er übersieht, dass Wärme in der Atmosphäre gar nicht vom Wärmeren zum Kälteren fließt, sondern ihre Richtung von Tag zu Tag zufällig wechselt.","Er übersieht, dass der Ausgleich bereits vollständig abgeschlossen ist, sodass das Wetter nur noch von Zufall und nicht mehr von Energie abhängt.","Er übersieht, dass Winde den Temperaturunterschied nicht abbauen, sondern ihn laufend verstärken, sodass Tropen und Pole immer weiter auseinanderdriften."],"correctIndex":0,"explanation":"Der Schluss tut so, als gäbe es nur einen einmaligen Ausgleich. In Wirklichkeit heizt die Sonne die Tropen Tag für Tag stärker als die Pole und schafft den Unterschied immer wieder neu. Wärme fließt vom Wärmeren zum Kälteren, Winde tragen sie polwärts und bauen den Unterschied ab, doch bevor er verschwunden ist, ist er schon wieder da. Dieser nie vollendete Ausgleich hält die Luftbewegung am Laufen und ist der Antrieb des Wettergeschehens (Kleidon 2012). Ein System, das ständig Energie von außen bekommt, kommt nicht zur Ruhe.","coreRule":"⚡ Wo ein Unterschied ständig neu entsteht, läuft der Ausgleich ständig weiter – und dieser Dauerlauf ist der Motor des Wetters.","beleg":"Werkstück C.5.1 (Die thermodynamische Grundlage); Fn. gl-c-kleidon (Kleidon 2012, Physik in unserer Zeit 43(3), S. 138–140)","status":"entwurf","scenario":"Die Sonne strahlt auf die Tropen stärker ein als auf die Pole. Wärme fließt von selbst vom Wärmeren zum Kälteren, und Winde tragen sie polwärts.","kurz":"Der Schluss rechnet mit einem einmaligen Ausgleich, doch die Sonne schafft den Unterschied jeden Tag neu. Der Ausgleich wird nie fertig, und dieses ständige Nachladen hält Wind und Wetter am Laufen.","prueffrage":"Was müsste geschehen, damit Tropen und Pole am Ende tatsächlich gleich warm wären?","rueckmeldung":[{"option":1,"text":"Dass Wetter so unberechenbar wirkt, lässt an eine wechselnde Richtung der Wärme denken. Die Wärme fließt aber verlässlich vom Wärmeren zum Kälteren, und genau das nimmt auch der Bekannte an; sein Fehler liegt woanders."},{"option":2,"text":"Wenn nichts nachkäme, wäre der Ausgleich tatsächlich irgendwann fertig. Doch die Tropen sind bis heute viel wärmer als die Pole, weil die Sonne den Unterschied täglich neu schafft, und gerade diese Energie treibt das Wetter an."},{"option":3,"text":"Der Unterschied verschwindet tatsächlich nicht. Die Ursache ist aber nicht der Wind, denn der trägt Wärme polwärts und baut den Unterschied ab. Er bleibt nur, weil die Sonne ihn jeden Tag neu schafft."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"NOAA: Global Atmospheric Circulations","oeffentlich":true,"url":"https://noaa.gov/node/10334","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Kleidon, A. (2012): Was leistet die Erde? Physik in unserer Zeit 43(3), 136–144 (doi 10.1002/piuz.201201294)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"cf8ff120d1ad5cd8"}},{"id":"qx-c2-039","clusterId":"C","werkstueckRef":"C.5.2","stufe":1,"question":"Wie lässt sich am besten erklären, dass die Freundin ein Ungeheuer gesehen hat, obwohl es nur Otter waren?","scenario":"Eine Freundin schickt dir ein wackeliges, herangezoomtes Handyvideo von einem nebligen See: Ein dunkler, langer Schatten mit seltsamen Höckern bewegt sich durchs Wasser. Sie ist überzeugt: „Das ist ein Seeungeheuer, ich habe es mit eigenen Augen gesehen.“ Später stellt sich heraus, dass drei Otter hintereinander geschwommen sind.","options":["Das Auge hat unvollständige, verzerrte Daten geliefert, und das Gehirn hat die Lücken mit Erwartungen und Vorwissen gefüllt, hier mit einem Ungeheuer.","Das Auge hat das Licht falsch aufgenommen, und das Gehirn hat diese fehlerhaften Daten anschließend ungeprüft weitergegeben.","Das Gehirn hat alles nüchtern aufgezeichnet, und die Täuschung ist allein durch die schlechte Qualität der Handykamera entstanden.","Die Freundin hat die Szene wegen ihrer Erwartungen falsch in Erinnerung, ihre Wahrnehmung im Moment selbst war dabei völlig objektiv."],"correctIndex":0,"explanation":"Das Auge hat nicht gelogen, es hat Licht empfangen. Die Deutung kommt vom Gehirn, das unvollständige, verzerrte Daten mit Erwartungen und Vorwissen ergänzt; an einem nebligen See, um den sich Geschichten über Seeungeheuer ranken, kann daraus ein Monster werden. Dazu kommen Nebel, Wellenbewegung und die geringe Auflösung einer Zoom-Kamera, wodurch drei einzelne Tiere zu einer einzigen seltsamen Gestalt verschmelzen können. Die Behauptung „mit eigenen Augen gesehen“ beweist deshalb wenig: Was wir sehen, ist schon im Moment des Sehens eine Deutung der Daten, nicht erst in der Erinnerung. Eine schlechte Kamera allein erklärt das nicht, denn auch das Gehirn deutet mit.","coreRule":"⚡ Sehen ist Interpretieren, nicht Aufzeichnen: Bei unklaren Daten füllt das Gehirn die Lücken mit der erwarteten Geschichte.","quote":"","quoteLabel":"","beleg":"Werkstück C.5.2 (Das Monster auf dem See; Kernidee)","status":"entwurf","kurz":"Das Auge liefert nur Licht, nicht die Deutung. Bei Nebel, Wellen und Zoom sind die Daten lückenhaft, und das Gehirn ergänzt sie mit Erwartungen und Vorwissen, hier zu einem Ungeheuer. „Mit eigenen Augen gesehen“ ist daher schon eine Deutung.","prueffrage":"Wie gut waren Sicht, Entfernung und Bildqualität, und wie viel davon war tatsächlich zu erkennen?","rueckmeldung":[{"option":1,"text":"Dass die Daten schlecht waren, stimmt. Aber das Auge nimmt kein falsches Licht auf, es empfängt es nur. Die Deutung entsteht erst im Gehirn, und dieses reicht nichts neutral weiter, sondern deutet aktiv mit."},{"option":2,"text":"Die geringe Auflösung kann dazu beitragen, dass Tiere zu einer Gestalt verschmelzen. Das Gehirn zeichnet aber nichts nüchtern auf, sondern deutet mit, und die Freundin hat die Szene ja auch selbst gesehen. Die Kamera allein erklärt es nicht."},{"option":3,"text":"Erwartungen können tatsächlich Erinnerungen verzerren. Sie wirken aber schon im Moment des Sehens: Die Wahrnehmung war nicht objektiv, denn bereits das, was wir sehen, ist eine Deutung der Daten."}],"familie":"erinnerung-ist-rekonstruktion","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Gregory, R. L. (1997): Knowledge in perception and illusion. Philosophical Transactions of the Royal Society B 352(1358), 1121–1127","oeffentlich":true,"doi":"10.1098/rstb.1997.0095","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1692018/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"d62ad9319e127b52"}},{"id":"qx-c2-040","clusterId":"C","werkstueckRef":"C.5.2","stufe":2,"question":"Welche Erklärung dieser „Orbs“ ist die sparsamste und lässt sich mit einem einfachen Test am besten prüfen?","scenario":"Du fotografierst mit Blitz in einer staubigen Dachkammer und siehst auf dem Bild runde, leuchtende Kugeln, die du vorher nicht bemerkt hast. Jemand sagt: „Das sind Geister.“","options":["Das Blitzlicht wird von nahen Staubpartikeln zurückgeworfen; dieselben Kugeln erscheinen an weniger staubigen Orten oder ohne Blitz nicht.","Nahe Objekte bewegen sich bei der Aufnahme scheinbar schneller als ferne und werden dadurch als Kugeln abgebildet; das zeigt sich nur bei bewegter Kamera.","Temperaturunterschiede in der Dachkammer brechen das Licht und spiegeln entfernte Lichtquellen als leuchtende Kugeln; das zeigt sich nur bei Tageslicht.","Die Kompression des Bildes formt aus dem Bildrauschen zufällig kugelförmige Lichtflecken; das zeigt sich nur bei Handyfotos."],"correctIndex":0,"explanation":"Die sparsamste Erklärung nutzt nur bekannte Optik und lässt sich einfach testen: Das Blitzlicht der Kamera wird von nahen, unscharfen Staub- oder Feuchtigkeitspartikeln reflektiert (Backscatter) und erscheint als helle Kugel. Wiederholst du dasselbe Foto in staubfreier Luft oder ohne Blitz, sollten die Kugeln verschwinden. Die übrigen Erklärungen passen nicht zur Situation: Die Bewegungsparallaxe betrifft die Bewegung des Beobachters, nicht ein einzelnes Foto. Eine Brechung durch Temperaturunterschiede erklärt Verzerrungen, aber keine Kugeln vor der Linse. Kompression kann Objekte verfremden, ist aber nicht die Ursache der Orbs. „Geister“ dagegen setzt etwas Neues voraus, für das es hier keinen Beleg gibt. Ein einzelnes Foto beweist deshalb keine Geistererscheinung.","coreRule":"⚡ Wenn eine bekannte Ursache ein Bild vollständig erklärt und sich testen lässt, brauchst du keine übernatürliche Erklärung.","beleg":"Werkstück C.5.2 (Anwendung & Relevanz, Bei Geister-Fotografie)","status":"entwurf","kurz":"Der Blitz wirft Licht von nahen Staubteilchen zurück, und das lässt sich testen: Ohne Blitz oder in staubfreier Luft sollten die Kugeln fehlen. „Geister“ wäre eine neue Annahme ohne Beleg.","prueffrage":"Was ändert sich auf einem zweiten Foto derselben Stelle, wenn du nur eine Bedingung der Aufnahme veränderst?","rueckmeldung":[{"option":1,"text":"Dass Dinge dicht vor der Linse eine Rolle spielen, trifft zu. Dass nahe Objekte schneller zu wandern scheinen, gilt aber nur, wenn sich der Betrachter bewegt, und macht aus einem einzelnen Blitzfoto keine Kugeln."},{"option":2,"text":"Temperaturunterschiede können Licht brechen, doch das erklärt eher Verzerrungen als Kugeln vor der Linse. Außerdem hast du mit Blitz fotografiert, nicht bei Tageslicht."},{"option":3,"text":"Kompression kann Bilder verfremden, ist aber nicht die Ursache der Orbs. Auch der Test passt nicht: Ob es ein Handyfoto ist, sagt nichts darüber, woher die Kugeln kommen."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Society for Psychical Research, Psi Encyclopedia: Parsons, S.: Orbs (Light Anomalies)","oeffentlich":true,"url":"https://psi-encyclopedia.spr.ac.uk/articles/orbs-light-anomalies/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Schwartz, G. E.; Creath, K. (2005): Anomalous orbic „spirit“ photographs? A conventional optical explanation. Journal of Scientific Exploration 19(3), 343–358","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"999d622ad7bb68ba"}},{"id":"qx-c2-041","clusterId":"C","werkstueckRef":"C.5.2","stufe":3,"question":"Was ist an diesem Schluss fehlerhaft?","scenario":"Jemand zeigt dir ein unscharfes Nachtvideo eines leuchtenden Punkts, der sich am Himmel zu bewegen scheint, und sagt: „Ich kann mir nicht erklären, was das ist – also muss es außerirdisch sein.“","options":["Der Schluss dreht sich im Kreis: Das Video gilt als Beweis für Außerirdische, und die Außerirdischen gelten wiederum als Beweis dafür, dass das Video echt ist.","Der Schluss deutet in einen Punkt zu viel hinein: Er wird als Gesicht oder Gestalt gelesen, obwohl das Bild gar nichts Erkennbares zeigen kann.","Der Schluss überschätzt die Häufigkeit solcher Ereignisse: Wer gerade eine Dokumentation über Ufos gesehen hat, hält echte Sichtungen für alltäglicher, als sie sind.","Der Schluss macht aus einer Erklärungslücke einen Beleg: Aus „ich kann es nicht erklären“ wird „außerirdisch“, obwohl naheliegendere Erklärungen gar nicht geprüft wurden."],"correctIndex":3,"explanation":"Dass jemand etwas nicht erklären kann, sagt etwas über sein Wissen aus, nicht über das Objekt. Bei unscharfen Nachtaufnahmen gibt es viele alltägliche Erklärungen: Flugzeuge, Satelliten wie Starlink, Ballons oder Drohnen werden ohne Referenzobjekte leicht falsch eingeschätzt, Linsenreflexionen (Lens Flares) wirken wie eigenständige Lichter, und Luftturbulenzen lassen Lichtpunkte flackern oder wandern. Solange diese Möglichkeiten nicht ausgeschlossen sind, trägt der Sprung zur aufregendsten Erklärung nicht. Eine passende Prüffrage lautet: Welche bekannten Gesetze der Optik, der Perspektive oder der Kameratechnik könnten das Gesehene ebenfalls vollständig erklären?","coreRule":"⚡ Eine Erklärungslücke ist kein Beleg für die aufregendste Erklärung.","beleg":"Werkstück C.5.2 (Anwendung & Relevanz, Bei der Ufologie; Red Flags)","status":"entwurf","kurz":"Dass jemand etwas nicht erklären kann, sagt etwas über sein Wissen, nicht über das Objekt. Bei unscharfen Nachtaufnahmen kommen viele alltägliche Erklärungen infrage; solange sie nicht ausgeschlossen sind, trägt der Sprung zur spektakulärsten nicht.","prueffrage":"Was müsste man über Ort, Uhrzeit und Blickrichtung der Aufnahme wissen, um den Lichtpunkt bestimmen zu können?","rueckmeldung":[{"option":0,"text":"Ein Zirkelschluss setzt voraus, was er beweisen will, etwa wenn Video und Außerirdische sich gegenseitig stützen. Hier wird aber nur von „unerklärlich“ auf „außerirdisch“ gesprungen, also von einer Lücke zu einer Erklärung, nicht im Kreis."},{"option":1,"text":"Bei so wenig Bildinformation wird tatsächlich schnell etwas hineingedeutet. Hier ist aber von einem leuchtenden Punkt die Rede, nicht von einer erkannten Gestalt. Der Fehler liegt im Schluss von „unerklärt“ auf „außerirdisch“."},{"option":2,"text":"Medien können beeinflussen, wie häufig uns etwas erscheint. Davon ist hier aber keine Rede: Der Schluss stützt sich nicht auf eine Häufigkeitseinschätzung, sondern auf die eigene Ratlosigkeit."}],"familie":"unwissen-ist-kein-beleg","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Office of the Director of National Intelligence (2021): Preliminary Assessment: Unidentified Aerial Phenomena","oeffentlich":true,"url":"https://archive.dni.gov/files/ODNI/documents/assessments/Prelimary-Assessment-UAP-20210625.pdf","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"455238f8111a1b04"}},{"id":"qx-c2-042","clusterId":"C","werkstueckRef":"C.5.2","stufe":4,"question":"Welcher Einwand trifft den Schluss von Herrn K. am besten?","options":["Er unterstellt, dass sich Licht in der Luft geradlinig ausbreitet. Temperaturschichten, Wasserdampf und Turbulenzen brechen es aber, sodass Objekte am Horizont höher erscheinen können, als sie tatsächlich sind.","Er unterstellt, dass sich ferne Objekte schneller bewegen als nahe. Deshalb wirken sie am Horizont größer und deutlicher, als seine Rechnung vorhersagt.","Er unterstellt, dass seine Augen das Bild verlässlich aufzeichnen. Tatsächlich rechnet das Gehirn ferne Objekte bei Dämmerung stets aus dem Bild heraus und ersetzt sie durch Spiegelungen.","Er unterstellt, dass Objekte bei großer Entfernung kleiner wirken. Tatsächlich erscheinen sie ab einer bestimmten Distanz größer und lassen sich dadurch leichter erkennen."],"correctIndex":0,"explanation":"Sein Schluss hängt an einer stillschweigenden Annahme: dass Licht in der Luft schnurgerade verläuft. Tatsächlich brechen Temperaturschichten, Wasserdampf und Turbulenzen das Licht; schon bei gewöhnlicher Schichtung lässt diese Brechung (Refraktion) Objekte am Horizont etwas höher erscheinen und gleicht die Krümmung teilweise aus, und liegt warme Luft über kaltem Wasser, kann sie sogar Teile sichtbar machen, die nach geradliniger Rechnung ganz verdeckt wären. Das Flimmern und die Verschiebung in seiner Beobachtung passen zu solchen Verzerrungen, ähnlich wie bei einer Fata Morgana. Wer aus „Ich sehe mehr, als meine Rechnung erlaubt“ schließt, die Erde sei nicht gekrümmt, prüft also die eigene Rechnung nicht, die die Brechung außer Acht lässt. Die anderen Einwände passen nicht zu bekannten Phänomenen: Bei der Bewegungsparallaxe wirken nahe Objekte schneller als ferne, ferne Objekte wirken kleiner, nicht größer, und das Gehirn ersetzt ferne Objekte nicht durch Spiegelungen, sondern füllt unklare Daten höchstens mit Erwartungen auf.","coreRule":"⚡ Wer weit sieht, muss die Brechung der Luft mitrechnen: Eine Beobachtung widerlegt eine Theorie erst, wenn alle bekannten Störeinflüsse in der Rechnung berücksichtigt sind.","beleg":"Werkstück C.5.2 (Kontext & Tiefe, Atmosphärische Verzerrung; Anwendung & Relevanz, Bei der Flache-Erde-Theorie)","status":"entwurf","scenario":"Herr K. steht an einem klaren Tag an einer Küste und sieht ein Hochhaus, das 40 Kilometer entfernt am Horizont liegt. Er hat grob nachgerechnet: Bei einer gekrümmten Erde müsste der untere Teil des Gebäudes hinter dem Horizont verborgen sein. Er sieht aber mehr davon, als seine Rechnung erlaubt, wenn auch etwas flimmernd und leicht verschoben. Er schließt: „Die Erde ist nicht gekrümmt, sonst könnte ich das sehen.“","quote":"","quoteLabel":"","kurz":"Herr K. rechnet, als verliefe Licht in der Luft schnurgerade. Luft bricht es aber, und über lange Strecken nahe der Oberfläche kann das Objekte am Horizont höher erscheinen lassen. Seine Rechnung blendet diese Brechung aus.","prueffrage":"Wie hoch steht Herr K. über dem Wasser, und wie viele Meter des Gebäudes müssten nach seiner Rechnung verdeckt sein?","rueckmeldung":[{"option":1,"text":"Dass Sehen und Rechnung hier nicht zusammenpassen, ist richtig beobachtet. Bewegung spielt dabei aber keine Rolle: Das Hochhaus steht still, und bei der Bewegungsparallaxe wirken ohnehin die nahen Dinge schneller, nicht die fernen."},{"option":2,"text":"Wahrnehmung ist tatsächlich keine reine Aufzeichnung, doch das Gehirn ersetzt ferne Objekte nicht durch Spiegelungen; es füllt unklare Daten höchstens mit Erwartungen auf. Der Fehler liegt in der Rechnung, die die Brechung des Lichts übergeht."},{"option":3,"text":"Auffällig ist, dass Herr K. mehr vom Gebäude sieht, als seine Rechnung erlaubt. Mit der Entfernung erscheinen Objekte aber kleiner, nicht größer. Die Brechung des Lichts bewirkt etwas anderes: Das Gebäude erscheint höher, als es tatsächlich steht."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Georgia State University, HyperPhysics: Atmospheric Refraction","oeffentlich":true,"url":"https://hyperphysics.gsu.edu/hbase/atmos/mirage.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Young, A. T. (San Diego State University): Looming, Towering, Stooping, and Sinking","oeffentlich":true,"url":"https://aty.sdsu.edu/mirages/mirsims/loom/loom.html","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"ed17c1872a951c0f"}},{"id":"qx-c2-043","clusterId":"C","werkstueckRef":"C.5.3","stufe":1,"question":"Ein Bekannter zeigt dir ein Foto eines langen Streifens hinter einem Flugzeug und sagt: „Das sind Chemikalien, die da versprüht werden. Aus Kerosin entsteht ja nichts, was einen weißen Streifen bilden könnte.“ Welche Überlegung prüft diese Behauptung am besten?","options":["Man fragt, was bei der Verbrennung von Kerosin entsteht: Kohlendioxid und heißer Wasserdampf, der in der eiskalten Höhenluft zu Eiskristallen gefriert, wie unser Atem an einem Wintertag.","Man fragt, ob der Streifen Aluminium- oder Bariumverbindungen enthält, denn nur solche Stoffe können in der Höhenluft die Tröpfchen eines Streifens erzeugen.","Man fragt, ob sich der Streifen bei trockener Luft genauso schnell auflöst wie bei feuchter Luft, denn die Eiskristalle wachsen aus Rußpartikeln unabhängig vom Wasser.","Man fragt, ob das Kohlendioxid aus dem Triebwerk in der Kälte gefriert, denn aus Kohlendioxid bestehen die Eiskristalle des Streifens."],"correctIndex":0,"explanation":"Wie in unserem Atem entstehen bei der Verbrennung vor allem Kohlendioxid und Wasser. In etwa zehn Kilometern Höhe ist es oft kälter als −40 °C: Der heiße Wasserdampf kondensiert zu winzigen Tröpfchen, die rasch zu Eiskristallen gefrieren. Die Behauptung „aus Kerosin entsteht nichts Sichtbares“ ist damit widerlegt, ganz ohne Zusatzstoffe. Rußpartikel aus dem Triebwerk können als Kondensationskerne dienen, nötig sind sie aber nicht, denn die Luft enthält ohnehin genug Partikel. Eine gute Prüffrage fragt nach der einfachsten Erklärung, die schon bekannte Zutaten und Bedingungen nutzt, bevor man ein geheimes Programm annimmt.","coreRule":"⚡ Bevor du einen Zusatzstoff annimmst: Prüfe, ob die bekannten Zutaten und Bedingungen das Phänomen schon erklären.","beleg":"Werkstück C.5.3 (Kontext & Tiefe: Die Zutaten, Die Bedingungen)","status":"entwurf","scenario":"Ein Flugzeug fliegt in etwa zehn Kilometern Höhe, wo es oft kälter als −40 °C ist. Hinter ihm bleibt ein weißer Streifen zurück.","kurz":"Schon die Verbrennung von Kerosin liefert in der Kälte alles Nötige: Der heiße Wasserdampf gefriert zu Eiskristallen. Der Fehler liegt darin, ein geheimes Programm anzunehmen, bevor man die einfachste Erklärung mit bekannten Zutaten geprüft hat.","prueffrage":"Welche Stoffe und welche Bedingungen sind in dieser Höhe ohnehin vorhanden, und reichen sie für den Streifen schon aus?","rueckmeldung":[{"option":1,"text":"Nach dem Inhalt des Streifens zu fragen, klingt gründlich. Die Voraussetzung stimmt aber nicht: Zusätzliche Metallverbindungen braucht es nicht, denn der Wasserdampf aus der Verbrennung reicht in der Kälte allein aus."},{"option":2,"text":"Ruß kann tatsächlich als Kondensationskern dienen. Die Eiskristalle bestehen aber aus gefrorenem Wasser, nicht aus Ruß, und wie lange ein Streifen bleibt, hängt stark von der Feuchte der Umgebungsluft ab: In trockener Luft löst er sich rasch auf."},{"option":3,"text":"Kohlendioxid entsteht bei der Verbrennung wirklich, aber es friert bei diesen Temperaturen nicht aus. Die Eiskristalle bestehen aus gefrorenem Wasserdampf. Mit Kohlendioxid lässt sich der weiße Streifen daher nicht erklären."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"U.S. EPA: Information on Contrails from Aircraft","oeffentlich":true,"url":"https://www.epa.gov/regulations-emissions-vehicles-and-engines/Contrails","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Schumann, U. (1996): On conditions for contrail formation from aircraft exhausts. Meteorologische Zeitschrift 5(1), 4–23 (doi 10.1127/metz/5/1996/4)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"955a6c73618bfc1c"}},{"id":"qx-c2-044","clusterId":"C","werkstueckRef":"C.5.3","stufe":2,"question":"Was ist an diesem Schluss fehlerhaft?","scenario":"Jemand zeigt dir eine Regenwasserprobe, in der Aluminium und Barium nachgewiesen wurden: „Das ist der Beweis für Sprühaktionen.“","options":["Der Schluss ist fehlerhaft, weil Proben nur Momentaufnahmen sind; ob es Sprühaktionen gibt, lässt sich deshalb weder belegen noch ausschließen.","Der Schluss ist fehlerhaft, weil die Probe verunreinigt gewesen sein muss; in natürlichem Regenwasser kommen Aluminium und Barium nie vor.","Der Schluss ist fehlerhaft, weil ein Nachweis allein nichts zeigt; beide Elemente kommen überall in der Erdkruste vor und sind auch ohne Sprühaktionen zu erwarten.","Der Schluss ist fehlerhaft, weil eine einzelne Probe nicht reicht; erst wenn viele Proben Aluminium und Barium enthalten, wären Sprühaktionen belegt."],"correctIndex":2,"explanation":"Ein Messwert sagt erst etwas, wenn man ihn mit dem Wert vergleicht, der ohnehin zu erwarten ist. Aluminium und Barium kommen überall in der Erdkruste vor und gelangen etwa mit Staub ins Regenwasser; ihr Nachweis passt deshalb auch ohne Sprühaktionen und spricht nicht für sie. Entscheidend wäre, ob die Mengen deutlich über dem üblichen Gehalt liegen, und daran ändern auch weitere Proben mit bloßem Nachweis nichts. Die Behauptung „nie vorhanden“ wäre ebenso falsch wie die Haltung „weder belegbar noch widerlegbar“. Das stützt auch ein Befund aus der Fachwelt: Shearer u. a. (2016) befragten 77 Fachleute für Kondensstreifen und Staubablagerung; 76 hatten nie einen Beleg für ein geheimes Sprühprogramm gesehen und erklärten die ihnen vorgelegten Messwerte mit gewöhnlichen Ursachen.","coreRule":"⚡ Ein Messwert ohne den Vergleich mit dem natürlichen Gehalt beweist nichts.","beleg":"Werkstück C.5.3 (Red Flags); Fn. gl-c-shearer (Shearer u. a. 2016, Environ. Res. Lett. 11(8), Art. 084011)","status":"entwurf","kurz":"Ein Nachweis zählt erst im Vergleich mit dem Wert, der ohnehin zu erwarten ist. Aluminium und Barium sind in der Erdkruste überall zu finden, ihr Nachweis passt also auch ohne Sprühaktionen und spricht nicht für sie.","prueffrage":"Wie viel Aluminium und Barium enthielt die Probe genau, und mit welchem Wert wurde das verglichen?","rueckmeldung":[{"option":0,"text":"Dass eine einzelne Probe nur eine Momentaufnahme ist, stimmt. Unentscheidbar wird die Frage dadurch nicht: Messwerte lassen sich mit dem üblichen Gehalt vergleichen, und der Nachweis überall vorkommender Elemente spricht nicht für Sprühaktionen."},{"option":1,"text":"Eine Probe kann verunreinigt sein, doch hier wird etwas Falsches vorausgesetzt: Aluminium und Barium kommen natürlich vor, etwa im Staub aus der Erdkruste. „Nie“ stimmt also nicht, und eine Verunreinigung braucht es zur Erklärung nicht."},{"option":3,"text":"Mehr Proben wirken gründlicher. Doch Aluminium und Barium kommen überall in der Erdkruste vor und sind auch in weiteren Proben zu erwarten; viele bloße Nachweise belegen so wenig wie einer. Zählen würde erst ein deutlich erhöhter Gehalt."}],"familie":"dosis-entscheidet","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Shearer, C.; West, M.; Caldeira, K.; Davis, S. J. (2016): Quantifying expert consensus against the existence of a secret, large-scale atmospheric spraying program. Environmental Research Letters 11(8), 084011","oeffentlich":true,"doi":"10.1088/1748-9326/11/8/084011","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"a87943da00b5a3b9"}},{"id":"qx-c2-045","clusterId":"C","werkstueckRef":"C.5.3","stufe":3,"question":"Sie sagt: „Kondensstreifen sind harmlos: Wer sich um Flugverkehr und Klima sorgt, soll auf das CO₂ achten. Die Wolken aus Wasser und Eis am Himmel sind nur Wetter und wirken sich nicht aufs Klima aus.“ Welche Antwort ist am besten begründet?","options":["„Ungiftig“ heißt nicht „folgenlos“: Die Schleierwolken aus Kondensstreifen zählen zu den größten Erwärmungsbeiträgen des Luftverkehrs.","„Ungiftig“ heißt auch „folgenlos“: Wolken aus reinem Wasser und Eis können die Temperatur nicht verändern, weil sie keine Energie aufnehmen oder abgeben.","„Ungiftig“ heißt nicht „folgenlos“, aber die Wirkung ist kühlend: Die Schleierwolken aus Kondensstreifen werfen Sonnenlicht zurück, die Erwärmung geht allein vom CO₂ aus.","„Ungiftig“ heißt nicht „folgenlos“, aber der Grund ist ein anderer: Die Schleierwolken aus Kondensstreifen belasten das Klima durch ihre Giftstoffe, auch wenn Messungen das bisher nicht zeigen."],"correctIndex":0,"explanation":"Die Freundin schließt von „ungiftig“ auf „folgenlos“ – das ist ein Fehlschluss, denn Harmlosigkeit für die Gesundheit sagt nichts über die Wirkung auf die Strahlungsbilanz. Langlebige Kondensstreifen gehen in Schleierbewölkung über und beeinflussen, wie viel Wärme die Atmosphäre hält. Nach einer großen Bilanz (Lee u. a. 2021) ist diese Schleierbewölkung nach bestem Schätzwert der größte einzelne Erwärmungsbeitrag des Luftverkehrs, noch vor dessen CO₂: Für 2018 entfielen davon rund 57 mW/m² auf Kondensstreifen-Zirren und 34 auf CO₂. Der Wert für die Zirren ist allerdings deutlich unsicherer als der für CO₂.","coreRule":"⚡ „Kein Gift“ heißt nicht „keine Wirkung“: Prüfe, welche Eigenschaft einer Sache für die Frage zählt.","beleg":"Werkstück C.5.3 (Der Kipppunkt); Fn. gl-c-lee (Lee u. a. 2021, Atmos. Environ. 244, Art. 117834)","status":"entwurf","scenario":"Du diskutierst mit einer Freundin über Flugzeuge. Sie hat gerade gelernt, dass Kondensstreifen aus Wasserdampf und Eiskristallen bestehen und kein Gift enthalten.","kurz":"Dass Wolken aus Wasser und Eis ungiftig sind, sagt nichts über ihre Klimawirkung. Langlebige Kondensstreifen werden zu Schleierwolken, die Wärme zurückhalten, und gelten nach einer großen Bilanz sogar als größter Erwärmungsbeitrag des Luftverkehrs.","prueffrage":"Worauf bezieht sich „harmlos“ in ihrem Satz: auf die Gesundheit oder auf die Wärmebilanz der Atmosphäre?","rueckmeldung":[{"option":1,"text":"Dass Wasser und Eis ungiftig sind, stimmt, und so wirkt der Schluss plausibel. Wolken beeinflussen aber die Strahlung: Sie reflektieren Sonnenlicht und halten Wärmestrahlung zurück. Wie giftig etwas ist, sagt nichts über die Klimawirkung."},{"option":2,"text":"Daran stimmt: Wolken werfen auch Sonnenlicht zurück, und das kühlt. Bei langlebigen Kondensstreifen überwiegt im Mittel aber die zurückgehaltene Wärme; nach bestem Schätzwert einer großen Bilanz wärmen sie sogar stärker als das CO₂ des Luftverkehrs."},{"option":3,"text":"Richtig ist: Ungiftig heißt nicht folgenlos. Die Begründung trägt aber nicht, denn Kondensstreifen bestehen aus Wasser und Eis, und ihre Klimawirkung kommt aus der Wärmerückhaltung der Eiskristalle. Giftstoffe spielen dabei keine Rolle."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Lee, D. S. u. a. (2021): The contribution of global aviation to anthropogenic climate forcing for 2000 to 2018. Atmospheric Environment 244, 117834","oeffentlich":true,"doi":"10.1016/j.atmosenv.2020.117834","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC7468346/","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"ad41281d66c71d28"}},{"id":"qx-c2-046","clusterId":"C","werkstueckRef":"C.5.3","stufe":4,"question":"Was ist an diesem Einwand verkürzt und trägt den Schluss deshalb nicht?","scenario":"In einer Diskussion über Streifen am Himmel sagt jemand: „Wolken werden doch seit Jahren mit Chemikalien besprüht, das nennt man Cloud Seeding! Also stimmt die Sprühtheorie.“","options":["Dass Wolken gezielt besprüht werden, ist grundsätzlich unmöglich, also muss die Behauptung gar nicht erst geprüft werden.","Dass es Wolkenimpfung gibt, stimmt, doch sie wirkt nur örtlich und begrenzt, und daraus folgt kein Sprühprogramm hinter Kondensstreifen.","Dass es Wolkenimpfung gibt, stimmt, und weil sie weit verbreitet ist, ist die Sprühtheorie im Kern bestätigt.","Dass Wolkenimpfung schwer nachweisbar ist, macht die Theorie unwiderlegbar, also ist sie damit glaubwürdig."],"correctIndex":1,"explanation":"Cloud Seeding gibt es wirklich: Dabei werden Stoffe wie Silberiodid gezielt in Wolken eingebracht, um Regen oder Schnee anzuregen. Manche Länder setzen es regelmäßig ein, doch es wirkt nur örtlich, und sein Effekt ist begrenzt und oft schwer nachzuweisen. Der Einwand verwechselt damit zwei verschiedene Dinge: Dass ein bekanntes, örtlich begrenztes Verfahren existiert, sagt nichts darüber, was die langen Streifen hinter Flugzeugen sind. Dafür reicht die Physik: Heißer, feuchter Abgasdampf aus dem Triebwerk gefriert in der eiskalten Höhenluft zu Eiskristallen, und ob der Streifen kurz oder lange bleibt, hängt von der Feuchte der Umgebungsluft ab. Aus der Existenz eines realen, lokalen Verfahrens folgt kein globales Geheimprogramm.","coreRule":"⚡ Ein reales, lokales Verfahren belegt kein globales Geheimprogramm.","beleg":"Werkstück C.5.3 (Verbindungen; Kontext & Tiefe)","status":"entwurf","kurz":"Cloud Seeding gibt es wirklich, es wirkt aber nur örtlich und begrenzt. Dass ein solches Verfahren existiert, erklärt nicht die langen Streifen hinter Flugzeugen. Das ist die Verwechslung zweier verschiedener Dinge.","prueffrage":"Hinter welchen Flugzeugen entstehen die Streifen, und bei welchem Wetter bleiben sie lange am Himmel stehen?","rueckmeldung":[{"option":0,"text":"Sprühen für unmöglich zu erklären, wäre ein schneller Weg, die Behauptung abzutun. Gezielte Eingriffe in Wolken gibt es aber tatsächlich. Der Einwand scheitert daran, dass dieses Verfahren die Streifen hinter Flugzeugen nicht erklärt."},{"option":2,"text":"Dass es Wolkenimpfung gibt, stimmt. Sie wird aber gezielt und örtlich begrenzt eingesetzt, und selbst wo sie verbreitet ist, belegt das kein Sprühprogramm hinter Kondensstreifen. Für die langen Streifen reicht schon die Physik der Abgase."},{"option":3,"text":"Was sich nicht widerlegen lässt, wirkt zunächst unangreifbar. Doch eine Behauptung gewinnt keine Stütze, nur weil sie schwer zu prüfen ist. Die Streifen erklären sich ohnehin ohne Sprühprogramm durch kondensierenden Abgasdampf."}],"familie":"verschwoerung-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"World Meteorological Organization: WMO Statement on Weather Modification","oeffentlich":true,"url":"https://wmo.int/content/wmo-statement-weather-modification","abruf":"2026-10-12"},{"typ":"url","kurz":"U.S. EPA: Information on Contrails from Aircraft","oeffentlich":true,"url":"https://www.epa.gov/regulations-emissions-vehicles-and-engines/Contrails","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"4f78993692068e95"}},{"id":"qx-c2-047","clusterId":"C","werkstueckRef":"C.5.4","stufe":1,"question":"Der Bekannte sagt: „Dafür muss jedes Stockwerk einzeln gesprengt worden sein.“ Welche Überlegung zeigt am besten, was an diesem Schluss nicht trägt?","options":["Ein schneller, gleichmäßiger Einsturz zeigt, dass jemand ihn von außen gezielt herbeigeführt haben muss.","Ein aufprallender Block trägt weit mehr Energie als das Element darunter aushält, so löst ein Ausfall die Kette aus.","Ein Einsturz setzt voraus, dass vorher fast jedes einzelne Element im Gebäude geschwächt worden ist.","Ein Einsturz kündigt sich lange vorher an, weil die unteren Elemente unter dem Gewicht nur langsam nachgeben."],"correctIndex":1,"explanation":"Der Schluss „schnell und vollständig, also gesprengt“ übersieht eine einfachere Erklärung. Fällt ein oberer Gebäudeteil auf die Struktur darunter, wird seine Lageenergie zu Bewegungsenergie, und beim Aufprall können Kräfte wirken, die ein Vielfaches der ruhenden Last betragen, für die das nächste Element ausgelegt ist. Übersteigt diese Belastung seine Tragreserve, versagt es, und der Block stürzt samt Trümmern mit noch mehr Masse weiter auf das nächste Element. So kann das Versagen an einer Stelle genügen, damit die Struktur von oben nach unten nacheinander nachgibt, schnell und ohne weitere Eingriffe. Eine Sprengung ist dafür nicht nötig: Die vorhandene Physik erklärt das Ergebnis bereits (Ockhams Rasiermesser).","coreRule":"⚡ Ein geschwächtes Element kann eine Kettenreaktion auslösen, die niemand mehr bremst: Tempo und Vollständigkeit eines Einsturzes sind noch kein Beleg für eine Sprengung.","beleg":"Werkstück C.5.4 (Der Stapel Bücher; Kernidee)","status":"entwurf","scenario":"Ein Bekannter sieht die Bilder vom Einsturz eines Hochhauses nach einem Brand. Der Einsturz dauerte nur wenige Sekunden und erfasste das ganze Gebäude, obwohl nur einige Stockwerke gebrannt hatten.","kurz":"Stürzt ein oberer Teil auf die Struktur darunter, kann er weit mehr Energie mitbringen, als das nächste Element aufnehmen kann. Versagt es, wächst die fallende Masse mit jeder Etage; so erklärt die Physik den schnellen, vollständigen Einsturz ohne Sprengung.","prueffrage":"Wo begann der Einsturz auf den Bildern: in Höhe der brennenden Stockwerke oder an vielen Stellen zugleich?","rueckmeldung":[{"option":0,"text":"Ein Einsturz in wenigen Sekunden wirkt wie geplant, und genau daraus entsteht der Schluss auf Absicht. Eine Kette von oben nach unten erklärt Tempo und Gleichmäßigkeit aber allein, ein Eingriff von außen wird dafür gar nicht gebraucht."},{"option":2,"text":"Wenn ein ganzes Gebäude einstürzt, scheint es, als müssten vorher fast alle Elemente geschwächt gewesen sein. Es kann aber das Versagen an einer Stelle reichen, den Rest liefert die frei werdende Energie; zudem brannten nur einige Stockwerke."},{"option":3,"text":"Belastung verbindet man leicht mit langsamem Nachgeben. Bei einem Aufprall können aber Kräfte wirken, die ein Vielfaches der ruhenden Last betragen, und dann versagt das nächste Element schlagartig; eine lange Vorwarnung braucht es nicht."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"NIST: FAQs – NIST WTC Towers Investigation","oeffentlich":true,"url":"https://www.nist.gov/world-trade-center-investigation/study-faqs/wtc-towers-investigation","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"75569bb8234f93b1"}},{"id":"qx-c2-048","clusterId":"C","werkstueckRef":"C.5.4","stufe":2,"question":"Jemand sagt: „Das Hochhaus wurde von keinem Flugzeug getroffen und ist trotzdem komplett eingestürzt. Das kann nur eine Sprengung gewesen sein.“ Welche Überlegung prüft diese Behauptung am besten?","options":["Stundenlange Brände können Stahlträger so ausdehnen und schwächen, dass eine kritische Stütze ihren Halt verliert und eine Einsturzkaskade auslöst. Ein Flugzeugeinschlag ist dafür nicht nötig.","Ein Totaleinsturz ohne direkten Flugzeugtreffer ist bei Hochhäusern so ungewöhnlich, dass allein dieser Umstand eine Sprengung als Ursache nahelegt.","Ein Gebäude, das nicht von einem Flugzeug getroffen wurde, bleibt durch seine intakte Struktur so tragfähig, dass Brände allein es nicht zum Einsturz bringen können.","Ein Einsturz in so kurzer Zeit braucht eine gleichzeitig wirkende Ursache an vielen Stellen. Ein einzelner ausgefallener Träger kann ihn nicht erklären."],"correctIndex":0,"explanation":"Die Behauptung tut so, als gäbe es nur Flugzeugeinschlag oder Sprengung. Stahl muss nicht schmelzen, um zu versagen: Bei 600 bis 800 °C verliert er über die Hälfte seiner Tragfähigkeit, und schon bei geringeren Temperaturen dehnt er sich deutlich aus. Nach der Untersuchung des NIST schoben sich ausdehnende Deckenträger einen Unterzug von seinem Auflager an einer tragenden Stütze; Decken brachen ein, die Stütze verlor ihre seitliche Halterung, knickte aus, und das Versagen pflanzte sich durch die Struktur fort. Weil die Sprinkler trocken blieben, wirkten die Brände stundenlang ungehindert; die Trümmerschäden spielten nach NIST für den Einsturz selbst kaum eine Rolle. Diese schon vorhandene Ursache erklärt den Einsturz ohne zusätzliche Sprengung. Nach NIST war es der erste bekannte Totaleinsturz eines Hochhauses vor allem durch Feuer, doch ungewöhnlich ist nicht dasselbe wie unerklärbar.","coreRule":"⚡ Hitze dehnt Stahl, und eine verrutschte Stütze genügt für die Kaskade.","beleg":"Werkstück C.5.4 (Kontext & Tiefe, Punkt 5 WTC 7); Fn. gl-c-nist (NIST NCSTAR 1A, 2008); Fn. gl-c-wtc7-freifall (NIST 2008, S. 45 und 48)","status":"entwurf","scenario":"Das Gebäude stand in der Nähe zweier Türme, die kurz zuvor eingestürzt waren. Es wurde von herabfallenden Trümmern getroffen, danach brannte es viele Stunden lang auf mehreren Etagen unkontrolliert. Die Sprinkler der unteren Stockwerke blieben trocken, weil die einstürzenden Türme die städtische Wasserleitung beschädigt hatten.","kurz":"Die Behauptung tut so, als gäbe es nur Flugzeug oder Sprengung. Stundenlang ungelöschte Brände schwächen Stahl aber stark, und der Ausfall einer kritischen Stütze kann eine Kettenreaktion auslösen. Ungewöhnlich ist nicht dasselbe wie unerklärbar.","prueffrage":"Welche Schäden hatte das Gebäude schon vor dem Einsturz, und welche davon wurden behoben, welche nicht?","rueckmeldung":[{"option":1,"text":"Ungewöhnlich war der Einsturz tatsächlich: Nach der US-Behörde NIST war es der erste bekannte Totaleinsturz eines Hochhauses vor allem durch Feuer. Selten heißt aber nicht unerklärbar, und die stundenlangen Brände erklären ihn ohne Sprengung."},{"option":2,"text":"Eine intakte Struktur schützt nicht vor Feuer: Erhitzter Stahl verliert stark an Tragfähigkeit, und sich ausdehnende Deckenträger können einen Querträger von seiner Auflage schieben, sodass einer Stütze der Halt fehlt."},{"option":3,"text":"Ein schneller Einsturz wirkt, als müsse vieles gleichzeitig nachgegeben haben. Fällt aber eine kritische Stütze aus, kann sich das Versagen als Kettenreaktion fortpflanzen; Ursachen an vielen Stellen zugleich braucht es dafür nicht."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"NIST: FAQs – NIST WTC 7 Investigation","oeffentlich":true,"url":"https://www.nist.gov/world-trade-center-investigation/study-faqs/wtc-7-investigation","abruf":"2026-10-12"},{"typ":"url","kurz":"NIST: FAQs – NIST WTC Towers Investigation (Festigkeitsverlust von Stahl)","oeffentlich":true,"url":"https://www.nist.gov/world-trade-center-investigation/study-faqs/wtc-towers-investigation","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"e3826ed63bb11655"}},{"id":"qx-c2-049","clusterId":"C","werkstueckRef":"C.5.4","stufe":3,"question":"Jemand sagt: „Das Dach von WTC 7 ist beim Einsturz im freien Fall gefallen. Das geht nur mit Sprengstoff, weil sonst jedes Stockwerk Widerstand geleistet hätte.“ Welche Prüfung klärt, ob das den Schluss auf eine Sprengung trägt?","options":["Du prüfst, ob der Freifall den ganzen Einsturz betraf oder nur einen Teilabschnitt, und ob dieser Abschnitt auch ohne Sprengstoff erklärbar ist.","Du prüfst, wie viele Zuschauer den Einsturz im Video als verdächtig empfinden, weil der Eindruck vieler Beobachter die Aussage der Messungen bestätigt.","Du prüfst, ob die Person selbst Bauingenieurin ist, weil ein fachfremder Einwand ohne Abschluss im Bauwesen von vornherein keine Beachtung verdient.","Du prüfst, ob sich der Einsturz im Video flüssig anfühlt, weil ein Fall ohne sichtbare Verzögerung nur durch eine Sprengung entstehen kann."],"correctIndex":0,"explanation":"Der Schluss „Freifall, also Sprengung“ setzt voraus, dass der Freifall den ganzen Einsturz betraf und nur durch Sprengstoff möglich ist. Beides lässt sich prüfen. Gemessen wurde: Die Dachlinie brauchte für 18 Stockwerke rund 5,4 Sekunden, im freien Fall wären es 3,9 Sekunden gewesen, also rund 40 Prozent länger. Nur die Nordfassade fiel etwa 2,25 Sekunden lang über rund acht Stockwerke mit Erdbeschleunigung. In dieser Phase trugen die zuvor ausgeknickten Außenstützen sie praktisch nicht mehr, es gab also kaum Widerstand. Ein kurzer Freifall-Abschnitt folgt damit schon aus einem Einsturz durch Feuer und beweist keinen Sprengstoff. Wer den Teilabschnitt zum ganzen Einsturz verallgemeinert und die einfachere Erklärung nicht prüft, schließt zu weit. Die anderen Wege prüfen nicht die Behauptung: Gefühl und Zahl der Zuschauer sagen nichts über den Vorgang, und der Beruf der Sprecherin entscheidet nicht über die Richtigkeit des Arguments.","coreRule":"⚡ Ein kurzer Freifall-Abschnitt ist kein Fingerabdruck für Sprengstoff: Prüfe, wie lange und woran er galt, bevor du auf die Ursache schließt.","beleg":"Werkstück C.5.4 (Kontext & Tiefe, Punkt 5); Fn. gl-c-wtc7-freifall (NIST 2008, NCSTAR 1A, S. 45 und 48)","status":"entwurf","scenario":"In einer Diskussion über den Einsturz von WTC 7 wird ein Videoclip gezeigt, in dem das Gebäude in wenigen Sekunden in sich zusammenfällt. Die Person behauptet, jeder Fall mit Erdbeschleunigung beweise, dass die Stützen vorher gezielt gesprengt wurden.","kurz":"Der Freifall betraf nur einen Teilabschnitt der Nordfassade, etwa 2,25 Sekunden lang. Dort trugen die ausgeknickten Stützen kaum noch, das erklärt ihn auch ohne Sprengstoff. Fehlerhaft ist, einen Teil zum ganzen Einsturz zu verallgemeinern.","prueffrage":"Wie lange dauerte der Einsturz der Dachlinie von WTC 7 laut Messung, und wie lange hätte ein freier Fall aus derselben Höhe gedauert?","rueckmeldung":[{"option":1,"text":"Viele Beobachter wirken wie ein Beleg, doch geteilte Eindrücke sind keine Messung. Ob der Fall verdächtig wirkt, sagt nichts darüber, was physikalisch geschah und ob es eine einfachere Erklärung gibt."},{"option":2,"text":"Fachwissen hilft beim Einordnen, ein Argument wird aber an seinen Belegen und seiner Logik geprüft, nicht an der Ausbildung der Person. Der Schluss selbst bleibt dabei ungeprüft."},{"option":3,"text":"Ein flüssiger Fall ohne sichtbare Verzögerung ist ein Eindruck, kein Messwert. Gerade die Behauptung „nur durch Sprengung“ ist unbelegt, denn ein kurzer Freifall-Abschnitt folgt schon, wenn tragende Stützen bereits ausgeknickt sind."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"NIST: FAQs – NIST WTC 7 Investigation","oeffentlich":true,"url":"https://www.nist.gov/world-trade-center-investigation/study-faqs/wtc-7-investigation","abruf":"2026-10-12"},{"typ":"doi","kurz":"NIST (2008): Final Report on the Collapse of World Trade Center Building 7 (NCSTAR 1A)","oeffentlich":true,"doi":"10.6028/NIST.NCSTAR.1a","seite":"45, 48"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"97bbe4427172ae84"}},{"id":"qx-c2-050","clusterId":"C","werkstueckRef":"C.5.5","stufe":1,"question":"In einer Doku heißt es: „Die Wikinger in Grönland starben aus, weil sie dekadent und weniger anpassungsfähig waren als die Inuit.“ Du kennst folgende Fakten: Die Siedlungen bestanden fast 500 Jahre, ihre Energiebilanz war von Anfang an knapp, ab dem späten 13. Jahrhundert wurde das Klima unberechenbarer, der Meeresspiegel stieg und überflutete Weideland, das Walrosselfenbein verlor seinen Markt und die Schiffe aus Norwegen blieben aus. Welche Beurteilung wird dem am besten gerecht?","options":["Die Erklärung ist unvollständig: Sie führt das Ende auf Charakter zurück, obwohl mehrere harte Umstände zugleich wirkten.","Die Erklärung stimmt im Kern: Wer fast 500 Jahre durchhält und dann verschwindet, hat offensichtlich mit der Zeit an Durchhaltevermögen verloren.","Die Erklärung ist widerlegt, weil ein einzelner Kälteeinbruch im 13. Jahrhundert die Siedlungen innerhalb weniger Jahre ausgelöscht hat.","Die Erklärung ist unbrauchbar, weil sich der Untergang einer Gesellschaft grundsätzlich nicht erklären lässt, wenn die Quellen so spärlich sind."],"correctIndex":0,"explanation":"Der Vorwurf der Dekadenz erklärt das Ende durch einen vermuteten Charakterzug, ohne die Umstände zu prüfen. Dabei lagen mehrere harte Faktoren gleichzeitig vor: Von Anfang an war die Energiebilanz knapp, das Vieh allein konnte die Höfe nicht ernähren. Ab dem späten 13. Jahrhundert wurde das Klima unberechenbarer (nach neueren Seesedimenten vor allem trockener; ob auch kälter, ist umstritten), der Meeresspiegel stieg, der Markt für Walrosselfenbein brach weg und die Schiffe blieben aus. Gegen eine Charakterschwäche spricht schon die Dauer: Fast 500 Jahre hielten die Siedlungen durch. Als viele Belastungen zugleich zuschlugen, reichten die Reserven einer kleinen, isolierten Gemeinschaft nicht mehr. Dass die Inuit überlebten, beweist keine überlegene Moral: Die Wikinger übernahmen etwa die Eisjagd der Inuit nie, blieben europäische Viehzüchter und waren schließlich verwundbar. Eine einzelne Ursache wie ein einziger Kälteeinbruch passt ebenfalls nicht zu den Fakten, denn mehrere Faktoren trafen zusammen. Und dass Quellen lückenhaft sind, heißt nicht, dass man gar nichts sagen kann: Man kann Erklärungen danach beurteilen, wie gut sie zu den bekannten Fakten passen.","coreRule":"⚡ Wer ein Scheitern mit einem Charakterfehler erklärt, ohne Umstände wie Energie, Klima und Handel zu prüfen, erklärt zu wenig.","beleg":"Werkstück C.5.5 (Die Wikinger in Grönland); Fn. gl-c-wikinger (Dugmore u. a. 2012, PNAS 109(10), S. 3658–3663); Fn. gl-c-davis (Janes in Hakluyt, Davis' erste Reise 1585)","status":"entwurf","scenario":"","kurz":"Die Doku führt das Ende auf einen vermuteten Charakterzug zurück, obwohl mehrere harte Umstände zusammentrafen: knappe Energiebilanz, unberechenbares Klima, steigendes Meer, verlorener Elfenbeinmarkt, ausbleibende Schiffe. Fast 500 Jahre Durchhalten sprechen zudem gegen Schwäche.","prueffrage":"Was müsste man über Menschen wissen, um sie dekadent zu nennen, und welche der bekannten Tatsachen sagen überhaupt etwas über ihr Verhalten?","rueckmeldung":[{"option":1,"text":"Dass die Siedlungen nach so langer Zeit verschwanden, wirkt wie ein Zeichen nachlassender Kraft. Doch fast 500 Jahre Durchhalten sprechen gegen eine Charakterschwäche, und das Ende selbst nennt keinen Grund: Dafür kommen die harten Umstände in Frage."},{"option":2,"text":"Das Klima wurde tatsächlich unberechenbarer, doch kein einzelner Kälteeinbruch löschte die Siedlungen in wenigen Jahren aus. Mehrere Belastungen trafen zusammen, und ob es überhaupt kälter wurde, ist umstritten."},{"option":3,"text":"Die Quellen sind tatsächlich lückenhaft, das stimmt. Daraus folgt aber nicht, dass sich nichts sagen lässt: Man kann Erklärungen danach beurteilen, wie gut sie zu den bekannten Fakten passen, und die Dekadenz-These passt schlecht dazu."}],"familie":"umstaende-vor-absicht","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Dugmore, A. J. u. a. (2012): Cultural adaptation, compounding vulnerabilities and conjunctures in Norse Greenland. PNAS 109(10), 3658–3663","oeffentlich":true,"doi":"10.1073/pnas.1115292109","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3309771/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Zhao, B. u. a. (2022): Prolonged drying trend coincident with the demise of Norse settlement in southern Greenland. Science Advances 8(12), eabm4346","oeffentlich":true,"doi":"10.1126/sciadv.abm4346","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8942370/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Borreggine, M. u. a. (2023): Sea-level rise in Southwest Greenland as a contributor to Viking abandonment. PNAS 120(17), e2209615120","oeffentlich":true,"doi":"10.1073/pnas.2209615120","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10151458/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"0b399156719441dc"}},{"id":"qx-c2-051","clusterId":"C","werkstueckRef":"C.5.5","stufe":2,"question":"Wie lässt sich am besten erklären, dass die Wikinger in Grönland nach fast 500 Jahren verschwanden, die Inuit aber überlebten?","options":["Sie passten sich nur teilweise an: Die Winterjagd der Nachbarn übernahmen sie nie, daher fehlten bei mehreren Belastungen die Reserven.","Sie passten sich gar nicht an: Sie änderten ihre Ernährung nie, daher löschte allein das Klima sie aus.","Sie waren durch Müßiggang geschwächt, während die Nachbarn härter arbeiteten, daher erklärt der Charakterunterschied ihr Verschwinden.","Sie ahmten die Nachbarn vollständig nach und gaben die Viehzucht auf, daher machte gerade diese Angleichung sie verwundbar."],"correctIndex":0,"explanation":"Die Siedler waren keine Verlierer durch Dekadenz oder Unfähigkeit. Sie haben sich durchaus angepasst: Sie stellten auf gemeinschaftliche Robbenjagd um, und der Meeresanteil in ihren Knochen stieg im Lauf der Jahrhunderte von rund 40 auf rund 80 Prozent. Zugleich blieben sie Viehzüchter mit Höfen, Ställen und Steinkirchen, und die Eisjagd der Nachbarn, die Robben auch im Winter erreichbar machte, übernahmen sie nie. Ihre Energiebilanz war von Anfang an knapp. Als ab dem späten 13. Jahrhundert Klima, Meeresspiegel und Handel zugleich gegen sie liefen, reichten die Reserven einer kleinen, isolierten Gemeinschaft nicht mehr. Die Geografie setzte die Grenzen, aber die Kultur entschied mit, welche Anpassung die Siedler vollzogen und welche nicht. Wer nur die Umwelt oder nur den Charakter als Ursache nimmt, übersieht dieses Zusammenspiel.","coreRule":"⚡ Die Umwelt setzt die Grenzen, aber die Kultur entscheidet mit, welche Anpassung gelingt.","beleg":"Werkstück C.5.5 (Die Wikinger in Grönland; Der Kipppunkt); Fn. gl-c-wikinger (Dugmore u. a. 2012, PNAS 109(10), S. 3659–3662)","status":"entwurf","scenario":"Eine Siedlergemeinschaft aus Europa lebt rund 500 Jahre in der Arktis. Sie hält Vieh, baut Höfe und Steinkirchen und ist auf Heu angewiesen. Sie stellt auf gemeinschaftliche Robbenjagd um, bleibt dabei aber europäische Viehzüchterin. Als das Klima unberechenbarer wird, Küstenweiden überflutet werden, ihr wichtigstes Handelsgut seinen Markt verliert und die Schiffe ausbleiben, bricht die Siedlung zusammen. Ein Volk, das die Robben auch im Winter an Atemlöchern und Eiskanten jagt, lebt im selben Land weiter.","kurz":"Die Siedler passten sich durchaus an, übernahmen aber nie die Winterjagd der Nachbarn. Als Klima, Meeresspiegel und Handel zugleich kippten, fehlten die Reserven. Wer nur Umwelt oder nur Charakter anführt, übersieht dieses Zusammenspiel.","prueffrage":"Was änderten die Siedler im Lauf der Zeit an ihrer Nahrungssuche, und hielten sie danach weiter Vieh?","rueckmeldung":[{"option":1,"text":"Dass das Klima unberechenbarer wurde, stimmt, und das macht die Erklärung bequem. Doch die Siedler änderten ihre Ernährung sehr wohl: Der Meeresanteil in ihren Knochen stieg von rund 40 auf rund 80 Prozent. Zudem wirkten Meeresspiegel und Handel mit."},{"option":2,"text":"Ein Charakterunterschied wäre eine einfache Erklärung, doch dafür gibt es keinen Beleg: Die Siedler stellten auf gemeinschaftliche Robbenjagd um und hielten Jahrhunderte durch. Entscheidend war, welche Anpassung sie vollzogen und welche nicht."},{"option":3,"text":"Die Siedler gaben die Viehzucht nie auf, sondern blieben Viehzüchter mit Höfen und Steinkirchen, und die Winterjagd der Nachbarn übernahmen sie gerade nicht. Verwundbar machte sie also nicht zu viel, sondern zu wenig Angleichung."}],"familie":"monokausal-erkennen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Dugmore, A. J. u. a. (2012): Cultural adaptation, compounding vulnerabilities and conjunctures in Norse Greenland. PNAS 109(10), 3658–3663","oeffentlich":true,"doi":"10.1073/pnas.1115292109","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3309771/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"b4506db20f6c25d9"}},{"id":"qx-c2-052","clusterId":"C","werkstueckRef":"C.5.5","stufe":3,"question":"Ein Artikel behauptet: „Die Menschheit hat Holz durch Kohle, Kohle durch Öl und Öl nun durch Sonne und Wind ersetzt. Jede Stufe ist dichter und leistungsfähiger als die vorige.“ Was ist an dieser Behauptung fehlerhaft?","options":["Sie unterstellt, dass neue Energieträger die alten abgelöst haben, und sie ordnet Sonne und Wind zu Unrecht in eine Reihe wachsender Energiedichte ein.","Sie unterstellt, dass jeder Wechsel des Energieträgers die Bevölkerung vergrößert hat, und sie ordnet Holz zu Unrecht als frühesten Energieträger ein.","Sie unterstellt, dass die Energiedichte eines Trägers über seine Verbreitung entscheidet, und sie ordnet Öl zu Unrecht als dichtesten Träger ein.","Sie unterstellt, dass fossile Energieträger die Industrialisierung ausgelöst haben, und sie ordnet Kohle zu Unrecht vor dem Öl ein."],"correctIndex":0,"explanation":"Zwei Denkfehler stecken in der Behauptung. Erstens: Neue Energieträger sind meist hinzugekommen, statt alte zu ersetzen; Biomasse dominierte bis weit ins 19. Jahrhundert, und Kohle, Öl und Gas wurden dazugenommen, nicht eingetauscht. Zweitens: Die Reihe „immer dichter“ bricht beim letzten Glied, denn Sonnenstrahlung und Wind haben eine viel geringere Energiedichte als Kohle oder Öl. Die übrigen Antworten nennen Fehler, die so nicht vorliegen: Über Bevölkerung, Industrialisierung oder Verbreitung sagt die Behauptung nichts, Holz war früh wichtig, und Kohle kam vor dem Öl. Auch setzt sie Öl nicht an die Spitze der Reihe, sondern Sonne und Wind.","coreRule":"⚡ Energiestufen addieren sich, sie ersetzen sich nicht – und nicht jedes Glied einer Reihe passt ins Muster.","beleg":"Werkstück C.5.5 (Kontext & Tiefe, Energie ist die Währung des Fortschritts); Fn. gl-c-energiestufen (Schabbach/Wesselak 2012, S. 56, 69 und 113–114)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Neue Energieträger kamen meist hinzu, statt alte abzulösen: Biomasse dominierte bis weit ins 19. Jahrhundert, Kohle und Öl wurden dazugenommen. Und die Reihe „immer dichter“ bricht bei Sonne und Wind, die nur eine geringe Energiedichte haben.","prueffrage":"Welche Aussagen macht der Artikel wörtlich, und welche davon ließen sich mit Verbrauchszahlen oder Messwerten nachprüfen?","rueckmeldung":[{"option":1,"text":"Dass Energie und Bevölkerung zusammenhängen, liegt nahe. Die Behauptung sagt darüber aber nichts, und Holz gehörte tatsächlich zu den frühesten Energieträgern. So wird ein Fehler genannt, der in der Aussage gar nicht steckt."},{"option":2,"text":"Die Energiedichte ist durchaus der Maßstab der Reihe, doch dass sie über die Verbreitung entscheide, sagt der Artikel nicht. Öl nennt er auch nicht den dichtesten Träger: An die Spitze setzt er Sonne und Wind."},{"option":3,"text":"Dass Kohle die Industrialisierung antrieb, ist bekannt und wirkt deshalb vertraut. Der Artikel sagt darüber aber nichts, und seine Reihenfolge stimmt: Kohle kam tatsächlich vor dem Öl. Beides ist also kein Fehler der Aussage."}],"familie":"schluss-pruefen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Our World in Data: Ritchie, H. (2021): How have the world’s energy sources changed over the last two centuries?","oeffentlich":true,"url":"https://ourworldindata.org/global-energy-200-years","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Schabbach, T.; Wesselak, V. (2012): Energie. Die Zukunft wird erneuerbar. Berlin/Heidelberg: Springer","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"568e0a34da4d2c8c"}},{"id":"qx-c2-053","clusterId":"C","werkstueckRef":"C.5.5","stufe":4,"question":"Jemand sagt: „Die Geografie erklärt, warum manche Länder heute reich und andere arm sind. Eurasien hatte Weizen, Rinder und Pferde, Amerika hatte das nicht.“ Als Gegenargument wird angeführt: Zur Zeit der Eroberung verdiente ein Spanier wahrscheinlich weniger als das Doppelte eines Bewohners des Inkareichs, heute ist der durchschnittliche Spanier über sechsmal so reich wie der durchschnittliche Peruaner. Was folgt aus diesem Zahlenvergleich?","options":["Die Geografie spielt für die Geschichte keine Rolle, weil der Vorsprung Eurasiens allein auf reinem Zufall beruhte.","Kulturelle Überlegenheit erklärt die Unterschiede besser, weil Institutionen aus den Wertvorstellungen einer Gesellschaft folgen.","Die Geografie ist damit widerlegt, weil die Einkommen schon zur Zeit der Eroberung weit auseinanderlagen.","Die Geografie erklärt den frühen Vorsprung, nicht aber die später wachsende Kluft; dafür braucht es weitere Faktoren wie Institutionen."],"correctIndex":3,"explanation":"Der Abstand wuchs von weniger als dem Doppelten auf über das Sechsfache. Laut Acemoglu und Robinson liefert Diamonds Geografie-These einen plausiblen Ansatz für den Vorsprung Eurasiens zu Beginn der Neuzeit, erklärt aber nicht, warum sich der Abstand später immer weiter öffnete. Daraus folgt nicht, dass die Geografie keine Rolle spielt: Sie kann den Start erklären, etwa durch domestizierbare Pflanzen und Tiere in Eurasien. Der spätere Abstand verlangt zusätzliche Faktoren. Acemoglu und Robinson sehen sie in Institutionen, also Regeln, die Eigentum sichern, Neuerungen belohnen und die Mehrheit am Wirtschaftsleben beteiligen, oder solchen, mit denen Herrschende auf Kosten der Übrigen Gewinn ziehen. Diese Regeln entstehen in politischen Prozessen und sind kein vorherbestimmtes Ergebnis der Geografie; sie folgen auch nicht einfach aus den Wertvorstellungen einer Gesellschaft. Auch die anderen Antworten halten nicht: Dass die Einkommen zur Zeit der Eroberung noch nahe beieinanderlagen, widerlegt die Geografie als Erklärung des Starts nicht. Und eine rein kulturelle Erklärung wird durch den Zahlenvergleich nicht belegt.","coreRule":"⚡ Ein Faktor, der gleich bleibt, erklärt keine wachsende Kluft allein: Geografie erklärt oft den Start, Institutionen und andere Entscheidungen den späteren Abstand.","beleg":"Werkstück C.5.5 (Der Kipppunkt); Fn. gl-c-acemoglu (Acemoglu/Robinson 2013, Kap. 2, Abschnitt „Die Geographie-Hypothese“)","status":"entwurf","scenario":"","kurz":"Der Abstand wuchs von weniger als dem Doppelten auf über das Sechsfache. Die Geografie kann den Start erklären, nicht aber diese Öffnung; dafür braucht es weitere Faktoren wie Institutionen. Wer sie deshalb ganz verwirft, schließt zu weit.","prueffrage":"Was zeigt der Zahlenvergleich über den Abstand zwischen beiden Gruppen zu den zwei Zeitpunkten, und was zeigt er nicht?","rueckmeldung":[{"option":0,"text":"Dass die Geografie nicht alles erklärt, stimmt. Daraus folgt aber nicht, dass sie keine Rolle spielt: Domestizierbare Pflanzen und Tiere erklären plausibel den frühen Vorsprung, und der war damit kein bloßer Zufall."},{"option":1,"text":"Institutionen spielen durchaus eine Rolle. Der Zahlenvergleich belegt aber keine kulturelle Erklärung, und Institutionen folgen nicht einfach aus Wertvorstellungen, sondern entstehen in politischen Prozessen."},{"option":2,"text":"Der Satz dreht die Zahlen um: Zur Zeit der Eroberung lagen die Einkommen nahe beieinander, erst später öffnete sich die Kluft. Selbst große Unterschiede damals würden die Geografie als Erklärung des Starts nicht widerlegen."}],"familie":"monokausal-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Nobel Prize Outreach: Popular information – The Prize in Economic Sciences 2024","oeffentlich":true,"url":"https://www.nobelprize.org/prizes/economic-sciences/2024/popular-information/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Acemoglu, D.; Robinson, J. A. (2013): Warum Nationen scheitern. Frankfurt a. M.: S. Fischer, Kap. 2 „Die Geographie-Hypothese“","oeffentlich":false}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"a830428dd3bd9c4e"}},{"id":"qx-c2-054","clusterId":"C","werkstueckRef":"C.5.6","stufe":1,"question":"Eine Dokumentation zeigt: Eine ältere Frau ist in ihrem Wohnzimmer fast vollständig verbrannt, der Sessel ist zerstört, der Rest des Raumes kaum beschädigt. Im Film heißt es: „Es gab keine erkennbare Zündquelle, also muss sich die Frau von selbst entzündet haben.“ Welche Prüfung ist als Erstes sinnvoll?","options":["Prüfen, ob in Reichweite der Frau eine alltägliche Zündquelle wie Zigarette, Kerze oder Kamin stand und ob sie nur eingeschränkt beweglich war.","Prüfen, ob sich im Raum brennbare Gase gebildet haben, die den Brand binnen Minuten ausgelöst und die Frau erfasst haben könnten.","Prüfen, ob die Frau zuvor Alkohol getrunken hat, da dieser sich im Körperinneren entzünden und das Feuer von innen auslösen kann.","Prüfen, ob ein Blitzschlag oder Kurzschluss den Brand ausgelöst hat, da sonst auch die übrigen Möbel im Raum verbrannt wären."],"correctIndex":0,"explanation":"Aus „Ich sehe keine offensichtliche Ursache“ folgt nicht „Es gab keine Ursache“. Ein umgekippter Aschenbecher oder eine heruntergefallene Kerze reicht bereits. Die geringe Zerstörung der Umgebung spricht auch nicht gegen ein gewöhnliches Feuer: Wenn eine äußere Flamme die Haut einige Minuten erhitzt, brennt das schmelzende Unterhautfett im verkohlten Gerüst aus Haut und Kleidung wie bei einer umgedrehten Kerze über Stunden mit kleinen Flammen weiter. So wird der Körper stark zerstört, der Raum kaum. Ein Versuch von DeHaan und Nurbakhsh (2001) mit einem rund 95 Kilogramm schweren Schweinekadaver in einer Baumwolldecke zeigte genau das: Das Feuer hielt sich über 6,5 Stunden selbst am Leben. Erst die systematische Prüfung von Zündquelle, Brennstoff (Unterhautfett) und Beweglichkeit der Person zeigt, ob der Fall zum bekannten Dochteffekt-Muster passt, bevor man eine übernatürliche Erklärung erwägt.","coreRule":"⚡ „Keine offensichtliche Zündquelle“ heißt nicht „keine Zündquelle“: Erst suchen, dann „unerklärlich“ sagen.","beleg":"Werkstück C.5.6 (Kontext & Tiefe; Anwendung & Relevanz, Bei „spontaner menschlicher Selbstentzündung“)","status":"entwurf","scenario":"Ein Bekannter erzählt dir von einer Dokumentation und hält den Fall für ein Beispiel „spontaner Selbstentzündung“.","kurz":"Dass keine Zündquelle zu sehen ist, heißt nicht, dass es keine gab: Eine Kerze oder Zigarette kann ein Feuer in Gang bringen, das den Körper über Stunden zerstört und den Raum kaum. Zuerst gehören die alltäglichen Zündquellen und die Beweglichkeit der Frau geprüft.","prueffrage":"Was zeigen die Aufnahmen vom Tisch und vom Boden neben dem Sessel, und was weiß man über die Gewohnheiten der Frau?","rueckmeldung":[{"option":1,"text":"Gase könnten tatsächlich ein Feuer auslösen. Sie würden aber den ganzen Raum erfassen, nicht fast nur eine Person und einen Sessel, und im Fall gibt es keinen Hinweis darauf. Zuerst gehören die naheliegenden Quellen in Reichweite der Frau geprüft."},{"option":2,"text":"Alkohol kann träge machen und so die Beweglichkeit einschränken. Er entzündet sich aber nicht im Körper, denn die Menge im Blut ist viel zu gering, um zu brennen. Als Ursache von innen trägt das nicht."},{"option":3,"text":"Eine äußere Zündquelle zu suchen ist richtig, die Begründung trägt aber nicht: Ein angezündeter Körper kann stundenlang mit kleinen Flammen brennen, während der Raum fast unversehrt bleibt. Kerze oder Zigarette liegen zudem näher als ein Blitz."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"DeHaan, J. D.; Nurbakhsh, S. (2001): Sustained Combustion of an Animal Carcass … J Forensic Sci 46(5):1076–1081 – PubMed-Abstract","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/11569545/","abruf":"2026-10-12"},{"typ":"doi","kurz":"DeHaan, J. D.; Nurbakhsh, S. (2001): Sustained Combustion of an Animal Carcass … J Forensic Sci 46(5) (Volltext kostenpflichtig)","oeffentlich":false,"doi":"10.1520/JFS15101J"},{"typ":"url","kurz":"Christensen, A. M. (2000): Debunking the Spontaneous Human Combustion Myth. Masterarbeit, University of Tennessee (TRACE)","oeffentlich":true,"url":"https://trace.tennessee.edu/utk_gradthes/4133","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"e19394ce0b93a391"}},{"id":"qx-c2-055","clusterId":"C","werkstueckRef":"C.5.6","stufe":2,"question":"Welche Erklärung ist die sparsamste, und was würdest du zuerst prüfen?","scenario":"Nach einem Wohnungsbrand sagt ein Gutachter: Der Rumpf der Person sei fast vollständig verbrannt, Arme, Beine und Kopf dagegen vergleichsweise unversehrt. Im Raum selbst gibt es nur mäßige Brandschäden. Ein Bekannter meint: „Wenn der Körper so ungleichmäßig brennt, muss ein besonderer Brandbeschleuniger im Spiel gewesen sein.“","options":["Der Rumpf hat viel Unterhautfett, das schmilzt, von verkohlter Haut und Kleidung aufgesaugt wird und langsam weiterbrennt. Prüfen: Zündquelle, Kleidung, Fettanteil.","Kopf und Gliedmaßen sind stärker durchblutet, das Blut schützt sie vor der Hitze, während der Rumpf ungeschützt brennt. Prüfen: Durchblutung, Kreislauf, Körpertemperatur.","Die Flammen sammeln sich an der Körpermitte, weil Brandbeschleuniger dort in die Kleidung eindringen und haften. Prüfen: Kleidungsreste, Rückstände, Brandspuren.","Der Rumpf entzündet sich zuerst, weil dort die Körpertemperatur am höchsten ist, und der Rest brennt später nach. Prüfen: Körpertemperatur, Brandverlauf, Zeitablauf."],"correctIndex":0,"explanation":"Ungleichmäßige Zerstörung ist kein Beweis für einen Brandbeschleuniger. Sie ist genau das, was die bekannte Verbrennungsphysik vorhersagt: Brennstoff ist das Unterhautfett, das durch Hitze schmilzt und von verkohlter Haut und Kleidung wie von einem Docht aufgesogen wird. So brennt es langsam mit niedrigen Flammen, ähnlich einer Öllampe, und die Umgebung bleibt vergleichsweise geschont. Arme, Beine und Kopf haben meist weniger Fett als der Rumpf und liefern diesem Docht-Feuer deshalb weniger Brennstoff. Experimente an einem rund 95 Kilogramm schweren Schweinekadaver in einer Baumwolldecke zeigten, dass sich ein solches Feuer über mehr als 6,5 Stunden selbst am Leben hielt, bis die Forscher es löschten, nachdem eine äußere Flamme es einmal entzündet hatte. Die sparsamste Erklärung ist daher die, die ohne zusätzliche Annahme auskommt, und sie lässt sich an Zündquelle, Kleidung und Fettverteilung überprüfen. Dass ein Brandbeschleuniger hier nichts erklärt, heißt nicht, dass er ausgeschlossen ist: Würden Spuren davon gefunden, änderte das die Lage.","coreRule":"⚡ Wo das Fett sitzt, brennt der Docht weiter.","beleg":"Werkstück C.5.6 (Anwendung & Relevanz, In der Forensik allgemein)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Ungleichmäßiges Brennen beweist keinen Brandbeschleuniger: Das Unterhautfett des Rumpfes brennt langsam weiter, aufgesogen von verkohlter Haut und Kleidung wie von einem Docht. Der Schluss „ungewöhnlich, also besonderer Anlass“ übersieht die einfachere Erklärung.","prueffrage":"Welche Körperteile sind stark verbrannt, welche kaum, und worin unterscheiden sie sich außer in ihrer Lage?","rueckmeldung":[{"option":1,"text":"Dass Kopf und Gliedmaßen weniger zerstört sind, stimmt. Das liegt aber nicht an Blut als Hitzeschutz, sondern daran, dass dort weniger Fett sitzt, das als Brennstoff dienen könnte."},{"option":2,"text":"Ein Brandbeschleuniger ist eine zusätzliche Annahme, und das Brandmuster allein belegt ihn nicht, denn das brennende Körperfett erklärt es schon. Rückstände zu suchen bleibt sinnvoll; fänden sich welche, änderte das die Lage."},{"option":3,"text":"Die Körpertemperatur liegt weit unter dem, was etwas entzündet, und erklärt kein Brandmuster. Maßgeblich ist, woher das Feuer seinen Brennstoff bezieht, nicht, wo es zuerst wärmer war."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"DeHaan, J. D.; Nurbakhsh, S. (2001): Sustained Combustion of an Animal Carcass … J Forensic Sci 46(5):1076–1081 – PubMed-Abstract","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/11569545/","abruf":"2026-10-12"},{"typ":"doi","kurz":"DeHaan, J. D.; Nurbakhsh, S. (2001): Sustained Combustion of an Animal Carcass … J Forensic Sci 46(5) (Volltext kostenpflichtig)","oeffentlich":false,"doi":"10.1520/JFS15101J"},{"typ":"url","kurz":"Christensen, A. M. (2000): Debunking the Spontaneous Human Combustion Myth. Masterarbeit, University of Tennessee (TRACE)","oeffentlich":true,"url":"https://trace.tennessee.edu/utk_gradthes/4133","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"7953f46d01448f01"}},{"id":"qx-c2-056","clusterId":"C","werkstueckRef":"C.5.6","stufe":3,"question":"Welche Folge ist bei diesem Vorgehen am wahrscheinlichsten und warum problematisch?","scenario":"Bei den Ermittlungen zu einem Brandtod liegt ein fast völlig verbrannter Körper in einem kaum beschädigten Zimmer. Ein Ermittler sieht keine offensichtliche Zündquelle und schreibt „unerklärlich“ in den Bericht.","options":["Die Unversehrtheit des Zimmers wird als Hinweis auf Brandstiftung gewertet, obwohl sie stets gegen einen Unfall spricht.","Ein echter Zündvorgang, etwa ein Unfall oder eine Tat, kann unentdeckt bleiben, weil die Ursachensuche vorzeitig endet.","Die Beweislast kehrt sich um: Nur wer eine Selbstentzündung widerlegt, darf sie als Ursache ausschließen und weiterermitteln.","Der Fall bleibt ungelöst, obwohl solche Fälle erfahrungsgemäß immer auf eine Straftat zurückgehen."],"correctIndex":1,"explanation":"Der Schluss „Ich sehe keine offensichtliche Ursache, also gab es keine“ ist ein Fehlschluss: Dass etwas nicht sofort erkennbar ist, heißt nicht, dass es nicht existiert. Zudem ist die Unversehrtheit der Umgebung kein Beweis gegen ein gewöhnliches Feuer. Brandversuche (DeHaan und Nurbakhsh, 2001) zeigten, dass ein in eine Baumwolldecke gewickelter Schweinekadaver, gewählt als Ersatz für einen menschlichen Körper, sich über mehr als 6,5 Stunden selbst am Leben erhaltend verbrannte, mit der Decke als Docht und dem Körperfett als Brennstoff. Wer vorschnell „unerklärlich“ schreibt, prüft nicht mehr, ob in Reichweite eine Zigarette, Kerze oder ein Kamin stand und ob der Körper genug Fett als Brennstoff hatte. So kann ein Unfall oder eine Tat übersehen werden.","coreRule":"⚡ „Keine offensichtliche Zündquelle“ ist nicht „keine Zündquelle“.","quote":"","quoteLabel":"","beleg":"Werkstück C.5.6 (Anwendung & Relevanz; Red Flags; Der Kipppunkt; Das Anti-Denkmuster)","status":"entwurf","kurz":"Wer „unerklärlich“ schreibt, hört auf zu suchen, und eine echte Ursache kann übersehen werden. Dass man keine Zündquelle sofort sieht, heißt nicht, dass es keine gab; auch ein gewöhnliches Feuer kann einen solchen Befund hinterlassen.","prueffrage":"Welche alltäglichen Zündquellen kämen in einem Wohnzimmer infrage, und welche davon hinterlassen nach einem Brand kaum Spuren?","rueckmeldung":[{"option":0,"text":"Ein unversehrtes Zimmer wirkt zunächst auffällig und lädt zu Verdacht ein. Es ist aber weder ein Beleg für Brandstiftung noch spricht es „stets“ gegen einen Unfall; ein gewöhnliches Feuer kann genau so aussehen."},{"option":2,"text":"Eine Umkehr der Beweislast wäre tatsächlich ein Problem, doch der Ermittler verlangt keine Widerlegung einer Selbstentzündung, er bricht die Suche einfach ab. Die wahrscheinliche Folge ist, dass eine echte Ursache unentdeckt bleibt."},{"option":3,"text":"Dass der Fall ohne weitere Prüfung ungeklärt bleibt, stimmt. Aber „immer eine Straftat“ ist eine Behauptung, die nicht trägt: Ebenso kommen Unfälle in Frage, etwa durch Zigarette, Kerze oder Kamin."}],"familie":"bekannte-ursache-zuerst","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"DeHaan, J. D.; Nurbakhsh, S. (2001): Sustained Combustion of an Animal Carcass … J Forensic Sci 46(5):1076–1081 – PubMed-Abstract","oeffentlich":true,"url":"https://pubmed.ncbi.nlm.nih.gov/11569545/","abruf":"2026-10-12"},{"typ":"doi","kurz":"DeHaan, J. D.; Nurbakhsh, S. (2001): Sustained Combustion of an Animal Carcass … J Forensic Sci 46(5) (Volltext kostenpflichtig)","oeffentlich":false,"doi":"10.1520/JFS15101J"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"8d7d8f42ba78fe79"}}]`);export{t as n,n as t};